INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牌子是一块小板子，上面写着字，告诉大家一件事。", "primary_collocate": null, "pronunciation": "pái zi", "ipa": "pʰaɪ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "门口挂着一块牌子。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牌子上写着“请安静”。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举着牌子站在路边。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块牌子是红色的。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把牌子挂在了门上。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牌子上的字很大，我看清了。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的牌子写着“小心”。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在牌子下面等朋友。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风把牌子吹倒了。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块牌子太旧，字都看不清。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "写着字的小板子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牌子", "is_correct": true, "explanation": "牌子 páizi：本词，指写着字的小板子。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子 pāizi（第一声）与 pái（第二声）声调不同，意思是节拍。"}, {"text": "盘子", "is_correct": false, "explanation": "盘子 pánzi 与 pái 韵母不同（-an 与 -ai），意思是碟子。"}, {"text": "台子", "is_correct": false, "explanation": "台子 táizi 与 pái 声母不同（t 与 p），意思是桌子。"}, {"text": "白子", "is_correct": false, "explanation": "白子 báizi 与 pái 声母不同（b 与 p），意思是白色的棋子。"}], "explanations": {"牌子": "牌子 páizi：本词，指写着字的小板子。", "拍子": "拍子 pāizi（第一声）与 pái（第二声）声调不同，意思是节拍。", "盘子": "盘子 pánzi 与 pái 韵母不同（-an 与 -ai），意思是碟子。", "台子": "台子 táizi 与 pái 声母不同（t 与 p），意思是桌子。", "白子": "白子 báizi 与 pái 声母不同（b 与 p），意思是白色的棋子。"}, "sentence_index": null, "correct_answer": "牌子"}, "level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "搭配：“挂”一般搭配招牌、画等，不说“挂着一块面包”。"}, {"text": "牌子", "is_correct": true, "explanation": "牌子：挂在门口写着字的板子，与句意相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不会挂在门口。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不能挂在门口当标志。"}], "explanations": {"面包": "搭配：“挂”一般搭配招牌、画等，不说“挂着一块面包”。", "牌子": "牌子：挂在门口写着字的板子，与句意相符。", "蛋糕": "语义：蛋糕是食物，不会挂在门口。", "白菜": "语义：白菜是蔬菜，不能挂在门口当标志。"}, "sentence_index": 0, "correct_answer": "牌子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用牌子切菜。", "explanation": "这里应该用〈刀〉。牌子是写字的板子，不能用来切菜。"}, {"text": "他饿了，吃了一块牌子。", "explanation": "这里应该用〈饼干〉。牌子是挂着写字的板子，不能吃。"}, {"text": "这块牌子考上了大学。", "explanation": "这里应该用〈学生〉。牌子不是人，不能考大学，只有人能考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88881, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牌子", "is_correct": true, "explanation": "牌子 páizi：本词，指写着字的小板子。"}, {"text": "孩子", "is_correct": false, "explanation": "孩子 háizi 与 pái 声母不同（h 与 p），意思是小孩。"}, {"text": "才子", "is_correct": false, "explanation": "才子 cáizi 与 pái 声母不同（c 与 p），意思是有才华的人。"}, {"text": "宅子", "is_correct": false, "explanation": "宅子 zháizi 与 pái 声母不同（zh 与 p），意思是住宅。"}, {"text": "摆子", "is_correct": false, "explanation": "摆子 bǎizi（第三声）与 pái（第二声）声调不同，意思是疟疾引起的寒热发作。"}], "explanations": {"牌子": "牌子 páizi：本词，指写着字的小板子。", "孩子": "孩子 háizi 与 pái 声母不同（h 与 p），意思是小孩。", "才子": "才子 cáizi 与 pái 声母不同（c 与 p），意思是有才华的人。", "宅子": "宅子 zháizi 与 pái 声母不同（zh 与 p），意思是住宅。", "摆子": "摆子 bǎizi（第三声）与 pái（第二声）声调不同，意思是疟疾引起的寒热发作。"}, "sentence_index": null, "correct_answer": "牌子"}, "level_3": {"options": [{"text": "花", "is_correct": false, "explanation": "语义：花不会写字，不能说“路边的花写着“小心””。"}, {"text": "牌子", "is_correct": true, "explanation": "牌子：路边写着提示的板子，与句意相符。"}, {"text": "风", "is_correct": false, "explanation": "搭配：“写着”的主语要是能写字的物体，“风”不搭配“写着”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是实物，不能写字。"}], "explanations": {"花": "语义：花不会写字，不能说“路边的花写着“小心””。", "牌子": "牌子：路边写着提示的板子，与句意相符。", "风": "搭配：“写着”的主语要是能写字的物体，“风”不搭配“写着”。", "影子": "语义：影子不是实物，不能写字。"}, "sentence_index": 6, "correct_answer": "牌子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "浴室里挂着一块牌子，可以用来照脸。", "explanation": "这里应该用〈镜子〉。牌子是写字的板子，不能用来照脸。"}, {"text": "下雨了，他撑开牌子走了。", "explanation": "这里应该用〈雨伞〉。“撑开”用于雨伞，牌子不能撑开。"}, {"text": "他拿着牌子扫地。", "explanation": "这里应该用〈扫帚〉。“扫地”要用扫帚，牌子不能用来扫地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店门口挂着一只牌子，写着营业时间。", "corrected_sentence": "店门口挂着一块牌子，写着营业时间。", "error_description": "“牌子”的量词应用“块”。“只”用于动物，不能用于牌子，应改为「一块牌子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店门口得牌子上印着营业时间。", "corrected_sentence": "店门口的牌子上印着营业时间。", "error_description": "“牌子”前面的修饰关系要用“的”，不能用“得”。“得”用在动词或形容词后，应改为「店门口的牌子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
