INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商品的品牌，即产品所用的商标或品牌名称。", "primary_collocate": null, "pronunciation": "pái zi", "ipa": "pʰaɪ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这个牌子的鞋很舒服。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢哪个牌子的手机？", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个老牌子，很多人都知道。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只买这个牌子的牛奶。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个牌子的衣服价钱不一样。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好牌子的东西一般比较贵。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈常用这个牌子的洗发水。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新牌子没有名气，卖得不太好。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的汽车很安全。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换个牌子试试吧。", "target_word": "牌子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "口语", "sense_fingerprint": "商品的品牌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牌子", "is_correct": true, "explanation": "牌子 páizi：本词，指商品的品牌。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子 pāizi（第一声）与 pái（第二声）声调不同，意思是节拍。"}, {"text": "盘子", "is_correct": false, "explanation": "盘子 pánzi 与 pái 韵母不同（-an 与 -ai），意思是碟子。"}, {"text": "台子", "is_correct": false, "explanation": "台子 táizi 与 pái 声母不同（t 与 p），意思是桌子。"}, {"text": "白子", "is_correct": false, "explanation": "白子 báizi 与 pái 声母不同（b 与 p），意思是白色的棋子。"}], "explanations": {"牌子": "牌子 páizi：本词，指商品的品牌。", "拍子": "拍子 pāizi（第一声）与 pái（第二声）声调不同，意思是节拍。", "盘子": "盘子 pánzi 与 pái 韵母不同（-an 与 -ai），意思是碟子。", "台子": "台子 táizi 与 pái 声母不同（t 与 p），意思是桌子。", "白子": "白子 báizi 与 pái 声母不同（b 与 p），意思是白色的棋子。"}, "sentence_index": null, "correct_answer": "牌子"}, "level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "搭配：“的鞋”前面要说品牌或款式，不说“面包的鞋”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是鞋的来源，“桌子的鞋”说不通。"}, {"text": "牌子", "is_correct": true, "explanation": "牌子：商品的品牌，修饰“鞋”，句意合理。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不生产鞋，“月亮的鞋”没有意义。"}], "explanations": {"面包": "搭配：“的鞋”前面要说品牌或款式，不说“面包的鞋”。", "桌子": "语义：桌子不是鞋的来源，“桌子的鞋”说不通。", "牌子": "牌子：商品的品牌，修饰“鞋”，句意合理。", "月亮": "语义：月亮不生产鞋，“月亮的鞋”没有意义。"}, "sentence_index": 0, "correct_answer": "牌子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渴了，喝了一杯牌子。", "explanation": "这里应该用〈牛奶〉。牌子是商品的名称，不能喝。"}, {"text": "这款牛奶的牌子很香，口感很好。", "explanation": "这里应该用〈口味〉。“香”形容口味，不能用来形容品牌。"}, {"text": "他把牌子穿在脚上出门了。", "explanation": "这里应该用〈鞋〉。牌子是商品的品牌名称，不能穿在脚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牌子", "is_correct": true, "explanation": "牌子 páizi：本词，指商品的品牌。"}, {"text": "孩子", "is_correct": false, "explanation": "孩子 háizi 与 pái 声母不同（h 与 p），意思是小孩。"}, {"text": "才子", "is_correct": false, "explanation": "才子 cáizi 与 pái 声母不同（c 与 p），意思是有才华的人。"}, {"text": "宅子", "is_correct": false, "explanation": "宅子 zháizi 与 pái 声母不同（zh 与 p），意思是住宅。"}, {"text": "摆子", "is_correct": false, "explanation": "摆子 bǎizi（第三声）与 pái（第二声）声调不同，意思是疟疾引起的寒热发作。"}], "explanations": {"牌子": "牌子 páizi：本词，指商品的品牌。", "孩子": "孩子 háizi 与 pái 声母不同（h 与 p），意思是小孩。", "才子": "才子 cáizi 与 pái 声母不同（c 与 p），意思是有才华的人。", "宅子": "宅子 zháizi 与 pái 声母不同（zh 与 p），意思是住宅。", "摆子": "摆子 bǎizi（第三声）与 pái（第二声）声调不同，意思是疟疾引起的寒热发作。"}, "sentence_index": null, "correct_answer": "牌子"}, "level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不能作为洗发水的品牌或种类。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“洗发水”前面的修饰词要说品牌或种类，不说“小说的洗发水”。"}, {"text": "牌子", "is_correct": true, "explanation": "牌子：商品的品牌，修饰“洗发水”，句意合理。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是洗发水的来源，“窗户的洗发水”说不通。"}], "explanations": {"西瓜": "语义：西瓜是水果，不能作为洗发水的品牌或种类。", "小说": "搭配：“洗发水”前面的修饰词要说品牌或种类，不说“小说的洗发水”。", "牌子": "牌子：商品的品牌，修饰“洗发水”，句意合理。", "窗户": "语义：窗户不是洗发水的来源，“窗户的洗发水”说不通。"}, "sentence_index": 6, "correct_answer": "牌子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的牌子是他写的。", "explanation": "这里应该用〈作者〉。“牌子”指品牌，不能说某人写的。"}, {"text": "这杯咖啡的牌子很烫。", "explanation": "这里应该用〈温度〉。“烫”形容温度，品牌没有温度。"}, {"text": "这个老人的牌子是八十岁。", "explanation": "这里应该用〈年龄〉。“八十岁”说的是年龄，品牌不能有年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些牌子们的饼干都很好吃。", "corrected_sentence": "这些牌子的饼干都很好吃。", "error_description": "“牌子”前面已有“这些”表示多个，后面不能再加“们”。应改为「这些牌子的饼干」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个牌子得洗面奶很温和。", "corrected_sentence": "这个牌子的洗面奶很温和。", "error_description": "“牌子”修饰后面的“洗面奶”要用“的”，不能用“得”。“得”用在动词或形容词后，应改为「这个牌子的洗面奶」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
