INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88883, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逮捕是警察把做了坏事的人抓住带走。", "primary_collocate": null, "pronunciation": "dài bǔ", "ipa": "taɪ˥˩ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察逮捕了那个小偷。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在车站逮捕了一个坏人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偷了别人的钱，警察把他逮捕了。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上，警察逮捕了三个抢钱的人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察终于在旅馆里逮捕了那个骗子。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察为什么要逮捕他？他做了坏事。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在他家门口逮捕了他。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里说，警察逮捕了一个有名的坏人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说警察已经逮捕了打人的那个人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到坏人想跑，警察马上逮捕了他。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逮捕了", "label": "体标"}, {"form": "逮捕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "警察把做了坏事的人抓住带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逮捕", "is_correct": true, "explanation": "正确：“逮捕”是警察把做了坏事的人抓住带走，与“警察……了那个小偷”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能说唱一个小偷。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于人。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞食食物，不能用来抓人。"}], "explanations": {"逮捕": "正确：“逮捕”是警察把做了坏事的人抓住带走，与“警察……了那个小偷”相符。", "唱": "搭配：“唱”的对象是歌，不能说唱一个小偷。", "煮": "搭配：“煮”的对象是食物，不能用于人。", "吃": "语义：“吃”指吞食食物，不能用来抓人。"}, "sentence_index": 0, "correct_answer": "逮捕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子在草地上逮捕了一只蝴蝶。", "explanation": "这里应该用〈捉住〉。“逮捕”只用于抓获做了坏事的人，抓动物应用捉住。"}, {"text": "妈妈逮捕了正要跑出去的孩子。", "explanation": "这里应该用〈抓住〉。“逮捕”指警察依法拘捕嫌疑人，妈妈拉住孩子应用抓住。"}, {"text": "渔民逮捕了一条大鱼。", "explanation": "这里应该用〈捕到〉。“逮捕”用于抓获罪犯，捕鱼应用捕到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逮捕", "is_correct": true, "explanation": "正确：“逮捕”与“警察在他家门口……了他”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般用于衣物、身体，不能说洗一个人。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽种植物，与在门口抓人不符。"}, {"text": "吸", "is_correct": false, "explanation": "语义：“吸”指吸入，不能用来抓人。"}], "explanations": {"逮捕": "正确：“逮捕”与“警察在他家门口……了他”相符。", "洗": "搭配：“洗”一般用于衣物、身体，不能说洗一个人。", "种": "语义：“种”指栽种植物，与在门口抓人不符。", "吸": "语义：“吸”指吸入，不能用来抓人。"}, "sentence_index": 6, "correct_answer": "逮捕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫逮捕了一只老鼠。", "explanation": "这里应该用〈扑住〉。“逮捕”用于抓获罪犯，小猫扑住老鼠应用扑住。"}, {"text": "我们在池塘边逮捕了一只螃蟹。", "explanation": "这里应该用〈抓到〉。“逮捕”用于抓获罪犯，抓螃蟹应用抓到。"}, {"text": "猎人逮捕了一只野兔。", "explanation": "这里应该用〈套住〉。“逮捕”用于抓获罪犯，猎人设陷阱抓兔子应用套住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察很快逮捕着那个小偷。", "corrected_sentence": "警察很快逮捕了那个小偷。", "error_description": "“着”表示持续的状态，与“很快”表示的瞬间完成不符，应写作“逮捕了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察曾经逮捕着那个坏人。", "corrected_sentence": "警察曾经逮捕过那个坏人。", "error_description": "“着”表示持续的状态，与“曾经”表示的已完成经历矛盾，应写作“逮捕过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
