INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88884, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "司法机关依法拘捕犯罪嫌疑人。", "primary_collocate": null, "pronunciation": "dài bǔ", "ipa": "taɪ˥˩ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "警方依法逮捕了那名嫌疑人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察院批准逮捕这名犯罪嫌疑人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方昨天逮捕了三名涉嫌诈骗的人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公安机关决定逮捕这名走私者。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经批准，警察当场逮捕了犯罪嫌疑人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，逮捕必须经过检察院批准。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方连夜逮捕了参与抢劫的两个人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证据，警察不能随便逮捕公民。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他涉嫌受贿，警方已经依法逮捕了他。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者报道说，警方逮捕了逃跑多年的嫌疑人。", "target_word": "逮捕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逮捕了", "label": "体标"}, {"form": "逮捕过", "label": "体标"}], "register": "书面", "sense_fingerprint": "司法机关依法拘捕犯罪嫌疑人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逮捕", "is_correct": true, "explanation": "正确：“逮捕”是司法机关依法拘捕犯罪嫌疑人，与“警方依法……了那名嫌疑人”相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好人好事，警方依法不能用于处理嫌疑人。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是事物或方法，不能用于人。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、物品，不能用于嫌疑人。"}], "explanations": {"逮捕": "正确：“逮捕”是司法机关依法拘捕犯罪嫌疑人，与“警方依法……了那名嫌疑人”相符。", "表扬": "语义：“表扬”是称赞好人好事，警方依法不能用于处理嫌疑人。", "发明": "搭配：“发明”的对象是事物或方法，不能用于人。", "修理": "搭配：“修理”的对象是机器、物品，不能用于嫌疑人。"}, "sentence_index": 0, "correct_answer": "逮捕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警方逮捕了这辆走私用的汽车。", "explanation": "这里应该用〈扣押〉。逮捕的对象是人，汽车是物品，应用扣押。"}, {"text": "海关逮捕了这批走私的香烟。", "explanation": "这里应该用〈扣押〉。逮捕的对象是人，查扣货物应用扣押。"}, {"text": "法院逮捕了这家公司的仓库。", "explanation": "这里应该用〈查封〉。仓库是物品，不能逮捕，应用查封。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逮捕", "is_correct": true, "explanation": "正确：“逮捕”与“警方连夜……了参与抢劫的两个人”相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是对喜事表示庆贺，不能用于参与抢劫的人。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是木石等材料，不能用于人。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，与人无关。"}], "explanations": {"逮捕": "正确：“逮捕”与“警方连夜……了参与抢劫的两个人”相符。", "祝贺": "语义：“祝贺”是对喜事表示庆贺，不能用于参与抢劫的人。", "雕刻": "搭配：“雕刻”的对象是木石等材料，不能用于人。", "种植": "语义：“种植”指栽种植物，与人无关。"}, "sentence_index": 6, "correct_answer": "逮捕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机场工作人员逮捕了他的护照，要求他补办手续。", "explanation": "这里应该用〈扣留〉。护照是物品，不能逮捕，应用扣留。"}, {"text": "警方逮捕了赌场里的赌具，没收了现金。", "explanation": "这里应该用〈收缴〉。赌具是物品，不能逮捕，应用收缴。"}, {"text": "海关逮捕了一批毒品，并立即销毁。", "explanation": "这里应该用〈查获〉。毒品是物品，不能逮捕，应用查获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检察院没有逮捕了那名嫌疑人。", "corrected_sentence": "检察院没有逮捕那名嫌疑人。", "error_description": "“没有”否定已发生的动作时不能与“了”同用，应去掉“了”，写作“没有逮捕那名嫌疑人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警方曾经逮捕着那名走私者。", "corrected_sentence": "警方曾经逮捕过那名走私者。", "error_description": "“着”表示持续的状态，与“曾经”表示的已完成经历矛盾，应写作“逮捕过”，放在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
