INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "链接是网上的一个小地方,点一下就能去另一个页面。", "primary_collocate": null, "pronunciation": "lián jiē", "ipa": "ljɛn˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "请点一下这个链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个链接打不开。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把链接发给你了。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页下面有一个链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点这个链接，就能看到视频。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收到我发的链接了吗？", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在群里发了一个链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条链接是红色的。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在文章里放了一个链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个链接带我去了另一个网站。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超链接", "label": "复合"}, {"form": "一个链接", "label": "量词"}, {"form": "一条链接", "label": "量词"}, {"form": "鏈接", "label": "繁体"}], "register": "中性", "sense_fingerprint": "网页上点一下就能跳转的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链接", "is_correct": true, "explanation": "正确：“点一下”后面接可以点击的网页链接，符合语境。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能在网页上被“点一下”，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“点一下”要求可点击的对象，“桌子”与之不搭配。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是可以点击的东西，与“点一下”的语境矛盾。"}], "explanations": {"链接": "正确：“点一下”后面接可以点击的网页链接，符合语境。", "月亮": "语义：月亮不能在网页上被“点一下”，句意不通。", "桌子": "搭配：“点一下”要求可点击的对象，“桌子”与之不搭配。", "海洋": "语义：海洋不是可以点击的东西，与“点一下”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "链接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条链接上挂着一个小吊坠。", "explanation": "这里应该用〈链子〉。“链接”指网页上可点击的连接，不能指项链上的链条。"}, {"text": "这个房间的链接被锁上了。", "explanation": "这里应该用〈门〉。门可以被锁上，“链接”是网页之间的连接，不能指房间的门。"}, {"text": "我最近膝盖的链接总是疼。", "explanation": "这里应该用〈关节〉。“链接”指网页之间的连接，不能指人体的关节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链接", "is_correct": true, "explanation": "正确：“老师在群里发了一个链接”，“链接”可以在群聊中发送，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“发”一般搭配消息、文件、链接等，不能说“发石头”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能通过群聊发送，句意不通。"}, {"text": "箱子", "is_correct": false, "explanation": "语义：箱子不能在群里被“发”出，与群聊的语境矛盾。"}], "explanations": {"链接": "正确：“老师在群里发了一个链接”，“链接”可以在群聊中发送，符合语境。", "石头": "搭配：“发”一般搭配消息、文件、链接等，不能说“发石头”。", "房子": "语义：房子不能通过群聊发送，句意不通。", "箱子": "语义：箱子不能在群里被“发”出，与群聊的语境矛盾。"}, "sentence_index": 6, "correct_answer": "链接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个链接太烫了，我不敢喝。", "explanation": "这里应该用〈汤〉。“链接”是网页上可点击的东西，不能喝，也不会烫。"}, {"text": "这个链接太窄了，我钻不过去。", "explanation": "这里应该用〈洞〉。“链接”指网页上可点击的连接，不能指可以钻过去的洞口。"}, {"text": "这个链接很重，我一个人搬不动。", "explanation": "这里应该用〈箱子〉。“链接”是网络上的连接，没有重量，搬不动的应是箱子等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友刚给我发了一只链接。", "corrected_sentence": "朋友刚给我发了一个链接。", "error_description": "错误形式：“一只链接”。正确形式：“一个链接”。“只”用于动物，“链接”不能用“只”来数，应该用“个”或“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学在微信上给我发了一张链接。", "corrected_sentence": "同学在微信上给我发了一个链接。", "error_description": "错误形式：“一张链接”。正确形式：“一个链接”。“张”用于纸、照片等平面的东西，“链接”应该用“个”或“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
