INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络中指向另一页面或资源的连接。", "primary_collocate": null, "pronunciation": "lián jiē", "ipa": "ljɛn˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "这个链接指向另一个页面。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文件的下载链接在这里。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把视频链接复制给我吗？", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的链接太多了。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击链接后，会出现一个新窗口。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请检查一下这个链接有没有问题。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条链接已经不能用了。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的邮件里有一个购物链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章最后有相关资料的链接。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个链接是错的，页面打不开。", "target_word": "链接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超链接", "label": "复合"}, {"form": "一个链接", "label": "量词"}, {"form": "一条链接", "label": "量词"}, {"form": "鏈接", "label": "繁体"}], "register": "中性", "sense_fingerprint": "网络中指向其他页面或资源的连接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链接", "is_correct": true, "explanation": "正确：链接指向另一个页面，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不能指向另一个页面。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“指向”需要有指向性的事物作主语，“颜色”不能与之搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能指向网页上的另一个页面。"}], "explanations": {"链接": "正确：链接指向另一个页面，符合句意。", "猫": "语义：猫是动物，不能指向另一个页面。", "颜色": "搭配：“指向”需要有指向性的事物作主语，“颜色”不能与之搭配。", "冰箱": "语义：冰箱是家电，不能指向网页上的另一个页面。"}, "sentence_index": 0, "correct_answer": "链接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个链接很高，我够不着。", "explanation": "这里应该用〈书架〉。“链接”是网络概念，没有高度，够不着的应是书架等实物。"}, {"text": "今天链接很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“链接”不能用来说“今天……很好”，描述天气要用“天气”。"}, {"text": "我的链接刚刚开走了。", "explanation": "这里应该用〈火车〉。链接不能开走，它只能指网页之间的连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链接", "is_correct": true, "explanation": "正确：链接已经失效，符合“已经不能用了”的语境。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：蛇是动物，不能说“不能用了”。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗是动物，不能说“不能用了”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以使用的工具，不能说“这条天空已经不能用了”，量词“条”也不搭配。"}], "explanations": {"链接": "正确：链接已经失效，符合“已经不能用了”的语境。", "蛇": "语义：蛇是动物，不能说“不能用了”。", "狗": "语义：狗是动物，不能说“不能用了”。", "天空": "语义：天空不是可以使用的工具，不能说“这条天空已经不能用了”，量词“条”也不搭配。"}, "sentence_index": 6, "correct_answer": "链接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个链接关不上了。", "explanation": "这里应该用〈门〉。“关上”的对象是门、窗等，“链接”不能被关上。"}, {"text": "这个链接太大了，穿不下。", "explanation": "这里应该用〈衣服〉。“链接”不是衣物，不会有大小和穿不穿的问题。"}, {"text": "这个链接很甜，我想吃。", "explanation": "这里应该用〈苹果〉。“链接”是网络概念，不能用“甜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座链接指向一个新的页面。", "corrected_sentence": "这条链接指向一个新的页面。", "error_description": "错误形式：“这座链接”。正确形式：“这条链接”。“座”用于山、桥等大型固定的东西，“链接”应该用“条”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一个很有用链接。", "corrected_sentence": "他找到了一个很有用的链接。", "error_description": "错误形式：“很有用链接”。正确形式：“很有用的链接”。形容词短语修饰名词时，中间要加“的”，构成“很有用的链接”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
