INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（机关、单位）接受并着手办理（申请、案件、投诉等）。", "primary_collocate": null, "pronunciation": "shòu lǐ", "ipa": "ʂou̯˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家银行已经受理了我的贷款申请。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院今天上午受理了这起案件。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员说，这类申请他们不受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的投诉我们已经受理，请耐心等待。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口下午五点后不再受理业务。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份材料不全，办事处没有受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民打电话投诉，十分钟后就有人受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签证中心周一到周五受理申请。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请表提交后，相关部门将在次日受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的申诉受理过两次，但都没有结果。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受理了", "label": "体标"}, {"form": "受理过", "label": "体标"}, {"form": "不予受理", "label": "复合"}], "register": "书面", "sense_fingerprint": "机关或单位接下别人提出的事项并着手办理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手里", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，“手里”指手中，意思不同。"}, {"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指接下事项并着手办理，读作 shòu lǐ。"}, {"text": "收礼", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，“收礼”指接受礼物。"}, {"text": "受力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，“受力”指承受的力。"}, {"text": "守礼", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，“守礼”指遵守礼节。"}], "explanations": {"手里": "shǒu（第三声）与 shòu（第四声）声调不同，“手里”指手中，意思不同。", "受理": "正确答案，“受理”指接下事项并着手办理，读作 shòu lǐ。", "收礼": "shōu（第一声）与 shòu（第四声）声调不同，“收礼”指接受礼物。", "受力": "lì（第四声）与 lǐ（第三声）声调不同，“受力”指承受的力。", "守礼": "shǒu（第三声）与 shòu（第四声）声调不同，“守礼”指遵守礼节。"}, "sentence_index": null, "correct_answer": "受理"}, "level_3": {"options": [{"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指接下申请并办理，与银行的“贷款申请”搭配，符合语境。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”的宾语应是事件，不能带“贷款申请”作宾语。"}, {"text": "掌握", "is_correct": false, "explanation": "搭配：“掌握”的对象是知识、技能、局势等，不说“掌握申请”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑他人，与银行处理贷款申请的语境不符。"}], "explanations": {"受理": "正确答案，“受理”指接下申请并办理，与银行的“贷款申请”搭配，符合语境。", "发生": "配价：“发生”的宾语应是事件，不能带“贷款申请”作宾语。", "掌握": "搭配：“掌握”的对象是知识、技能、局势等，不说“掌握申请”。", "嘲笑": "语义：“嘲笑”是讥笑他人，与银行处理贷款申请的语境不符。"}, "sentence_index": 0, "correct_answer": "受理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经受理了那个苹果，准备吃掉。", "explanation": "这里应该用〈吃〉。受理用于申请、案件、投诉等事项，苹果要用吃。"}, {"text": "这批垃圾我们已经受理了。", "explanation": "这里应该用〈处理〉。受理用于申请、案件、投诉等事项，垃圾要用处理。"}, {"text": "他已经受理了我的礼物。", "explanation": "这里应该用〈接受〉。受理用于申请、案件、投诉等事项，礼物要用接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指接下投诉并着手办理，与“十分钟后就有人”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“投诉”无关，句中没有可以吃的对象。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”的主语是事件，不能说“有人发生”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与处理市民投诉的语境无关。"}], "explanations": {"受理": "正确答案，“受理”指接下投诉并着手办理，与“十分钟后就有人”的语境相符。", "吃": "语义：“吃”与“投诉”无关，句中没有可以吃的对象。", "发生": "配价：“发生”的主语是事件，不能说“有人发生”。", "唱": "语义：“唱”指唱歌，与处理市民投诉的语境无关。"}, "sentence_index": 6, "correct_answer": "受理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师已经受理了这份作业。", "explanation": "这里应该用〈批阅〉。受理用于申请、申诉、投诉等事项，作业要用批阅。"}, {"text": "他每天都受理这盆花。", "explanation": "这里应该用〈浇〉。受理的对象是申请、申诉等事项，给花浇水要用浇。"}, {"text": "他想受理这个红包。", "explanation": "这里应该用〈收下〉。受理用于申请、申诉等事项，红包要用收下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗口受理地很快。", "corrected_sentence": "窗口受理得很快。", "error_description": "补语标记错误：程度补语应用“得”连接动词和补语，“地”用于动词前作状语，不能说“受理地很快”，正确说法是“受理得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
