INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受并办理（案件、申请等）。", "primary_collocate": null, "pronunciation": "shòu lǐ", "ipa": "ʂou̯˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家法院受理过不少劳动纠纷案件。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社保局今年受理了三百多份工伤认定申请。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仲裁委员会决定受理他的申请。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料齐全的话，窗口当场受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类案件由区法院受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方已经受理了她的报案。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请表填错了，工作人员不予受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上提交的申请，三天内受理。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门只受理本市居民的申请。", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院为什么不受理这起诉讼？", "target_word": "受理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受理了", "label": "体标"}, {"form": "受理过", "label": "体标"}, {"form": "不予受理", "label": "复合"}], "register": "书面", "sense_fingerprint": "法院或行政机关正式接收案件、申请并办理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收礼", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，“收礼”指接受礼物。"}, {"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指法院或机关接受并办理案件、申请，读作 shòu lǐ。"}, {"text": "手里", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，“手里”指手中，意思不同。"}, {"text": "受力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，“受力”指承受的力。"}, {"text": "守礼", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，“守礼”指遵守礼节。"}], "explanations": {"收礼": "shōu（第一声）与 shòu（第四声）声调不同，“收礼”指接受礼物。", "受理": "正确答案，“受理”指法院或机关接受并办理案件、申请，读作 shòu lǐ。", "手里": "shǒu（第三声）与 shòu（第四声）声调不同，“手里”指手中，意思不同。", "受力": "lì（第四声）与 lǐ（第三声）声调不同，“受力”指承受的力。", "守礼": "shǒu（第三声）与 shòu（第四声）声调不同，“守礼”指遵守礼节。"}, "sentence_index": null, "correct_answer": "受理"}, "level_3": {"options": [{"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指法院接受并办理案件，与“劳动纠纷案件”搭配，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“劳动纠纷案件”没有语义联系，不能说吃案件。"}, {"text": "打", "is_correct": false, "explanation": "搭配：法院处理案件不说“打案件”，“打”只用于“打官司”等固定说法。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，与法院处理的案件无关。"}], "explanations": {"受理": "正确答案，“受理”指法院接受并办理案件，与“劳动纠纷案件”搭配，符合语境。", "吃": "语义：“吃”与“劳动纠纷案件”没有语义联系，不能说吃案件。", "打": "搭配：法院处理案件不说“打案件”，“打”只用于“打官司”等固定说法。", "喝": "语义：“喝”的对象是饮品，与法院处理的案件无关。"}, "sentence_index": 0, "correct_answer": "受理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经受理了老师的批评，以后会改正。", "explanation": "这里应该用〈接受〉。受理用于申请、案件等事项，接受批评要用接受。"}, {"text": "那批垃圾工作人员已经受理了。", "explanation": "这里应该用〈处理〉。受理用于申请、案件等事项，垃圾要用处理。"}, {"text": "他热情地受理了朋友。", "explanation": "这里应该用〈招待〉。受理的对象是申请、案件等事项，不能用于朋友，朋友要用招待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受理", "is_correct": true, "explanation": "正确答案，“受理”指机关接受申请并办理，与“申请表填错了”的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱、赏识，与“申请表填错了”的语境相矛盾。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的宾语应是火、热情等，不说“点燃申请”。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”是赞美，与申请表出错的语境不符。"}], "explanations": {"受理": "正确答案，“受理”指机关接受申请并办理，与“申请表填错了”的语境相符。", "欣赏": "语义：“欣赏”是喜爱、赏识，与“申请表填错了”的语境相矛盾。", "点燃": "搭配：“点燃”的宾语应是火、热情等，不说“点燃申请”。", "歌颂": "语义：“歌颂”是赞美，与申请表出错的语境不符。"}, "sentence_index": 6, "correct_answer": "受理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为什么不受理这份礼物？", "explanation": "这里应该用〈收下〉。受理用于申请、案件等事项，礼物要用收下。"}, {"text": "他为什么不受理这盆花？", "explanation": "这里应该用〈浇〉。受理的对象是申请、案件等事项，给花浇水要用浇。"}, {"text": "他把这辆车受理了。", "explanation": "这里应该用〈修理〉。受理用于申请、案件等事项，坏了的车要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
