INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时农村集体经济中的基层组织。", "primary_collocate": null, "pronunciation": "shēng chǎn duì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ twei˥˩", "syllable_count": 3, "sentences": [{"text": "过去，农村的人都在生产队里干活。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时是生产队的队长。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时候，村里每个生产队都有土地。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在生产队干了十年活。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农民都按生产队的安排种地。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，那时候全村分成五个生产队。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的农村已经没有生产队了。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产队的粮食是大家一起种的。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸小时候住在一个生产队里。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这个村子以前有三个生产队。", "target_word": "生产队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "生产队长", "label": "复合"}, {"form": "生產隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "旧时农村集体经济中的基层组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产队", "is_correct": true, "explanation": "正确。“过去，农村的人都在生产队里干活”说的是旧时农村的基层组织。"}, {"text": "教室", "is_correct": false, "explanation": "语义：农村的人不会在教室里干活，与“农村的人”的语境冲突。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空是宇宙空间，与“过去农村的人”的劳动场景不符。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“月亮里”不能用来表示干活的场所，搭配不当。"}], "explanations": {"生产队": "正确。“过去，农村的人都在生产队里干活”说的是旧时农村的基层组织。", "教室": "语义：农村的人不会在教室里干活，与“农村的人”的语境冲突。", "太空": "语义：太空是宇宙空间，与“过去农村的人”的劳动场景不符。", "月亮": "搭配：“月亮里”不能用来表示干活的场所，搭配不当。"}, "sentence_index": 0, "correct_answer": "生产队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把生产队放进了书包里。", "explanation": "这里应该用〈课本〉。生产队是农村的组织，不是能放进书包的东西。"}, {"text": "他每天早上骑着生产队去上班。", "explanation": "这里应该用〈自行车〉。生产队是农村的劳动组织，不能被人骑。"}, {"text": "他在生产队读了十年书。", "explanation": "这里应该用〈学校〉。生产队是农村的劳动组织，读书要去学校，不能在生产队读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产队", "is_correct": true, "explanation": "正确。“现在的农村已经没有生产队了”指的是旧时的基层组织消失了。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以“没有”的基层组织，句意说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不属于农村的组织机构，“没有空气了”与句意冲突。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“没有太阳了”不能用来说农村的组织，搭配不当。"}], "explanations": {"生产队": "正确。“现在的农村已经没有生产队了”指的是旧时的基层组织消失了。", "天空": "语义：天空不是可以“没有”的基层组织，句意说不通。", "空气": "语义：空气不属于农村的组织机构，“没有空气了”与句意冲突。", "太阳": "搭配：“没有太阳了”不能用来说农村的组织，搭配不当。"}, "sentence_index": 6, "correct_answer": "生产队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她决定和生产队结婚。", "explanation": "这里应该用〈丈夫〉或〈妻子〉。结婚的对象必须是人，生产队是组织，不能结婚。"}, {"text": "奶奶每天给生产队梳头。", "explanation": "这里应该用〈孙子〉。梳头的对象是人，生产队是组织，不能给它梳头。"}, {"text": "妈妈每天给生产队洗头。", "explanation": "这里应该用〈小孩〉。洗头的对象是人，生产队是组织，不能给它洗头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时在一只生产队干过活。", "corrected_sentence": "他年轻时在一个生产队干过活。", "error_description": "错误：“一只生产队”；正确：“一个生产队”。“生产队”的量词应为“个”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过去那个生产队人都很勤快。", "corrected_sentence": "过去那个生产队的人都很勤快。", "error_description": "错误：“那个生产队人”；正确：“那个生产队的人”。这里表示“属于生产队的人”，修饰语“生产队”与中心语“人”之间需要用“的”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
