INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "游客是到别的地方去玩、去看风景的人。", "primary_collocate": null, "pronunciation": "yóu kè", "ipa": "joʊ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他不是本地人，是来这里玩的游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上站着很多看风景的游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在海边玩了一整天。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店住的大多是游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个背着大包的游客在找地图。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的游客越来越多，路上很挤。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在古城里吃小吃，买礼物。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在北京只是个游客，不太熟悉这里。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个游客请我帮他拍张照片。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天来看红叶的游客特别多。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "外国游客", "label": "复合"}, {"form": "遊客", "label": "繁体"}], "register": "中性", "sense_fingerprint": "去外地玩、看风景的人，不是本地人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本地人", "is_correct": false, "explanation": "语义：“本地人”与“不是本地人”直接矛盾。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指到外地玩的人，与“不是本地人，是来这里玩的”相符。"}, {"text": "居民", "is_correct": false, "explanation": "语义：“居民”指长期住在当地的人，与“来这里玩的”矛盾。"}, {"text": "土著", "is_correct": false, "explanation": "语域：“土著”指原住民，语域色彩不合，且与“来这里玩的”矛盾。"}], "explanations": {"本地人": "语义：“本地人”与“不是本地人”直接矛盾。", "游客": "“游客”指到外地玩的人，与“不是本地人，是来这里玩的”相符。", "居民": "语义：“居民”指长期住在当地的人，与“来这里玩的”矛盾。", "土著": "语域：“土著”指原住民，语域色彩不合，且与“来这里玩的”矛盾。"}, "sentence_index": 0, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区的游客每天负责夜里值班。", "explanation": "这里应该用〈保安〉。“游客”指到别的地方玩的人，负责夜里值班的应说〈保安〉。"}, {"text": "表姐是这家公司的游客，每天负责做账。", "explanation": "这里应该用〈会计〉。“游客”指到别的地方玩的人，负责做账的应说〈会计〉。"}, {"text": "我在北京是个游客，从小在这里长大。", "explanation": "这里应该用〈本地人〉。“游客”指外地来玩的人，从小在这里长大的应说〈本地人〉，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不会在古城里吃小吃、买礼物，句意不通。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指到外地玩的人，符合“在古城里吃小吃，买礼物”的情境。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“们”不用于雕像，且雕像不能吃小吃、买礼物。"}, {"text": "水牛", "is_correct": false, "explanation": "语义：水牛不会买礼物，与句意不符。"}], "explanations": {"老鼠": "语义：老鼠不会在古城里吃小吃、买礼物，句意不通。", "游客": "“游客”指到外地玩的人，符合“在古城里吃小吃，买礼物”的情境。", "雕像": "搭配：“们”不用于雕像，且雕像不能吃小吃、买礼物。", "水牛": "语义：水牛不会买礼物，与句意不符。"}, "sentence_index": 6, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥在这家仓库当游客，每天负责搬货。", "explanation": "这里应该用〈搬运工〉。“游客”指到别的地方玩的人，负责搬货的应说〈搬运工〉。"}, {"text": "这家饭店的游客是老板，每天都在厨房忙。", "explanation": "这里应该用〈店主〉。“游客”指外地来玩的人，经营饭店的人应说〈店主〉，不能说“游客”。"}, {"text": "出租车上的游客负责开车，每天很辛苦。", "explanation": "这里应该用〈司机〉。“游客”指到别的地方玩的人，负责开车的应说〈司机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市里有很多只游客。", "corrected_sentence": "这座城市里有很多游客。", "error_description": "错误在量词“只”。“游客”指人，不能用“只”（“只”多用于动物或成对、成只的东西）。这里应去掉“只”，说“很多游客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只游客在湖边拍照。", "corrected_sentence": "一位游客在湖边拍照。", "error_description": "错误在量词“只”。“只”多用于动物或成只、成对的东西，指人的“游客”应用“位”或“个”，应说“一位游客在湖边拍照”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
