INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外出游览的人。", "primary_collocate": null, "pronunciation": "yóu kè", "ipa": "joʊ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "今天景区里有很多游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位游客在山上拍了很多照片。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们坐着船看湖边的风景。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一位游客问我去博物馆怎么走。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客买票以后才能进入公园。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，游客都躲到了店里。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游带着游客参观了老城。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇每年都吸引上百万游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位游客把手机忘在了车上。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客可以在门口的服务中心拿地图。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "外国游客", "label": "复合"}, {"form": "遊客", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外出游览参观景点的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：景区里不会成批出现冰箱，与“今天景区里有很多”的情境不符。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指外出游览的人，景区里有很多，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：景区里不会有很多作业，与游览情境不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：景区里不会有很多钢琴，句意不通。"}], "explanations": {"冰箱": "语义：景区里不会成批出现冰箱，与“今天景区里有很多”的情境不符。", "游客": "“游客”指外出游览的人，景区里有很多，符合句意。", "作业": "语义：景区里不会有很多作业，与游览情境不符。", "钢琴": "语义：景区里不会有很多钢琴，句意不通。"}, "sentence_index": 0, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的游客每天都要给病人量血压。", "explanation": "这里应该用〈护士〉。“游客”指外出游览的人，给病人量血压的应说〈护士〉。"}, {"text": "我们公司的游客每天都要打卡上班。", "explanation": "这里应该用〈员工〉。“游客”指外出游览的人，每天打卡上班的应说〈员工〉。"}, {"text": "我姐姐是这家饭店的游客，每天负责做菜。", "explanation": "这里应该用〈厨师〉。“游客”指外出游览的人，负责做菜的应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": false, "explanation": "语义：导游不会带着货物去参观老城，句意不通。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指外出游览的人，导游可以带着他们参观老城。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能参观老城，与“带着……参观”的情境不符。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气不是人，不能参观老城，句意不通。"}], "explanations": {"货物": "语义：导游不会带着货物去参观老城，句意不通。", "游客": "“游客”指外出游览的人，导游可以带着他们参观老城。", "石头": "语义：“石头”不能参观老城，与“带着……参观”的情境不符。", "氧气": "语义：氧气不是人，不能参观老城，句意不通。"}, "sentence_index": 6, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我父亲是这家工厂的游客，已经干了三十年。", "explanation": "这里应该用〈工人〉。“游客”指外出游览的人，在工厂长期干活的应说〈工人〉。"}, {"text": "游客负责每天打扫服务中心。", "explanation": "这里应该用〈清洁工〉。“游客”指外出游览的人，每天负责打扫的应说〈清洁工〉，不能说“游客负责打扫”。"}, {"text": "讲解老城历史的游客很有经验。", "explanation": "这里应该用〈导游〉。“游客”是来玩的人，讲解工作的人是〈导游〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个游客们在湖边坐了很久。", "corrected_sentence": "一个游客在湖边坐了很久。", "error_description": "错误在“们”。“一个游客”已是数量短语，后面不能再加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只游客在门口问路。", "corrected_sentence": "这位游客在门口问路。", "error_description": "错误在量词。“只”一般用于动物，指人的“游客”应用“位”或“个”，应说“这位游客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
