INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下人是很久以前在富人家里做活的人。", "primary_collocate": null, "pronunciation": "xià rén", "ipa": "ɕja˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "书里写了一个很老实的下人。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富人家的下人吃得很简单。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太太让下人去买菜。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下人们都怕老爷。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲当过下人。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家的下人有十几个。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下人照顾着少爷的生活。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧里的下人总是很忙。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就被卖到大户人家当下人。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里值班的下人要把门窗都锁好。", "target_word": "下人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下人们", "label": "复数"}], "register": "书面", "sense_fingerprint": "很久以前在富人家里做活的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 夜里 (Zipf 3.96), 值班 (Zipf 3.76), 门窗 (Zipf 3.55)']::text[], '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下人", "is_correct": true, "explanation": "正确答案：下人，指很久以前在富人家里做活的人。"}, {"text": "闲人", "is_correct": false, "explanation": "xián（第二声）与 xià（第四声）韵母与声调都不同，意思是闲着没事做的人。"}, {"text": "仙人", "is_correct": false, "explanation": "xiān（第一声）与 xià（第四声）韵尾不同，意思是神仙。"}, {"text": "线人", "is_correct": false, "explanation": "xiàn 与 xià 只差韵尾 n，意思是为人提供情报的人。"}], "explanations": {"下人": "正确答案：下人，指很久以前在富人家里做活的人。", "闲人": "xián（第二声）与 xià（第四声）韵母与声调都不同，意思是闲着没事做的人。", "仙人": "xiān（第一声）与 xià（第四声）韵尾不同，意思是神仙。", "线人": "xiàn 与 xià 只差韵尾 n，意思是为人提供情报的人。"}, "sentence_index": null, "correct_answer": "下人"}, "level_3": {"options": [{"text": "下人", "is_correct": true, "explanation": "下人：很久以前在富人家里做活的人，符合书中人物的身份。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人，不能用“老实”来形容。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车不是人，“很老实的火车”不成立。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“老实”用于形容人，不修饰树。"}], "explanations": {"下人": "下人：很久以前在富人家里做活的人，符合书中人物的身份。", "冰箱": "语义：冰箱不是人，不能用“老实”来形容。", "火车": "语义：火车不是人，“很老实的火车”不成立。", "树": "搭配：“老实”用于形容人，不修饰树。"}, "sentence_index": 0, "correct_answer": "下人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市里的下人很热情。", "explanation": "这里应该用〈收银员〉。下人指旧时富贵人家的仆人，不能指超市里的收银人员。"}, {"text": "饭馆的下人手艺很好。", "explanation": "这里应该用〈厨师〉。下人指家中仆役，不能用来称饭馆的厨师。"}, {"text": "医院的下人每天照顾病人。", "explanation": "这里应该用〈护工〉。下人指旧时富贵人家的仆人，不用于医院的护理人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88893, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下人", "is_correct": true, "explanation": "正确答案：下人，指很久以前在富人家里做活的人。"}, {"text": "小人", "is_correct": false, "explanation": "xiǎo（第三声）与 xià（第四声）韵母与声调都不同，意思是品行低劣的人，不指仆人。"}, {"text": "下任", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是接任的下一任。"}, {"text": "贤人", "is_correct": false, "explanation": "xián（第二声）与 xià 韵母与声调不同，意思是有德才的人。"}], "explanations": {"下人": "正确答案：下人，指很久以前在富人家里做活的人。", "小人": "xiǎo（第三声）与 xià（第四声）韵母与声调都不同，意思是品行低劣的人，不指仆人。", "下任": "rèn（第四声）与 rén（第二声）声调不同，意思是接任的下一任。", "贤人": "xián（第二声）与 xià 韵母与声调不同，意思是有德才的人。"}, "sentence_index": null, "correct_answer": "下人"}, "level_3": {"options": [{"text": "下人", "is_correct": true, "explanation": "下人：旧时在富人家里做活的人，能够照顾少爷的生活。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是时间，不能照顾人的生活。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“照顾生活”的主语须是能照顾人的人，“花园”不能充当这个成分。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不能照顾少爷的生活，与语境不合。"}], "explanations": {"下人": "下人：旧时在富人家里做活的人，能够照顾少爷的生活。", "夜晚": "语义：夜晚是时间，不能照顾人的生活。", "花园": "搭配：“照顾生活”的主语须是能照顾人的人，“花园”不能充当这个成分。", "宠物": "语义：宠物不能照顾少爷的生活，与语境不合。"}, "sentence_index": 6, "correct_answer": "下人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校里的下人很有耐心。", "explanation": "这里应该用〈老师〉。下人指旧时富人家里做活的人，不能称学校里的教师。"}, {"text": "出租车上的下人每天很忙。", "explanation": "这里应该用〈司机〉。下人指旧时富人家里做活的人，不指开出租车的司机。"}, {"text": "我们班的下人每天认真听讲。", "explanation": "这里应该用〈学生〉。下人指旧时富人家里做活的人，不指在课堂上认真听讲的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有两只下人。", "corrected_sentence": "他家有两个下人。", "error_description": "量词错误：指人的名词一般用“个”，“只”用于动物。“下人”身份低微，不宜用敬称“位”，正确说法为“两个下人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家有只老实的下人。", "corrected_sentence": "那家有个老实的下人。", "error_description": "量词错误：指人的名词用“个”，“只”用于动物。“下人”前应用“个”，正确说法为“那家有个老实的下人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
