INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "武装反叛国家或政权的行动。", "primary_collocate": null, "pronunciation": "pàn luàn", "ipa": "pʰan˥˩ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家发生了一场叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队很快平定了叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叛乱让许多人失去了家。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年边境地区出现了叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了叛乱，后来逃到国外。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府派兵镇压叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场叛乱持续了三个月。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写了很多次叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叛乱的人拿着武器冲进了城里。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王担心国内会有叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场叛乱", "label": "量词"}, {"form": "武装叛乱", "label": "复合"}, {"form": "叛亂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有人不服从国家而动用武力造成的动乱事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叛乱", "is_correct": true, "explanation": "正确答案，“叛乱”指有人武装反抗国家，与“发生了一场”搭配，符合语境。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“发生”多搭配事故、事件，婚礼应说“举行”，不说“发生了一场婚礼”。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：“晚餐”是饮食，不是国家层面的事件，与“这个国家”的语境不符。"}, {"text": "演讲", "is_correct": false, "explanation": "搭配：“演讲”应说“发表”或“举行”，不说“发生了一场演讲”。"}], "explanations": {"叛乱": "正确答案，“叛乱”指有人武装反抗国家，与“发生了一场”搭配，符合语境。", "婚礼": "搭配：“发生”多搭配事故、事件，婚礼应说“举行”，不说“发生了一场婚礼”。", "晚餐": "语义：“晚餐”是饮食，不是国家层面的事件，与“这个国家”的语境不符。", "演讲": "搭配：“演讲”应说“发表”或“举行”，不说“发生了一场演讲”。"}, "sentence_index": 0, "correct_answer": "叛乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那年两国之间爆发了叛乱。", "explanation": "这里应该用〈战争〉。叛乱指国内有人武装反抗政府，两国之间的交战要用战争。"}, {"text": "工人们为了涨工资，发动了一场叛乱。", "explanation": "这里应该用〈罢工〉。叛乱指武装反抗国家政权，工人为涨工资停工要用罢工。"}, {"text": "市民们和平地举行了一场叛乱，表达对新政策的不满。", "explanation": "这里应该用〈抗议〉。叛乱指武装反抗政府，和平表达不满要用抗议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叛乱", "is_correct": true, "explanation": "正确答案，“这场叛乱”持续了一段时间，与“持续了三个月”的语境相符。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：午睡只是短暂的小憩，不可能持续三个月，与语境矛盾。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是短时聚会，不会持续三个月，与“持续了三个月”的语境矛盾。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座通常只持续几小时或几天，与“持续了三个月”的语境不符。"}], "explanations": {"叛乱": "正确答案，“这场叛乱”持续了一段时间，与“持续了三个月”的语境相符。", "午睡": "语义：午睡只是短暂的小憩，不可能持续三个月，与语境矛盾。", "晚会": "语义：晚会是短时聚会，不会持续三个月，与“持续了三个月”的语境矛盾。", "讲座": "语义：讲座通常只持续几小时或几天，与“持续了三个月”的语境不符。"}, "sentence_index": 6, "correct_answer": "叛乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人为了面子进行了一场叛乱。", "explanation": "这里应该用〈决斗〉。叛乱指有人武装反抗国家政权，两个人之间的对决要用决斗。"}, {"text": "两村为地界发生了一场叛乱。", "explanation": "这里应该用〈冲突〉。叛乱指武装反抗国家政权，两村因地界产生的纠纷要用冲突。"}, {"text": "市民们举行了一场叛乱，和平地走上街头。", "explanation": "这里应该用〈游行〉。叛乱指武装反抗政权，和平地走上街头要用游行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只叛乱的起因至今不清楚。", "corrected_sentence": "那场叛乱的起因至今不清楚。", "error_description": "量词错误：“叛乱”应搭配“场”或“次”，“只”多用于动物等，不能用于叛乱。正确说法是“那场叛乱的起因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府很快把这场叛乱平定着。", "corrected_sentence": "政府很快把这场叛乱平定了。", "error_description": "体标错误：句中有“很快”，表示动作已经完成，应在“平定”后用“了”，不能用“着”表示持续，正确说法是“很快把这场叛乱平定了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
