INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "武装反叛国家或政权的行动。", "primary_collocate": null, "pronunciation": "pàn luàn", "ipa": "pʰan˥˩ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "新政权成立后，叛乱仍在继续。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军领导了一次反对政府的叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次叛乱最后失败了。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵发动叛乱，占领了首都。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叛乱的消息传到了王宫。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家用了一年时间结束叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武装叛乱是对政权的严重威胁。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在叛乱中受了重伤。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家几十年来没有出现过叛乱。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叛乱发生后，大使馆通知市民不要出门。", "target_word": "叛乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次叛乱", "label": "量词"}, {"form": "武装叛乱", "label": "复合"}, {"form": "叛亂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "武装力量反叛政权的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叛乱", "is_correct": true, "explanation": "正确答案，“叛乱”指武装反叛政权的行动，与“仍在继续”搭配，符合语境。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一餐饭食，与新政权成立后的局势无关。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子”是食物，与“新政权成立后”的政治语境不符。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能“仍在继续”，与新政权成立后的局势无关。"}], "explanations": {"叛乱": "正确答案，“叛乱”指武装反叛政权的行动，与“仍在继续”搭配，符合语境。", "午饭": "语义：“午饭”是一餐饭食，与新政权成立后的局势无关。", "饺子": "语义：“饺子”是食物，与“新政权成立后”的政治语境不符。", "苹果": "语义：“苹果”是水果，不能“仍在继续”，与新政权成立后的局势无关。"}, "sentence_index": 0, "correct_answer": "叛乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间发动了叛乱，占领了首都。", "explanation": "这里应该用〈战争〉。叛乱指国内武装反抗政权，两国之间的交战要用战争。"}, {"text": "学生们为了不上晚自习，发动了一场叛乱。", "explanation": "这里应该用〈罢课〉。叛乱指武装反叛政权，学生集体停课要用罢课。"}, {"text": "士兵们按照训练计划进行了一场叛乱，模拟占领首都。", "explanation": "这里应该用〈演习〉。叛乱指真实的武装反叛政权，按计划进行的模拟军事训练要用演习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叛乱", "is_correct": true, "explanation": "正确答案，“武装叛乱”是固定搭配，指武装反叛政权，与“对政权的严重威胁”相符。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“武装”修饰的是冲突、暴动等，不能说“武装讲座”。"}, {"text": "足球", "is_correct": false, "explanation": "语义：“足球”是体育运动，不会构成对政权的严重威胁，与语境不符。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“武装婚礼”不合常理，与“对政权的严重威胁”的语境无关。"}], "explanations": {"叛乱": "正确答案，“武装叛乱”是固定搭配，指武装反叛政权，与“对政权的严重威胁”相符。", "讲座": "搭配：“武装”修饰的是冲突、暴动等，不能说“武装讲座”。", "足球": "语义：“足球”是体育运动，不会构成对政权的严重威胁，与语境不符。", "婚礼": "语义：“武装婚礼”不合常理，与“对政权的严重威胁”的语境无关。"}, "sentence_index": 6, "correct_answer": "叛乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两队叛乱结束后，观众离场了。", "explanation": "这里应该用〈比赛〉。叛乱指武装反抗国家政权，两队之间的竞技要用比赛。"}, {"text": "两人叛乱结束后，村民们松了一口气。", "explanation": "这里应该用〈决斗〉。叛乱指有人武装反抗国家，两人之间的对决要用决斗。"}, {"text": "市民们在广场上举行了一场叛乱，要求公开信息。", "explanation": "这里应该用〈集会〉。叛乱指武装反抗政权，市民和平聚集表达诉求要用集会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府军在三天内就镇压了这只叛乱。", "corrected_sentence": "政府军在三天内就镇压了这次叛乱。", "error_description": "量词错误：“叛乱”应搭配“次”或“场”，“只”多用于动物等，不能用于叛乱。正确说法是“镇压了这次叛乱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府军很快把这次武装叛乱平定着。", "corrected_sentence": "政府军很快把这次武装叛乱平定了。", "error_description": "体标错误：句中有“很快”，表示动作已经完成，应在“平定”后用“了”，不能用“着”表示持续，正确说法是“很快把这次武装叛乱平定了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "正确：死路指走不通、无路可走的绝境，与“能让人活下去的路”相对，构成反义关系。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘与“生路”没有反义关系，是无关的名词。"}, {"text": "饼干", "is_correct": false, "explanation": "饼干与“生路”没有反义关系，不能作为其反义词。"}, {"text": "鞋子", "is_correct": false, "explanation": "鞋子与“生路”没有反义关系，不能作为其反义词。"}], "correct_answer": "死路", "explanations": {"死路": "正确：死路指走不通、无路可走的绝境，与“能让人活下去的路”相对，构成反义关系。", "窗帘": "窗帘与“生路”没有反义关系，是无关的名词。", "饼干": "饼干与“生路”没有反义关系，不能作为其反义词。", "鞋子": "鞋子与“生路”没有反义关系，不能作为其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "正确：死路指走不通、无路可走的绝境，与“能让人活下去的路”相对，构成反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙与“生路”没有反义关系，是无关的名词。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶与“生路”没有反义关系，不能作为其反义词。"}, {"text": "毛巾", "is_correct": false, "explanation": "毛巾与“生路”没有反义关系，不能作为其反义词。"}], "correct_answer": "死路", "explanations": {"死路": "正确：死路指走不通、无路可走的绝境，与“能让人活下去的路”相对，构成反义关系。", "钥匙": "钥匙与“生路”没有反义关系，是无关的名词。", "花瓶": "花瓶与“生路”没有反义关系，不能作为其反义词。", "毛巾": "毛巾与“生路”没有反义关系，不能作为其反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生路是能让人活下去的路。", "primary_collocate": null, "pronunciation": "shēng lù", "ipa": "ʂɤŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "在沙漠里，水就是生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人给了他们一条生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有工作，一家人就没有生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水来了，爬上高处才有生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，做手术是他唯一的生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪山里走了三天，终于走出一条生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把人逼得没有生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，种地是农民的生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子，妈妈拼命地找生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不走这条路，我们就没有生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "能让人活下去的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生路", "is_correct": true, "explanation": "正确：“水就是生路”指水能让人活下去，与沙漠里缺水的语境相合。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景不能让人在沙漠里活下去，与“水就是……”的语义不符。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能维持生存，放在沙漠的语境中说“就是生路”说不通。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子不能让人在沙漠里活下去，“水就是……”说不通。"}], "explanations": {"生路": "正确：“水就是生路”指水能让人活下去，与沙漠里缺水的语境相合。", "风景": "语义：风景不能让人在沙漠里活下去，与“水就是……”的语义不符。", "墨水": "语义：墨水不能维持生存，放在沙漠的语境中说“就是生路”说不通。", "帽子": "语义：帽子不能让人在沙漠里活下去，“水就是……”说不通。"}, "sentence_index": 0, "correct_answer": "生路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们通过这条生路了解了情况。", "explanation": "这里应该用〈途径〉。途径指方法或渠道；“生路”只指能谋生或脱险的路，不指获取消息的渠道。"}, {"text": "这道数学题的生路在哪里？", "explanation": "这里应该用〈出路〉。出路可指解决问题的办法；“生路”只指能谋生或脱险的路，不指解题办法。"}, {"text": "他生路很多，能帮我找工作。", "explanation": "这里应该用〈路子〉。路子指门路、办法；“生路”只指谋生或脱险的出路，不能用来说一个人人脉广。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生路", "is_correct": true, "explanation": "正确：“没有生路”指没有能活下去的路，与“别把人逼得”的语境相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是能让人活下去的路，“逼得没有钢琴”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”与“逼得没有……”的语义不符，不能表示生存的出路。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“没有脸色”不成立，应说“没有好脸色”。"}], "explanations": {"生路": "正确：“没有生路”指没有能活下去的路，与“别把人逼得”的语境相合。", "钢琴": "语义：钢琴不是能让人活下去的路，“逼得没有钢琴”说不通。", "眼睛": "语义：“眼睛”与“逼得没有……”的语义不符，不能表示生存的出路。", "脸色": "搭配：“没有脸色”不成立，应说“没有好脸色”。"}, "sentence_index": 6, "correct_answer": "生路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于摸到了写作的生路，文章越写越好。", "explanation": "这里应该用〈窍门〉。窍门指做事的巧妙方法；“生路”指谋生或脱险的路，不指写作的诀窍。"}, {"text": "这批货的生路不明，大家都在找。", "explanation": "这里应该用〈去向〉。去向指去往何处；“生路”指谋生或脱险的路，不指货物的去处。"}, {"text": "这个生路很沉，搬不动。", "explanation": "这里把“生路”当成了可以搬动的〈物件〉，误取了实物的义项；“生路”是抽象的谋生或脱险之路，不能用“很沉”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在沙漠里，找到水就等于找到了一个生路。", "corrected_sentence": "在沙漠里，找到水就等于找到了一条生路。", "error_description": "量词错误：“生路”的量词应为“条”，说“一个生路”是错误的，正确说法是“一条生路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次逃出来，我们总算有了一个生路。", "corrected_sentence": "这次逃出来，我们总算有了一条生路。", "error_description": "量词错误：“生路”的量词应为“条”，说“一个生路”是错误的，正确说法是“一条生路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "正确：死路指走不通、无路可走的绝境，与“能谋生或脱险的路”相对，构成反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与“生路”没有反义关系，是无关的名词。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌与“生路”没有反义关系，不能作为其反义词。"}, {"text": "公园", "is_correct": false, "explanation": "公园与“生路”没有反义关系，不能作为其反义词。"}], "correct_answer": "死路", "explanations": {"死路": "正确：死路指走不通、无路可走的绝境，与“能谋生或脱险的路”相对，构成反义关系。", "雨伞": "雨伞与“生路”没有反义关系，是无关的名词。", "书桌": "书桌与“生路”没有反义关系，不能作为其反义词。", "公园": "公园与“生路”没有反义关系，不能作为其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死路", "is_correct": true, "explanation": "正确：死路指走不通、无路可走的绝境，与“能谋生或脱险的路”相对，构成反义关系。"}, {"text": "木椅", "is_correct": false, "explanation": "木椅与“生路”没有反义关系，是无关的名词。"}, {"text": "水杯", "is_correct": false, "explanation": "水杯与“生路”没有反义关系，不能作为其反义词。"}, {"text": "电灯", "is_correct": false, "explanation": "电灯与“生路”没有反义关系，不能作为其反义词。"}], "correct_answer": "死路", "explanations": {"死路": "正确：死路指走不通、无路可走的绝境，与“能谋生或脱险的路”相对，构成反义关系。", "木椅": "木椅与“生路”没有反义关系，是无关的名词。", "水杯": "水杯与“生路”没有反义关系，不能作为其反义词。", "电灯": "电灯与“生路”没有反义关系，不能作为其反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以谋生或脱险的路径。", "primary_collocate": null, "pronunciation": "shēng lù", "ipa": "ʂɤŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "工厂关门了，大家得自己找生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在城里找一条生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被大火围住，他们终于找到一条生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里没有地，年轻人只好出去找生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意不好做，老板正在想新的生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河是渔民的生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱都给了弟弟，让弟弟有条生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人靠种茶找到了生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路被堵死了，他们看不到一点生路。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了给家人一条生路，他去了南方。", "target_word": "生路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "谋生或脱离危险的出路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生路", "is_correct": true, "explanation": "正确：“找生路”是“谋生的路”的固定说法，与工厂关门、需要自己谋生的语境相合。"}, {"text": "零钱", "is_correct": false, "explanation": "语义：零钱不是谋生或脱险的途径，与“工厂关门了”的语境不合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是工作得到的钱，工厂关门后不能“自己找工资”，与句意不合。"}, {"text": "面子", "is_correct": false, "explanation": "搭配：“找面子”不成立，应说“争面子”或“要面子”。"}], "explanations": {"生路": "正确：“找生路”是“谋生的路”的固定说法，与工厂关门、需要自己谋生的语境相合。", "零钱": "语义：零钱不是谋生或脱险的途径，与“工厂关门了”的语境不合。", "工资": "语义：工资是工作得到的钱，工厂关门后不能“自己找工资”，与句意不合。", "面子": "搭配：“找面子”不成立，应说“争面子”或“要面子”。"}, "sentence_index": 0, "correct_answer": "生路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们通过这条生路了解了情况。", "explanation": "这里应该用〈途径〉。途径指方法或渠道；“生路”只指能谋生或脱险的路，不指获取消息的渠道。"}, {"text": "这个难题的生路在哪里？", "explanation": "这里应该用〈出路〉。出路可指解决问题的办法；“生路”只指能谋生或脱险的路，不指解决难题的办法。"}, {"text": "他很有生路，能帮我找到工作。", "explanation": "这里应该用〈门路〉。门路指人脉或门道；“生路”只指谋生或脱险的路，不能用来说一个人人脉广。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生路", "is_correct": true, "explanation": "正确：“有条生路”指有一条谋生的途径，与“把钱都给了弟弟”的帮扶语境相合。"}, {"text": "河", "is_correct": false, "explanation": "语义：“河”不是可以靠钱给予、用来谋生的途径，句中“让弟弟有……”的语义说不通。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：“蛇”不能通过给钱获得，“让弟弟有条蛇”与句意不符。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：量词“条”不搭配“账本”，应说“本”。"}], "explanations": {"生路": "正确：“有条生路”指有一条谋生的途径，与“把钱都给了弟弟”的帮扶语境相合。", "河": "语义：“河”不是可以靠钱给予、用来谋生的途径，句中“让弟弟有……”的语义说不通。", "蛇": "语义：“蛇”不能通过给钱获得，“让弟弟有条蛇”与句意不符。", "账本": "搭配：量词“条”不搭配“账本”，应说“本”。"}, "sentence_index": 6, "correct_answer": "生路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于找到了学习的生路，成绩一下子提高了。", "explanation": "这里应该用〈窍门〉。窍门指做事的巧妙方法；“生路”只指谋生或脱险的路，不指学习的诀窍。"}, {"text": "这个包裹的生路不明，大家都在找。", "explanation": "这里应该用〈去向〉。去向指去往何处；“生路”指谋生或脱险的路，不指物品的去处。"}, {"text": "他把生路夹在书里，当作书签用。", "explanation": "这里把“生路”当作〈书签〉，取了文具的义项；“生路”是抽象的谋生或脱险之路，不能夹在书里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂子倒闭了，大家只好另谋一个生路。", "corrected_sentence": "厂子倒闭了，大家只好另谋一条生路。", "error_description": "量词错误：“生路”的量词应为“条”，说“一个生路”是错误的，正确说法是“一条生路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有工作，只能去打零工找一个生路。", "corrected_sentence": "他没有工作，只能去打零工找一条生路。", "error_description": "量词错误：“生路”的量词应为“条”，说“一个生路”是错误的，正确说法是“一条生路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
