INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "铁是一种又硬又重的灰黑色金属，可以做锅、做钉子。", "primary_collocate": null, "pronunciation": "tiě", "ipa": "tʰie˨˩˦", "syllable_count": 1, "sentences": [{"text": "铁很硬，也很重。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这口锅是铁做的。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "铁放在水里会生锈。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸用铁做了一把椅子。", "target_word": "铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块铁太重，我拿不动。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些钉子是用铁做的。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人把铁放进火里烧红了。", "target_word": "铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁比木头重得多。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那座桥是用铁造的。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "铁和铜都是金属。", "target_word": "铁", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "鐵", "label": "繁体"}, {"form": "铁锅", "label": "复合"}], "register": "中性", "sense_fingerprint": "又硬又重的灰黑色金属，可做锅和钉子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88899, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铁", "is_correct": true, "explanation": "铁 tiě：正确答案，指又硬又重的金属。"}, {"text": "贴", "is_correct": false, "explanation": "贴 tiē 与 铁 tiě 声母和韵母相同，只是声调不同（第一声），意思是“粘贴”。"}, {"text": "撇", "is_correct": false, "explanation": "撇 piě 与 铁 tiě 韵母和声调相同，只是声母不同（p 与 t），意思是“撇嘴”的撇。"}, {"text": "体", "is_correct": false, "explanation": "体 tǐ 与 铁 tiě 声母和声调相同，但铁 tiě 有韵母 e 而体 tǐ 没有，意思是“身体”。"}], "explanations": {"铁": "铁 tiě：正确答案，指又硬又重的金属。", "贴": "贴 tiē 与 铁 tiě 声母和韵母相同，只是声调不同（第一声），意思是“粘贴”。", "撇": "撇 piě 与 铁 tiě 韵母和声调相同，只是声母不同（p 与 t），意思是“撇嘴”的撇。", "体": "体 tǐ 与 铁 tiě 声母和声调相同，但铁 tiě 有韵母 e 而体 tǐ 没有，意思是“身体”。"}, "sentence_index": null, "correct_answer": "铁"}, "level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "语义：水没有硬度，不会又硬又重，与“很硬，也很重”不合。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸薄而轻，不能说又硬又重。"}, {"text": "铁", "is_correct": true, "explanation": "铁：一种又硬又重的金属，符合“很硬，也很重”。"}, {"text": "棉花", "is_correct": false, "explanation": "搭配：“棉花”松软，与“很硬”搭配不当。"}], "explanations": {"水": "语义：水没有硬度，不会又硬又重，与“很硬，也很重”不合。", "纸": "语义：纸薄而轻，不能说又硬又重。", "铁": "铁：一种又硬又重的金属，符合“很硬，也很重”。", "棉花": "搭配：“棉花”松软，与“很硬”搭配不当。"}, "sentence_index": 0, "correct_answer": "铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只铁很重，我拿不动。", "explanation": "这里应该用〈块〉。铁作为材料常用“块”计量，“只”用于动物或成对的东西，不能用于铁。"}, {"text": "这头铁很重，我拿不动。", "explanation": "这里应该用〈块〉。“头”用于大型牲畜，铁作为材料不能用“头”计量。"}, {"text": "这把铁很重，我拿不动。", "explanation": "这里应该用〈块〉。“把”用于有柄的器具，铁作为材料不能用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰", "is_correct": false, "explanation": "语义：冰放进火里会融化，不会烧红。"}, {"text": "铁", "is_correct": true, "explanation": "铁：金属放进火里可以烧红，符合句意。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖放进火里会烧焦，不会烧红。"}, {"text": "油", "is_correct": false, "explanation": "搭配：“烧红”一般用于固体，不能说油烧红。"}], "explanations": {"冰": "语义：冰放进火里会融化，不会烧红。", "铁": "铁：金属放进火里可以烧红，符合句意。", "糖": "语义：糖放进火里会烧焦，不会烧红。", "油": "搭配：“烧红”一般用于固体，不能说油烧红。"}, "sentence_index": 6, "correct_answer": "铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条铁通到北京。", "explanation": "这里应该用〈铁路〉。“铁”单用指金属，指铁路要说“铁路”。"}, {"text": "他用铁写字。", "explanation": "这里应该用〈钢笔〉。“钢笔”是书写工具，“铁”是金属，不能用来写字。"}, {"text": "我用铁炒菜。", "explanation": "这里应该用〈铁锅〉。“铁锅”是炒菜的器具，“铁”指材料，不能直接用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋里放着一只铁。", "corrected_sentence": "屋里放着一块铁。", "error_description": "量词错误：铁作为材料，计量应说“一块铁”，不能用“只”（“只”用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口锅铁很重。", "corrected_sentence": "这口铁锅很重。", "error_description": "语序错误：“铁锅”是固定的复合词，“铁”要放在“锅”前面，说“锅铁”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上午", "is_correct": true, "explanation": "正确答案。上午与下午以正午为界，是一对反义词。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚指天黑后的时段，与下午不构成反义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "黎明指天刚亮的时候，与下午不构成反义关系。"}, {"text": "星期六", "is_correct": false, "explanation": "星期六是一周中的一天，与下午不构成反义关系。"}], "correct_answer": "上午", "explanations": {"上午": "正确答案。上午与下午以正午为界，是一对反义词。", "夜晚": "夜晚指天黑后的时段，与下午不构成反义关系。", "黎明": "黎明指天刚亮的时候，与下午不构成反义关系。", "星期六": "星期六是一周中的一天，与下午不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上午", "is_correct": true, "explanation": "正确答案。上午与下午以正午为界，是一对反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "早晨指天刚亮到上午的时段，与下午是同一天的前后时段，不构成反义。"}, {"text": "半夜", "is_correct": false, "explanation": "半夜指深夜，与下午不构成反义关系。"}, {"text": "星期一", "is_correct": false, "explanation": "星期一是一周中的一天，与下午不构成反义关系。"}], "correct_answer": "上午", "explanations": {"上午": "正确答案。上午与下午以正午为界，是一对反义词。", "早晨": "早晨指天刚亮到上午的时段，与下午是同一天的前后时段，不构成反义。", "半夜": "半夜指深夜，与下午不构成反义关系。", "星期一": "星期一是一周中的一天，与下午不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下午是中午以后到天黑以前的时间。", "primary_collocate": null, "pronunciation": "xià wǔ", "ipa": "ɕja⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "下午太阳很大，别出去了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她下午三点才吃午饭。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们下午去看电影，好不好？", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午孩子们在院子里玩。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的下午我常常睡觉。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午的风有点儿凉。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王今天下午请假了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上午我工作，下午我休息。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他下午回来，晚上又走了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天下午四点，老师都会给我们发作业。", "target_word": "下午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "中午后到天黑前的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。下午 xià wǔ 指中午以后到天黑以前的时间。"}, {"text": "下雨", "is_correct": false, "explanation": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。"}, {"text": "下雾", "is_correct": false, "explanation": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。"}, {"text": "下浮", "is_correct": false, "explanation": "浮 fú 与 午 wǔ 声母、声调都不同（f/w，第二声/第三声），下浮的意思是价格等往下降。"}], "explanations": {"下午": "正确答案。下午 xià wǔ 指中午以后到天黑以前的时间。", "下雨": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。", "下雾": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。", "下浮": "浮 fú 与 午 wǔ 声母、声调都不同（f/w，第二声/第三声），下浮的意思是价格等往下降。"}, "sentence_index": null, "correct_answer": "下午"}, "level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「下午太阳很大」中，下午表示中午以后的时段。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜是夜里，太阳不会很大，句子与「太阳很大」矛盾。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨是天亮前，太阳还没出来，与「太阳很大」矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "配价：教室是地点，不能表示时间，「教室太阳很大」不通。"}], "explanations": {"下午": "正确答案。「下午太阳很大」中，下午表示中午以后的时段。", "深夜": "语义：深夜是夜里，太阳不会很大，句子与「太阳很大」矛盾。", "凌晨": "语义：凌晨是天亮前，太阳还没出来，与「太阳很大」矛盾。", "教室": "配价：教室是地点，不能表示时间，「教室太阳很大」不通。"}, "sentence_index": 0, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的下午十点，我们还在湖边散步。", "explanation": "这里应该用〈夜里〉。下午到天黑为止，晚上十点已是夜里。"}, {"text": "我下午九点去上班。", "explanation": "这里应该用〈晚上〉。下午只到天黑前，晚上九点已不属于下午。"}, {"text": "下午十一点的街道很安静。", "explanation": "这里应该用〈深夜〉。下午只到天黑前，深夜十一点的街道要说深夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「小王今天下午请假了」中，下午是今天的一个时段。"}, {"text": "公司", "is_correct": false, "explanation": "配价：公司是地点，不能直接作时间状语，「小王今天公司请假了」不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是地点，不表示时间，句子不通。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是家具，不表示时间，句子不通。"}], "explanations": {"下午": "正确答案。「小王今天下午请假了」中，下午是今天的一个时段。", "公司": "配价：公司是地点，不能直接作时间状语，「小王今天公司请假了」不通。", "病房": "语义：病房是地点，不表示时间，句子不通。", "饭桌": "语义：饭桌是家具，不表示时间，句子不通。"}, "sentence_index": 6, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天下午十一点还在看书。", "explanation": "这里应该用〈晚上〉。下午指正午到天黑前，十一点要说晚上。"}, {"text": "我下午七点吃晚饭。", "explanation": "这里应该用〈晚上〉。下午到天黑为止，七点已是晚上。"}, {"text": "下午八点的街道很热闹。", "explanation": "这里应该用〈晚上〉。下午到天黑为止，八点已是晚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只下午我们去游泳吧。", "corrected_sentence": "这个下午我们去游泳吧。", "error_description": "错误：时段名词「下午」用了量词「只」。「只」用于动物等，应说「这个下午」，量词「个」用于时段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们下午两出发。", "corrected_sentence": "他们下午两点出发。", "error_description": "错误：时刻缺少「点」。「下午两」不能单独表示时刻，应说「下午两点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上午", "is_correct": true, "explanation": "正确答案。上午与下午以正午为界，是一对反义词。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚指天黑后的时段，与下午不构成反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "清晨指天刚亮的时候，与下午不构成反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "周末指星期六、日，是一周的时段，与下午不构成反义关系。"}], "correct_answer": "上午", "explanations": {"上午": "正确答案。上午与下午以正午为界，是一对反义词。", "夜晚": "夜晚指天黑后的时段，与下午不构成反义关系。", "清晨": "清晨指天刚亮的时候，与下午不构成反义关系。", "周末": "周末指星期六、日，是一周的时段，与下午不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
