INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从正午十二点到日落之前的时间。", "primary_collocate": null, "pronunciation": "xià wǔ", "ipa": "ɕja⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "我下午要去图书馆。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天下午天气很好。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天下午两点开会。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下午我们一起去公园玩吧。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下午都在家学习。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午的课四点结束。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天下午我见了一个老朋友。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星期五下午学校不上课。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你下午有时间吗？", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天下午妈妈要带我去看医生。", "target_word": "下午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "正午到日落前的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。下午 xià wǔ 指正午到日落前的时段。"}, {"text": "下雨", "is_correct": false, "explanation": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。"}, {"text": "下雾", "is_correct": false, "explanation": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。"}, {"text": "下浮", "is_correct": false, "explanation": "浮 fú 与 午 wǔ 声母、声调都不同（f/w，第二声/第三声），下浮的意思是价格等往下降。"}], "explanations": {"下午": "正确答案。下午 xià wǔ 指正午到日落前的时段。", "下雨": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。", "下雾": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。", "下浮": "浮 fú 与 午 wǔ 声母、声调都不同（f/w，第二声/第三声），下浮的意思是价格等往下降。"}, "sentence_index": null, "correct_answer": "下午"}, "level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「我下午要去图书馆」中，下午是表示时段的名词。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是吃的东西，不是时段，不能说「我午饭要去图书馆」。"}, {"text": "食堂", "is_correct": false, "explanation": "配价：食堂是地点，不能直接充当时间状语，需要说「在食堂」之类。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是早上吃的饭，不表示去图书馆的时间，句子不通。"}], "explanations": {"下午": "正确答案。「我下午要去图书馆」中，下午是表示时段的名词。", "午饭": "语义：午饭是吃的东西，不是时段，不能说「我午饭要去图书馆」。", "食堂": "配价：食堂是地点，不能直接充当时间状语，需要说「在食堂」之类。", "早饭": "语义：早饭是早上吃的饭，不表示去图书馆的时间，句子不通。"}, "sentence_index": 0, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下午十一点才睡觉。", "explanation": "这里应该用〈晚上〉。下午指正午到日落前，夜里十一点要说晚上。"}, {"text": "我下午十点还在写作业。", "explanation": "这里应该用〈夜里〉。下午只到日落前，夜里十点已不属于下午。"}, {"text": "我下午八点去跑步。", "explanation": "这里应该用〈晚上〉。下午到日落为止，晚上八点已不属于下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX