INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「昨天下午我见了一个老朋友」中，下午表示昨天的一个时段。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是时段，「昨天书包我见了」不通。"}, {"text": "饭店", "is_correct": false, "explanation": "配价：饭店是地点，不能直接作时间状语，需要用「在饭店」。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是读物，不能表示见人的时间。"}], "explanations": {"下午": "正确答案。「昨天下午我见了一个老朋友」中，下午表示昨天的一个时段。", "书包": "语义：书包是物品，不是时段，「昨天书包我见了」不通。", "饭店": "配价：饭店是地点，不能直接作时间状语，需要用「在饭店」。", "报纸": "语义：报纸是读物，不能表示见人的时间。"}, "sentence_index": 6, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸下午十一点还在公司加班。", "explanation": "这里应该用〈深夜〉。下午只到日落前，深夜十一点不能说下午。"}, {"text": "我们下午十点还在楼下聊天。", "explanation": "这里应该用〈夜里〉。下午只到日落前，夜里十点已不属于下午。"}, {"text": "我们下午九点一起去散步。", "explanation": "这里应该用〈晚上〉。下午到日落为止，晚上九点已不属于下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只下午我在家看书。", "corrected_sentence": "这个下午我在家看书。", "error_description": "错误：时段名词「下午」用了量词「只」。「只」用于动物等，应说「这个下午」，量词「个」用于时段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下午三开会。", "corrected_sentence": "我们下午三点开会。", "error_description": "错误：时刻缺少「点」。「下午三」不能单独表示时刻，应说「下午三点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
