INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "可谓是可以说是。", "primary_collocate": null, "pronunciation": "kě wèi", "ipa": "kʰɤ²¹⁴ wei⁵¹", "syllable_count": 2, "sentences": [{"text": "他的汉语可谓非常流利。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆可谓全城最有名的。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛可谓精彩极了。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对孩子可谓关怀备至。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的字可谓一绝。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天可谓热得让人受不了。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王可谓我们公司的老前辈。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雨可谓来得恰到好处。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩可谓天生一对。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的收成可谓好极了。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "可以说是（引出评价）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可谓", "is_correct": true, "explanation": "正确。“可谓”引出对“汉语”的评价，接在主语后，与“非常流利”搭配。"}, {"text": "说明", "is_correct": false, "explanation": "配价：“说明”后要接一个完整的陈述或事实，不能直接接“非常流利”这样的形容词短语。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”接的是声音、信号等，不能与“汉语”搭配，句子读起来不通。"}, {"text": "带有", "is_correct": false, "explanation": "语义：“带有”要接具体的特点或成分，“非常流利”是程度评价，与“带有”不搭。"}], "explanations": {"可谓": "正确。“可谓”引出对“汉语”的评价，接在主语后，与“非常流利”搭配。", "说明": "配价：“说明”后要接一个完整的陈述或事实，不能直接接“非常流利”这样的形容词短语。", "发出": "搭配：“发出”接的是声音、信号等，不能与“汉语”搭配，句子读起来不通。", "带有": "语义：“带有”要接具体的特点或成分，“非常流利”是程度评价，与“带有”不搭。"}, "sentence_index": 0, "correct_answer": "可谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家可谓住在三楼。", "explanation": "这里不用〈可谓〉。“可谓”用于引出评价，“住在三楼”是客观位置，直接说“我家住在三楼”即可。"}, {"text": "这次考试可谓有五十道题。", "explanation": "这里不用〈可谓〉。“有五十道题”是客观数量，陈述事实时不用引出评价的“可谓”。"}, {"text": "他可谓昨天到北京了。", "explanation": "这里不用〈可谓〉。“可谓”用于引出评价，“昨天到北京”是具体的时间和行动，应直接说“他昨天到北京了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可谓", "is_correct": true, "explanation": "正确。“可谓”引出对“老王”身份的评价，接在主语后，与“老前辈”搭配。"}, {"text": "称", "is_correct": false, "explanation": "配价：“称”要用“称X为Y”的格式，直接接“我们公司的老前辈”不成立。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”表示阻拦，与“老前辈”的身份评价不搭，句子意思不通。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”是动作，不能表示身份判断，“站……老前辈”读起来不通。"}], "explanations": {"可谓": "正确。“可谓”引出对“老王”身份的评价，接在主语后，与“老前辈”搭配。", "称": "配价：“称”要用“称X为Y”的格式，直接接“我们公司的老前辈”不成立。", "挡": "语义：“挡”表示阻拦，与“老前辈”的身份评价不搭，句子意思不通。", "站": "语义：“站”是动作，不能表示身份判断，“站……老前辈”读起来不通。"}, "sentence_index": 6, "correct_answer": "可谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的收成可谓好吗？", "explanation": "这里不用〈可谓〉。“可谓”表示肯定的评价，不用于疑问句；询问时直接说“好吗”。"}, {"text": "你别可谓这么说了。", "explanation": "这里不用〈可谓〉。“可谓”用于陈述评价，不能用在劝阻的祈使句中；劝人别这样说时直接说“别这么说”。"}, {"text": "他昨天没来，可谓他很忙。", "explanation": "这里应该用〈可见〉。“可见”表示由事实推出结论，“可谓”只用来引出评价，不能用来推断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师可谓的耐心极了。", "corrected_sentence": "这位老师可谓耐心极了。", "error_description": "错误：“可谓”后多加了“的”。“可谓”后直接接评价，不能加“的”，正确说法是“这位老师可谓耐心极了”。", "correct_sentence_indices": [0, 2, 3]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出可谓了好极了。", "corrected_sentence": "这次演出可谓好极了。", "error_description": "错误：“可谓”和“好极了”之间多了“了”。“可谓”后直接接评价，不能加“了”，正确说法是“这次演出可谓好极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
