INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "可以说；可以称得上。", "primary_collocate": null, "pronunciation": "kě wèi", "ipa": "kʰɤ²¹⁴ wei⁵¹", "syllable_count": 2, "sentences": [{"text": "能考上这所大学，可谓不容易。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生可谓历尽艰难。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书可谓是学生必读的好书。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法可谓简单又有效。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的菜可谓色香味俱全。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好天气可谓难得。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这座城市，他可谓了如指掌。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事可谓家喻户晓。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能住在海边，可谓幸运。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩可谓一天比一天好。", "target_word": "可谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "可以说；可以称得上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可谓", "is_correct": true, "explanation": "正确。“可谓”引出对“能考上这所大学”的评价，与“不容易”搭配，前后语义连贯。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”要接名词性的行动，不能直接接“不容易”这样的评价短语。"}, {"text": "变成", "is_correct": false, "explanation": "配价：“变成”后要接名词，“变成不容易”不成立。"}, {"text": "受到", "is_correct": false, "explanation": "搭配：“受到”后要接名词，如“表扬”“照顾”，不能接“不容易”。"}], "explanations": {"可谓": "正确。“可谓”引出对“能考上这所大学”的评价，与“不容易”搭配，前后语义连贯。", "进行": "配价：“进行”要接名词性的行动，不能直接接“不容易”这样的评价短语。", "变成": "配价：“变成”后要接名词，“变成不容易”不成立。", "受到": "搭配：“受到”后要接名词，如“表扬”“照顾”，不能接“不容易”。"}, "sentence_index": 0, "correct_answer": "可谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼可谓建在山上。", "explanation": "这里不用〈可谓〉。“建在山上”是客观事实，“可谓”只用来引出评价，直接说“这座楼建在山上”。"}, {"text": "他可谓买了三本书。", "explanation": "这里不用〈可谓〉。“买了三本书”是具体行为和数量，不是评价，用“可谓”不当。"}, {"text": "他可谓来过这里。", "explanation": "这里应该用〈确实〉。“确实”用于确认事实，“可谓”只用来引出评价，“来过这里”是事实陈述，不能用“可谓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可谓", "is_correct": true, "explanation": "正确。“可谓”引出对“他”熟悉程度的评价，与“了如指掌”搭配。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”不能接“了如指掌”这类状态性成语，句子不成立。"}, {"text": "下", "is_correct": false, "explanation": "语义：“下”指下棋或下决心，与“熟悉这座城市”的意思无关。"}, {"text": "放", "is_correct": false, "explanation": "语义：“放”表示放置，与“了如指掌”的含义不搭，句子读起来不通。"}], "explanations": {"可谓": "正确。“可谓”引出对“他”熟悉程度的评价，与“了如指掌”搭配。", "说": "配价：“说”不能接“了如指掌”这类状态性成语，句子不成立。", "下": "语义：“下”指下棋或下决心，与“熟悉这座城市”的意思无关。", "放": "语义：“放”表示放置，与“了如指掌”的含义不搭，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "可谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩可谓好吗？", "explanation": "这里不用〈可谓〉。“可谓”表示肯定的评价，不用于疑问句；询问时直接说“好吗”。"}, {"text": "你别可谓这样夸他了。", "explanation": "这里不用〈可谓〉。“可谓”用于陈述评价，不能用在劝阻的祈使句中；直接说“别这样夸他了”。"}, {"text": "他迟到了，可谓没赶上车。", "explanation": "这里应该用〈所以〉。“所以”表示因果关系，“可谓”只用来引出评价，不表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行可谓的收获满满。", "corrected_sentence": "这次旅行可谓收获满满。", "error_description": "错误：“可谓”后多加了“的”。“可谓”后直接接评价，不能加“的”，正确说法是“这次旅行可谓收获满满”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的表现可谓了出色。", "corrected_sentence": "他的表现可谓出色。", "error_description": "错误：“可谓”和“出色”之间多了“了”。“可谓”后直接接评价，不能加“了”，正确说法是“他的表现可谓出色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
