INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "当令是这一季刚好有的，最合适这个时候。", "primary_collocate": null, "pronunciation": "dāng lìng", "ipa": "taŋ˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "西瓜是夏天当令的水果。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在草莓正当令，又甜又便宜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢买当令的蔬菜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当令的东西不但好吃，价钱也不高。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天正是竹笋当令的时候。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季节，柿子当令，很多人在买。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃当令的菜对身体好。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天橘子当令，水果店里到处都是。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天当令的螃蟹又大又肥。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去市场买了当令的青菜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當令", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西正好是这个季节出产、最适合此时", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当令", "is_correct": true, "explanation": "正确。当令指这个季节正好上市、最合适，夏天的西瓜正是如此。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：「寒冷」与「夏天」的季节不符，西瓜不能说是寒冷的水果。"}, {"text": "人造", "is_correct": false, "explanation": "语义：西瓜是天然的，「人造的」与水果的本义相反。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：「硬朗」多形容老人的身体，不用来修饰水果。"}], "explanations": {"当令": "正确。当令指这个季节正好上市、最合适，夏天的西瓜正是如此。", "寒冷": "语义：「寒冷」与「夏天」的季节不符，西瓜不能说是寒冷的水果。", "人造": "语义：西瓜是天然的，「人造的」与水果的本义相反。", "硬朗": "搭配：「硬朗」多形容老人的身体，不用来修饰水果。"}, "sentence_index": 0, "correct_answer": "当令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手现在很当令。", "explanation": "这里应该用〈当红〉。当令只说应季的蔬果，不用来形容人。"}, {"text": "这首歌很当令，大家都在听。", "explanation": "这里应该用〈流行〉。当令说的是应季，不用来说歌曲的流行。"}, {"text": "这个发型很当令。", "explanation": "这里应该用〈时兴〉。当令指应季，不用于形容发型等时尚事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当令", "is_correct": true, "explanation": "正确。当令的菜指应季、新鲜的蔬菜，吃了对身体好。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：腐烂的菜不能吃，与「对身体好」的语境矛盾。"}, {"text": "煞白", "is_correct": false, "explanation": "体貌：「煞白」形容脸色，不用来形容菜的外观。"}, {"text": "透明", "is_correct": false, "explanation": "语义：菜一般不说透明，「吃透明的菜对身体好」不成立。"}], "explanations": {"当令": "正确。当令的菜指应季、新鲜的蔬菜，吃了对身体好。", "腐烂": "语义：腐烂的菜不能吃，与「对身体好」的语境矛盾。", "煞白": "体貌：「煞白」形容脸色，不用来形容菜的外观。", "透明": "语义：菜一般不说透明，「吃透明的菜对身体好」不成立。"}, "sentence_index": 6, "correct_answer": "当令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课最近很当令。", "explanation": "这里应该用〈热门〉。当令用于应季的蔬果，不用于课程等事物。"}, {"text": "这本小说很当令。", "explanation": "这里应该用〈畅销〉。当令说的是季节，不说书的销量。"}, {"text": "这款电脑很当令。", "explanation": "这里应该用〈抢手〉。当令只用于应季的蔬果，不用于电脑等商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的时候，当令地西瓜最便宜。", "corrected_sentence": "夏天的时候，当令的西瓜最便宜。", "error_description": "「当令」修饰名词「西瓜」时应用「的」，不能用「地」（「地」用于修饰动词）。正确：当令的西瓜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的橘子被当令，个个都很甜。", "corrected_sentence": "今年的橘子很当令，个个都很甜。", "error_description": "「当令」是形容词，不能用于「被」字句；此处应改为「很」。正确：很当令。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
