INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88906, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（蔬菜、水果等）正当季节的。", "primary_collocate": null, "pronunciation": "dāng lìng", "ipa": "taŋ˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这些草莓不是当令的，所以很贵。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荔枝在夏天当令。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当令的白菜又新鲜又便宜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这批桃子是当令的。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是梨子当令的季节。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜市场里当令的水果最多。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天当令的蔬菜有白菜和萝卜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当令的葡萄特别甜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只买当令的蔬菜，不买大棚菜。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芒果正当令，一斤只要五块钱。", "target_word": "当令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當令", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蔬菜水果正处在上市的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当令", "is_correct": true, "explanation": "正确。当令指正在上市、正当季，不是当令的草莓，价格才会贵。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：草莓不说寒冷，「不是寒冷的，所以很贵」没有因果关系。"}, {"text": "透明", "is_correct": false, "explanation": "语义：草莓不说透明，「不是透明的，所以很贵」不成立。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：「硬朗」形容人或身体，不修饰草莓。"}], "explanations": {"当令": "正确。当令指正在上市、正当季，不是当令的草莓，价格才会贵。", "寒冷": "语义：草莓不说寒冷，「不是寒冷的，所以很贵」没有因果关系。", "透明": "语义：草莓不说透明，「不是透明的，所以很贵」不成立。", "硬朗": "搭配：「硬朗」形容人或身体，不修饰草莓。"}, "sentence_index": 0, "correct_answer": "当令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌最近很当令。", "explanation": "这里应该用〈流行〉。当令说的是应季的蔬果，不用来说歌曲的流行。"}, {"text": "这台空调很当令。", "explanation": "这里应该用〈热销〉。当令只用于应季的蔬果，不用于电器。"}, {"text": "他是个当令的演员。", "explanation": "这里应该用〈当红〉。当令不用来形容人，演员走红要用当红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当令", "is_correct": true, "explanation": "正确。冬天当令的蔬菜即冬季正当季的蔬菜，白菜和萝卜正是如此。"}, {"text": "夏日", "is_correct": false, "explanation": "语义：「夏日」与「冬天」冲突，白菜和萝卜不是夏季的蔬菜。"}, {"text": "煞白", "is_correct": false, "explanation": "体貌：「煞白」形容脸色，不用来修饰蔬菜。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：腐烂不是蔬菜的季节特征，与「有白菜和萝卜」的列举语境不符。"}], "explanations": {"当令": "正确。冬天当令的蔬菜即冬季正当季的蔬菜，白菜和萝卜正是如此。", "夏日": "语义：「夏日」与「冬天」冲突，白菜和萝卜不是夏季的蔬菜。", "煞白": "体貌：「煞白」形容脸色，不用来修饰蔬菜。", "腐烂": "语义：腐烂不是蔬菜的季节特征，与「有白菜和萝卜」的列举语境不符。"}, "sentence_index": 6, "correct_answer": "当令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很当令。", "explanation": "这里应该用〈时髦〉。当令指应季，不用来形容衣服的时尚程度。"}, {"text": "这家餐厅很当令。", "explanation": "这里应该用〈火爆〉。当令只用于应季的蔬果，不用于餐厅的人气。"}, {"text": "这部电影很当令。", "explanation": "这里应该用〈卖座〉。当令说的是季节，不说电影的票房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个季节，当令地橙子最便宜。", "corrected_sentence": "这个季节，当令的橙子最便宜。", "error_description": "「当令」修饰名词「橙子」时应用「的」，不能用「地」（「地」用于修饰动词）。正确：当令的橙子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的桃子很当令地，个头也大。", "corrected_sentence": "这家店的桃子很当令，个头也大。", "error_description": "「当令」作谓语时后面不加「地」（「地」用于修饰动词，不用于形容词谓语）。正确：很当令。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
