INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88907, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陪是和别人在一起，不让他一个人。", "primary_collocate": null, "pronunciation": "péi", "ipa": "pʰei˧˥", "syllable_count": 1, "sentences": [{"text": "奶奶一个人在家，我周末回去陪她。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病了，爸爸在医院陪着她。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕黑，晚上要有人陪他睡觉。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人很孤单，我想多陪陪她。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷住院的时候，我天天去陪他。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人需要有人陪，儿女不能总不回家。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心情不好，朋友陪了他一晚上。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗每天陪着我，我不觉得孤单。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别走，再陪我坐一会儿，好吗？", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前我很紧张，妈妈一直陪在我身边。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陪了", "label": "体标（了）"}, {"form": "陪着", "label": "体标（着）"}, {"form": "陪过", "label": "体标（过）"}, {"form": "陪陪", "label": "重叠"}], "register": "口语", "sense_fingerprint": "和别人待在一起，让他不孤单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪 péi 指和人待在一起、不让他一个人，正是听到的词。"}, {"text": "配", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、搭配。"}, {"text": "盆", "is_correct": false, "explanation": "pén 与 péi 韵母不同（en 与 ei），意思是花盆、盆子。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 péi 韵母不同（ai 与 ei），意思是排列、排队。"}, {"text": "肥", "is_correct": false, "explanation": "féi 与 péi 声母不同（f 与 p），意思是肥料、肥胖。"}], "explanations": {"陪": "陪 péi 指和人待在一起、不让他一个人，正是听到的词。", "配": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、搭配。", "盆": "pén 与 péi 韵母不同（en 与 ei），意思是花盆、盆子。", "排": "pái 与 péi 韵母不同（ai 与 ei），意思是排列、排队。", "肥": "féi 与 péi 声母不同（f 与 p），意思是肥料、肥胖。"}, "sentence_index": null, "correct_answer": "陪"}, "level_3": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪：与“我周末回去”相符，表示去她身边和她待在一起。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“回去”是去她身边，“离开”与之相反，句子说不通。"}, {"text": "抛下", "is_correct": false, "explanation": "语义：“抛下”是丢开不管，与周末回去看她的语境相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是厌烦、看不起，与奶奶孤单、我特意回去的语境矛盾。"}], "explanations": {"陪": "陪：与“我周末回去”相符，表示去她身边和她待在一起。", "离开": "语义：“回去”是去她身边，“离开”与之相反，句子说不通。", "抛下": "语义：“抛下”是丢开不管，与周末回去看她的语境相反。", "嫌弃": "语义：“嫌弃”是厌烦、看不起，与奶奶孤单、我特意回去的语境矛盾。"}, "sentence_index": 0, "correct_answer": "陪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我陪了朋友的婚礼。", "explanation": "这里应该用〈参加〉。陪表示和人待在一起，不用来说参加婚礼这类活动。"}, {"text": "护士每天陪病人的饮食。", "explanation": "这里应该用〈照料〉。陪只表示和人待在一起，不能说陪病人的饮食，照料才用于饮食起居。"}, {"text": "他陪这本书读了三遍。", "explanation": "这里“陪”被误用为〈阅读〉的意思。陪表示和人待在一起，不能带书做宾语，应说“他把这本书读了三遍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88907, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪 péi 指和人待在一起、不让他一个人，正是听到的词。"}, {"text": "佩", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是佩服、佩戴。"}, {"text": "没", "is_correct": false, "explanation": "méi 与 péi 声母不同（m 与 p），意思是没有。"}, {"text": "皮", "is_correct": false, "explanation": "pí 与 péi 韵母不同（i 与 ei），意思是皮肤、皮革。"}, {"text": "呸", "is_correct": false, "explanation": "pēi（第一声）与 péi（第二声）声调不同，是表示唾弃的叹词。"}], "explanations": {"陪": "陪 péi 指和人待在一起、不让他一个人，正是听到的词。", "佩": "pèi（第四声）与 péi（第二声）声调不同，意思是佩服、佩戴。", "没": "méi 与 péi 声母不同（m 与 p），意思是没有。", "皮": "pí 与 péi 韵母不同（i 与 ei），意思是皮肤、皮革。", "呸": "pēi（第一声）与 péi（第二声）声调不同，是表示唾弃的叹词。"}, "sentence_index": null, "correct_answer": "陪"}, "level_3": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪：与“心情不好”的语境相符，表示朋友一直陪着他。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：朋友在他心情不好时抛弃他，与“陪了他一晚上”的意思相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是厌烦、看不起，与朋友陪伴他的语境矛盾。"}, {"text": "骂", "is_correct": false, "explanation": "语义：他心情不好，朋友应该安慰、陪伴他，“骂了他一晚上”与语境不合。"}], "explanations": {"陪": "陪：与“心情不好”的语境相符，表示朋友一直陪着他。", "抛弃": "语义：朋友在他心情不好时抛弃他，与“陪了他一晚上”的意思相反。", "嫌弃": "语义：“嫌弃”是厌烦、看不起，与朋友陪伴他的语境矛盾。", "骂": "语义：他心情不好，朋友应该安慰、陪伴他，“骂了他一晚上”与语境不合。"}, "sentence_index": 6, "correct_answer": "陪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈一直陪我的成绩。", "explanation": "这里应该用〈关注〉。陪的对象是人，表示待在一起，不能说陪成绩。"}, {"text": "老师一直陪我的作文。", "explanation": "这里应该用〈批改〉。陪的对象是人，不能说陪作文；批改作文才这样说。"}, {"text": "我一直陪这台电脑，每天开机关机。", "explanation": "这里应该用〈使用〉。陪的对象是人，不能用来说陪电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天放学后陪了奶奶聊天。", "corrected_sentence": "我每天放学后陪奶奶聊天。", "error_description": "错误：“陪”后多加了“了”。“每天”表示习惯，不能用“了”表示完成，应改为“陪奶奶聊天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷在医院陪我着。", "corrected_sentence": "爷爷在医院陪着我。", "error_description": "错误：“着”应紧跟动词，写作“陪着我”，不能放在宾语“我”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
