INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陪同：跟着别人一起去做某件事。", "primary_collocate": null, "pronunciation": "péi", "ipa": "pʰei˧˥", "syllable_count": 1, "sentences": [{"text": "我陪客人去长城参观。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常陪孩子去公园玩。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陪朋友逛了一下午街。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你陪我去医院看看，好吗？", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸陪我练习写汉字。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找人陪我去买衣服。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他陪女朋友看了一场电影。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师陪学生们走到了校门口。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天陪我吃晚饭，聊聊学校的事。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我陪着外国朋友在北京走了一圈。", "target_word": "陪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陪了", "label": "体标（了）"}, {"form": "陪着", "label": "体标（着）"}, {"form": "陪过", "label": "体标（过）"}, {"form": "陪陪", "label": "重叠"}], "register": "口语", "sense_fingerprint": "跟着别人一起去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪 péi 指陪同、陪伴，正是听到的词。"}, {"text": "配", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、搭配。"}, {"text": "盆", "is_correct": false, "explanation": "pén 与 péi 韵母不同（en 与 ei），意思是花盆、盆子。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 péi 韵母不同（ai 与 ei），意思是排列、排队。"}, {"text": "肥", "is_correct": false, "explanation": "féi 与 péi 声母不同（f 与 p），意思是肥料、肥胖。"}], "explanations": {"陪": "陪 péi 指陪同、陪伴，正是听到的词。", "配": "pèi（第四声）与 péi（第二声）声调不同，意思是配合、搭配。", "盆": "pén 与 péi 韵母不同（en 与 ei），意思是花盆、盆子。", "排": "pái 与 péi 韵母不同（ai 与 ei），意思是排列、排队。", "肥": "féi 与 péi 声母不同（f 与 p），意思是肥料、肥胖。"}, "sentence_index": null, "correct_answer": "陪"}, "level_3": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪：与“去长城参观”相符，表示和客人同行。"}, {"text": "派", "is_correct": false, "explanation": "语义：“派”是指派、差遣，客人不能被派去参观。"}, {"text": "绑", "is_correct": false, "explanation": "语义：“绑”是捆住，与客人自愿同行的语境相反。"}, {"text": "押", "is_correct": false, "explanation": "语义：“押”指押送，带有强制意味，与客人自愿同行不合。"}], "explanations": {"陪": "陪：与“去长城参观”相符，表示和客人同行。", "派": "语义：“派”是指派、差遣，客人不能被派去参观。", "绑": "语义：“绑”是捆住，与客人自愿同行的语境相反。", "押": "语义：“押”指押送，带有强制意味，与客人自愿同行不合。"}, "sentence_index": 0, "correct_answer": "陪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救护车陪病人去医院。", "explanation": "这里应该用〈护送〉。陪的主语要是人，能和被陪的人待在一起，救护车不能陪人，护送病人才这样说。"}, {"text": "这条领带很陪你的衬衫。", "explanation": "这里应该用〈配〉。陪表示和人待在一起，不表示颜色、款式相配，相配才用配。"}, {"text": "他陪我的钱去银行。", "explanation": "这里应该用〈存〉。陪的对象是人，不能说陪钱，去银行存钱才这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88908, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪 péi 指陪同、陪伴，正是听到的词。"}, {"text": "佩", "is_correct": false, "explanation": "pèi（第四声）与 péi（第二声）声调不同，意思是佩服、佩戴。"}, {"text": "没", "is_correct": false, "explanation": "méi 与 péi 声母不同（m 与 p），意思是没有。"}, {"text": "皮", "is_correct": false, "explanation": "pí 与 péi 韵母不同（i 与 ei），意思是皮肤、皮革。"}, {"text": "呸", "is_correct": false, "explanation": "pēi（第一声）与 péi（第二声）声调不同，是表示唾弃的叹词。"}], "explanations": {"陪": "陪 péi 指陪同、陪伴，正是听到的词。", "佩": "pèi（第四声）与 péi（第二声）声调不同，意思是佩服、佩戴。", "没": "méi 与 péi 声母不同（m 与 p），意思是没有。", "皮": "pí 与 péi 韵母不同（i 与 ei），意思是皮肤、皮革。", "呸": "pēi（第一声）与 péi（第二声）声调不同，是表示唾弃的叹词。"}, "sentence_index": null, "correct_answer": "陪"}, "level_3": {"options": [{"text": "陪", "is_correct": true, "explanation": "陪：与“看了一场电影”相符，表示和女朋友一起去看。"}, {"text": "赶", "is_correct": false, "explanation": "搭配：“赶”是催促、驱赶，不能说“赶女朋友看电影”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与一起看电影的语境相反。"}, {"text": "撇", "is_correct": false, "explanation": "语义：“撇”是撇下、丢下，与两人一起看电影的意思矛盾。"}], "explanations": {"陪": "陪：与“看了一场电影”相符，表示和女朋友一起去看。", "赶": "搭配：“赶”是催促、驱赶，不能说“赶女朋友看电影”。", "扔": "语义：“扔”是丢弃，与一起看电影的语境相反。", "撇": "语义：“撇”是撇下、丢下，与两人一起看电影的意思矛盾。"}, "sentence_index": 6, "correct_answer": "陪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我陪了这场比赛三个小时。", "explanation": "这里应该用〈看〉。陪表示和人待在一起，不能说陪比赛，看比赛才用看。"}, {"text": "修理工陪了那辆车一下午。", "explanation": "这里应该用〈修〉。陪的对象是人，不能说陪车，修车才这样说。"}, {"text": "他陪了一杯咖啡。", "explanation": "这里应该用〈点〉。陪的对象是人，不能说陪咖啡，点饮料才这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周都陪了朋友去书店买书。", "corrected_sentence": "我每周都陪朋友去书店买书。", "error_description": "错误：“每周都”表示习惯，“陪”后不能加“了”，应说“陪朋友去书店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我陪地朋友在北京逛了一天。", "corrected_sentence": "我陪着朋友在北京逛了一天。", "error_description": "错误：“陪”后的体标应为“着”，不能用结构助词“地”，应说“陪着朋友”，“陪地朋友”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上去", "is_correct": true, "explanation": "正确。“上去”与“下去”方向相反，指从低处到高处去。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“下去”无反义关系，二者的意义并不相对。"}, {"text": "思考", "is_correct": false, "explanation": "与“下去”无反义关系，二者的意义并不相对。"}, {"text": "读书", "is_correct": false, "explanation": "与“下去”无反义关系，二者的意义并不相对。"}], "correct_answer": "上去", "explanations": {"上去": "正确。“上去”与“下去”方向相反，指从低处到高处去。", "睡觉": "与“下去”无反义关系，二者的意义并不相对。", "思考": "与“下去”无反义关系，二者的意义并不相对。", "读书": "与“下去”无反义关系，二者的意义并不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
