INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下去是从高的地方走到低的地方去。", "primary_collocate": null, "pronunciation": "xià qù", "ipa": "ɕja˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "地下室很黑，你别一个人下去。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从楼上走下去，去买早饭。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先下去，你在这里等我。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山很陡，我们慢慢走下去。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着手电筒下去看看。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯在这里，我们下去吧。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳下去，跑进了花园。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水井很深，没人敢下去。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下有人找你，你下去一下。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他顺着梯子爬下去了。", "target_word": "下去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下去了", "label": "体标"}, {"form": "下去过", "label": "体标"}], "register": "口语", "sense_fingerprint": "从高的地方走到低的地方去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 水井 (Zipf 3.34), 很深 (Zipf 3.25), 没人敢 (Zipf 3.1)']::text[], 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下去", "is_correct": true, "explanation": "正确。“地下室很黑，你别一个人下去”指到地下室去，“下去”表示向低处去。"}, {"text": "上去", "is_correct": false, "explanation": "语义：“地下室”在低处，“上去”指向高处去，与句中的方位矛盾。"}, {"text": "下车", "is_correct": false, "explanation": "搭配：“下车”须以乘坐车辆为前提，句中没有车辆。"}, {"text": "停下", "is_correct": false, "explanation": "语义：“停下”与“你别一个人”所表达的叮嘱语境不合，句意说不通。"}], "explanations": {"下去": "正确。“地下室很黑，你别一个人下去”指到地下室去，“下去”表示向低处去。", "上去": "语义：“地下室”在低处，“上去”指向高处去，与句中的方位矛盾。", "下车": "搭配：“下车”须以乘坐车辆为前提，句中没有车辆。", "停下": "语义：“停下”与“你别一个人”所表达的叮嘱语境不合，句意说不通。"}, "sentence_index": 0, "correct_answer": "下去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山很陡，我们慢慢爬下去到山顶。", "explanation": "这里应该用〈上去〉。山顶在高处，要到高处去应说“上去”，“下去”指往低处去。"}, {"text": "我在楼下等你，你快走下去吧。", "explanation": "这里应该用〈下来〉。说话人在楼下，请对方向说话人所在的方向来应说“下来”，“下去”表示离开。"}, {"text": "这只鸟在地上，想飞到树顶，就飞下去了。", "explanation": "这里应该用〈飞上去〉。从地上到树顶要往高处去，应说“飞上去”，“飞下去”指往低处去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下去", "is_correct": true, "explanation": "正确。“小猫跳下去”指小猫从高处往低处跳，“下去”表示向下。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”指结束工作，小猫不上班，“跳下班”也不成词。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指课程结束，不能放在“跳”后表示动作方向。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能作“跳”的趋向补语。"}], "explanations": {"下去": "正确。“小猫跳下去”指小猫从高处往低处跳，“下去”表示向下。", "下班": "语义：“下班”指结束工作，小猫不上班，“跳下班”也不成词。", "下课": "语义：“下课”指课程结束，不能放在“跳”后表示动作方向。", "下雨": "语义：“下雨”是天气现象，不能作“跳”的趋向补语。"}, "sentence_index": 6, "correct_answer": "下去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想从楼下回到楼上，就爬下去了。", "explanation": "这里应该用〈上去〉。楼上在高处，向高处去应说“上去”，“下去”是往低处去。"}, {"text": "他住在顶楼，下班回家时从一楼走下去了。", "explanation": "这里应该用〈走上去〉。顶楼在高处，从一楼回顶楼要往高处去，应说“走上去”，“走下去”是往低处去。"}, {"text": "他在地下室，想去屋顶看看，就走下去了。", "explanation": "这里应该用〈走上去〉。地下室在最低处，去屋顶要往高处去，应说“走上去”，“走下去”是往低处去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在地下室，你快跑下去。", "corrected_sentence": "我在地下室，你快跑下来。", "error_description": "方向错误：说话人在低处的地下室，请对方从楼上朝说话人所在处过来应说“下来”，不能说“下去”。错误出在目标词“下去”的方向上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在地上，你快从树上爬下去。", "corrected_sentence": "我在地上，你快从树上爬下来。", "error_description": "方向错误：说话人在地上，请对方从树上朝说话人所在处过来应说“下来”，不能说“下去”。错误出在目标词“下去”的方向上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
