INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "直线是一条不弯的线。", "primary_collocate": null, "pronunciation": "zhí xiàn", "ipa": "ʈʂɻ̩˧˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他用尺子在纸上画了一条直线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路很长，几乎是一条直线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟沿着直线飞向远处的树。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们排成一条直线站好。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把绳子拉成了一条直线。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的边是直线，不是曲线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要我们沿着直线走过去。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段铁路几乎是一条直线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥上的灯排成一条直线，很漂亮。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能不能不用尺子，画出一条直线？", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条直线", "label": "量词"}, {"form": "直线距离", "label": "复合词"}, {"form": "直線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中看得见的不弯的线，与曲线相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：直线（zhí xiàn），不弯的线。"}, {"text": "支线", "is_correct": false, "explanation": "支线：zhī（第一声）与 zhí（第二声）声调不同，意思是分支的线路。"}, {"text": "织线", "is_correct": false, "explanation": "织线：zhī（第一声）与 zhí（第二声）声调不同，意思是织布用的线。"}, {"text": "实现", "is_correct": false, "explanation": "实现：shí 与 zhí 声母不同（sh 与 zh），意思是变为现实。"}], "explanations": {"直线": "正确：直线（zhí xiàn），不弯的线。", "支线": "支线：zhī（第一声）与 zhí（第二声）声调不同，意思是分支的线路。", "织线": "织线：zhī（第一声）与 zhí（第二声）声调不同，意思是织布用的线。", "实现": "实现：shí 与 zhí 声母不同（sh 与 zh），意思是变为现实。"}, "sentence_index": null, "correct_answer": "直线"}, "level_3": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：尺子画出的是不弯的线，“一条直线”与“用尺子画”相符。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：“条”用于线状事物，桥应说“座”，不能说“画了一条桥”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头应说“块”或“个”，“画了一条石头”说不通。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：圆一般用“个”计量，“一条圆”说不通；尺子也画不出圆。"}], "explanations": {"直线": "正确：尺子画出的是不弯的线，“一条直线”与“用尺子画”相符。", "桥": "搭配：“条”用于线状事物，桥应说“座”，不能说“画了一条桥”。", "石头": "搭配：石头应说“块”或“个”，“画了一条石头”说不通。", "圆": "搭配：圆一般用“个”计量，“一条圆”说不通；尺子也画不出圆。"}, "sentence_index": 0, "correct_answer": "直线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们排成一棵直线站好。", "explanation": "这里应该用〈条〉。线条用“条”计量；“棵”用于树木，不能用来数直线。"}, {"text": "孩子们排成一块直线站好。", "explanation": "这里应该用〈条〉。“块”用于块状的东西，直线要用“条”计量。"}, {"text": "孩子们排成一颗直线站好。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状或圆形的小东西，直线不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：“沿着直线走过去”说的是沿着一条直的路线走，与句子相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能沿着天空走过去，与“走过去”的语义矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以沿着走的路线，与“沿着……走过去”的语义不符。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“沿着”后面要接路线或路径，“工作”不能与“沿着……走”搭配。"}], "explanations": {"直线": "正确：“沿着直线走过去”说的是沿着一条直的路线走，与句子相符。", "天空": "语义：人不能沿着天空走过去，与“走过去”的语义矛盾。", "空气": "语义：空气不是可以沿着走的路线，与“沿着……走过去”的语义不符。", "工作": "搭配：“沿着”后面要接路线或路径，“工作”不能与“沿着……走”搭配。"}, "sentence_index": 6, "correct_answer": "直线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条直线弯弯曲曲，一直绕到山后。", "explanation": "这里应该用〈曲线〉。直线是不弯的线，“弯弯曲曲”的线应说曲线；这里的描写与直线的含义矛盾。"}, {"text": "这条直线是用一个个小点连起来的，中间断断续续。", "explanation": "这里应该用〈虚线〉。由一个个小点组成、断断续续的线叫虚线；直线是一条不断开的、不弯的线。"}, {"text": "这条直线有好几个拐角。", "explanation": "这里应该用〈折线〉。折线由多段线连成，有拐角；直线笔直，没有拐角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他沿着一块很长的直线走。", "corrected_sentence": "他沿着一条很长的直线走。", "error_description": "“直线”的量词用错了：应说“一条”，“块”用于块状的东西，不能用来计量直线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们沿着这棵直线画了一排点。", "corrected_sentence": "我们沿着这条直线画了一排点。", "error_description": "“直线”的量词用错了：应说“这条直线”，“棵”用于树木，不能用来计量直线。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
