INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不弯曲、向两端无限延伸的线。", "primary_collocate": null, "pronunciation": "zhí xiàn", "ipa": "ʈʂɻ̩˧˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "两点确定一条直线。", "target_word": "直线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "数学课上，老师教我们怎么画直线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过两个点只能画一条直线。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条直线和那条直线是平行的。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两条直线相交的地方叫交点。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在图上，这两个点之间画一条直线。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用直线把这两个点连起来。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直线没有弯，也没有起点和终点。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在图上找出和这条直线垂直的另一条线。", "target_word": "直线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条直线经过了图中的两个点。", "target_word": "直线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条直线", "label": "量词"}, {"form": "直线距离", "label": "复合词"}, {"form": "直線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数学几何里的直线，两端无限延伸，可以平行或相交", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：直线（zhí xiàn），两端无限延伸、不弯的线。"}, {"text": "支线", "is_correct": false, "explanation": "支线：zhī（第一声）与 zhí（第二声）声调不同，意思是分支的线路。"}, {"text": "织线", "is_correct": false, "explanation": "织线：zhī（第一声）与 zhí（第二声）声调不同，意思是织布用的线。"}, {"text": "实现", "is_correct": false, "explanation": "实现：shí 与 zhí 声母不同（sh 与 zh），意思是变为现实。"}], "explanations": {"直线": "正确：直线（zhí xiàn），两端无限延伸、不弯的线。", "支线": "支线：zhī（第一声）与 zhí（第二声）声调不同，意思是分支的线路。", "织线": "织线：zhī（第一声）与 zhí（第二声）声调不同，意思是织布用的线。", "实现": "实现：shí 与 zhí 声母不同（sh 与 zh），意思是变为现实。"}, "sentence_index": null, "correct_answer": "直线"}, "level_3": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：过两点能唯一确定一条直线，与“一条直线”相符。"}, {"text": "曲线", "is_correct": false, "explanation": "语义：经过两点的曲线有无数条，不能说“两点确定一条曲线”。"}, {"text": "折线", "is_correct": false, "explanation": "语义：两点之间可以连出无数条折线，不能说“两点确定一条折线”。"}, {"text": "平面", "is_correct": false, "explanation": "搭配：平面用“个”计量，“一条平面”说不通；过两点的平面有无数个。"}], "explanations": {"直线": "正确：过两点能唯一确定一条直线，与“一条直线”相符。", "曲线": "语义：经过两点的曲线有无数条，不能说“两点确定一条曲线”。", "折线": "语义：两点之间可以连出无数条折线，不能说“两点确定一条折线”。", "平面": "搭配：平面用“个”计量，“一条平面”说不通；过两点的平面有无数个。"}, "sentence_index": 0, "correct_answer": "直线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图上这条直线弯弯曲曲的，像一条蛇。", "explanation": "这里应该用〈曲线〉。直线笔直、没有弯，“弯弯曲曲”的线应说曲线。"}, {"text": "这条直线只有一个端点。", "explanation": "这里应该用〈射线〉。射线只有一个端点；直线两端都不断，没有端点。"}, {"text": "这条直线有好几个拐角。", "explanation": "这里应该用〈折线〉。折线由多段线连成，有拐角；直线笔直，没有拐角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直线", "is_correct": true, "explanation": "正确：用直线连接两点，“连起来”说的是画出一条线。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“连”要接线段或路径，圆是封闭图形，不能用来连接两点。"}, {"text": "平面", "is_correct": false, "explanation": "语义：平面是面，不是线，不能把两个点连起来。"}, {"text": "角", "is_correct": false, "explanation": "语义：角是两条线的夹角，不能用来把两个点连起来。"}], "explanations": {"直线": "正确：用直线连接两点，“连起来”说的是画出一条线。", "圆": "搭配：“连”要接线段或路径，圆是封闭图形，不能用来连接两点。", "平面": "语义：平面是面，不是线，不能把两个点连起来。", "角": "语义：角是两条线的夹角，不能用来把两个点连起来。"}, "sentence_index": 6, "correct_answer": "直线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块直线经过了图中的两个点。", "explanation": "这里应该用〈条〉。“块”用于块状的东西，直线要用“条”计量。"}, {"text": "这棵直线经过了图中的两个点。", "explanation": "这里应该用〈条〉。“棵”用于树木，直线不能用“棵”计量。"}, {"text": "这颗直线经过了图中的两个点。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状或圆形的小东西，直线要用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两块很长的直线互相平行。", "corrected_sentence": "这两条很长的直线互相平行。", "error_description": "“直线”的量词用错了：应说“这两条”，“块”用于块状的东西，不能用来计量直线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请在图上画出这棵直线。", "corrected_sentence": "请在图上画出这条直线。", "error_description": "“直线”的量词用错了：应说“这条直线”，“棵”用于树木，不能用来计量直线。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
