INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88915, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "虽是说\"这样是对的，不过……\"，后面常常有一个\"但是\"。", "primary_collocate": null, "pronunciation": "suī", "ipa": "swei˥", "syllable_count": 1, "sentences": [{"text": "你的想法虽对，但是现在还不能用。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法虽好，但是太贵了。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话虽有道理，可是我不同意。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做虽可以，但是不太方便。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说的虽对，但是语气不太好。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱虽便宜，但是质量不太好。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的意见虽对，我们还是想再试一次。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划虽不错，但是时间太短。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你虽没错，但是也应该说声对不起。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章虽写得好，但是有点长。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虽然", "label": "复合"}, {"form": "虽说", "label": "复合"}], "register": "书面", "sense_fingerprint": "先承认对的一面，再用但是转折", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88915, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确答案。“虽”读 suī（第一声），表示先承认对的一面。"}, {"text": "随", "is_correct": false, "explanation": "suí（第二声）与 suī 声调不同，意思是跟随。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是年岁。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是破碎。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是谷物的穗。"}], "explanations": {"虽": "正确答案。“虽”读 suī（第一声），表示先承认对的一面。", "随": "suí（第二声）与 suī 声调不同，意思是跟随。", "岁": "suì（第四声）与 suī 声调不同，意思是年岁。", "碎": "suì（第四声）与 suī 声调不同，意思是破碎。", "穗": "suì（第四声）与 suī 声调不同，意思是谷物的穗。"}, "sentence_index": null, "correct_answer": "虽"}, "level_3": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确。“虽”先承认“想法对”，后面用“但是”转折，符合句意。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”“还”配合，不能与“但是”搭配。"}, {"text": "与其", "is_correct": false, "explanation": "配价：“与其”要与“不如”成对出现，比较两种选择，句中没有比较项。"}, {"text": "既然", "is_correct": false, "explanation": "语义：“既然”表示据此推断，与后面“但是”的转折不合，想法对并不构成不能用的原因。"}], "explanations": {"虽": "正确。“虽”先承认“想法对”，后面用“但是”转折，符合句意。", "不但": "搭配：“不但”要与“而且”“还”配合，不能与“但是”搭配。", "与其": "配价：“与其”要与“不如”成对出现，比较两种选择，句中没有比较项。", "既然": "语义：“既然”表示据此推断，与后面“但是”的转折不合，想法对并不构成不能用的原因。"}, "sentence_index": 0, "correct_answer": "虽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样做虽可以，所以不太方便。", "explanation": "这里应该用〈但是〉。虽承认了对的一面，后面要用“但是”转折，接“所以”就变成因果，意思不通。"}, {"text": "这样做虽可以，于是不太方便。", "explanation": "这里应该用〈但是〉。“于是”表示结果，不能接在让步的“虽”后面。"}, {"text": "这样做虽可以，因此不太方便。", "explanation": "这里应该用〈但是〉。“因此”表示结果，不能接在让步的“虽”后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88915, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确答案。“虽”读 suī（第一声），表示先承认对的一面。"}, {"text": "推", "is_correct": false, "explanation": "tuī（第一声）与 suī 声母不同，意思是推动。"}, {"text": "吹", "is_correct": false, "explanation": "chuī（第一声）与 suī 声母不同，意思是吹气。"}, {"text": "追", "is_correct": false, "explanation": "zhuī（第一声）与 suī 声母不同，意思是追赶。"}, {"text": "随", "is_correct": false, "explanation": "suí（第二声）与 suī 声调不同，意思是跟随。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是年岁。"}], "explanations": {"虽": "正确答案。“虽”读 suī（第一声），表示先承认对的一面。", "推": "tuī（第一声）与 suī 声母不同，意思是推动。", "吹": "chuī（第一声）与 suī 声母不同，意思是吹气。", "追": "zhuī（第一声）与 suī 声母不同，意思是追赶。", "随": "suí（第二声）与 suī 声调不同，意思是跟随。", "岁": "suì（第四声）与 suī 声调不同，意思是年岁。"}, "sentence_index": null, "correct_answer": "虽"}, "level_3": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确。“虽”先承认“意见对”，后面用“还是”转折，符合句意。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进，与后面“还是想再试”的让步语气不合。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，不能接在让步的“虽”之后，“老师的意见所以对”不成句。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与“就”配合表示条件，不能与“还是”搭配。"}], "explanations": {"虽": "正确。“虽”先承认“意见对”，后面用“还是”转折，符合句意。", "而且": "语义：“而且”表示递进，与后面“还是想再试”的让步语气不合。", "所以": "语义：“所以”表示因果，不能接在让步的“虽”之后，“老师的意见所以对”不成句。", "只要": "搭配：“只要”要与“就”配合表示条件，不能与“还是”搭配。"}, "sentence_index": 6, "correct_answer": "虽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章虽写得好，因而很受欢迎。", "explanation": "这里应该用〈但是〉。虽承认写得好之后要用“但是”转折，接“因而”表示结果，意思不通。"}, {"text": "这篇文章虽写得好，所以有点长。", "explanation": "这里应该用〈但是〉。“所以”表示因果，不能接在让步的“虽”后面。"}, {"text": "这篇文章虽写得好，于是有点长。", "explanation": "这里应该用〈但是〉。“于是”表示结果，不能接在让步的“虽”后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
