INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书虽，可是很有意思。", "corrected_sentence": "这本书虽厚，可是很有意思。", "error_description": "缺少谓语：“虽”后要接形容词“厚”，删去后句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
