INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88916, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示让步，意思是\"虽然\"，后常接\"但\"\"可是\"等。", "primary_collocate": null, "pronunciation": "suī", "ipa": "swei˥", "syllable_count": 1, "sentences": [{"text": "他虽年轻，但经验很丰富。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天虽冷，可是大家都去公园玩。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服虽旧，但是很干净。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路虽远，我们还是走着去了。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店虽小，东西却很多。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她虽累，可是脸上一直带着笑。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子虽不大，但很安静。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我虽不会做饭，但是会洗碗。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书虽很厚，但是不难读。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽不爱说话，但是很会听。", "target_word": "虽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虽然", "label": "复合"}, {"form": "虽说", "label": "复合"}], "register": "书面", "sense_fingerprint": "让步连词，等于虽然，后接但、可是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确答案。“虽”读 suī（第一声），表示让步。"}, {"text": "随", "is_correct": false, "explanation": "suí（第二声）与 suī（第一声）声调不同，意思是跟随。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是年岁。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是谷物的穗。"}, {"text": "绥", "is_correct": false, "explanation": "suí（第二声）与 suī 声调不同，意思是安抚。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suī 声调不同，意思是破碎。"}], "explanations": {"虽": "正确答案。“虽”读 suī（第一声），表示让步。", "随": "suí（第二声）与 suī（第一声）声调不同，意思是跟随。", "岁": "suì（第四声）与 suī 声调不同，意思是年岁。", "穗": "suì（第四声）与 suī 声调不同，意思是谷物的穗。", "绥": "suí（第二声）与 suī 声调不同，意思是安抚。", "碎": "suì（第四声）与 suī 声调不同，意思是破碎。"}, "sentence_index": null, "correct_answer": "虽"}, "level_3": {"options": [{"text": "虽", "is_correct": true, "explanation": "正确。“虽”放在主语后，与后面的“但”配合，表示让步。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，与后面“但”表示的转折矛盾，年轻不是经验丰富的原因。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，句中说的是已经存在的事实，不能用假设。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”“还”配合，不能与“但”搭配。"}], "explanations": {"虽": "正确。“虽”放在主语后，与后面的“但”配合，表示让步。", "因为": "语义：“因为”引出原因，与后面“但”表示的转折矛盾，年轻不是经验丰富的原因。", "如果": "语义：“如果”表示假设，句中说的是已经存在的事实，不能用假设。", "不但": "搭配：“不但”要与“而且”“还”配合，不能与“但”搭配。"}, "sentence_index": 0, "correct_answer": "虽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路虽远，所以我们走着去了。", "explanation": "这里应该用〈还是〉或〈但〉。虽表示让步，后面要接转折，不能接表示因果的“所以”。"}, {"text": "他虽会唱歌，然后会跳舞。", "explanation": "这里应该用〈但〉。虽引出让步，要接“但”或“可是”转折；“然后”表示先后，不能接在“虽”后面。"}, {"text": "他虽不聪明，于是考试得了第一名。", "explanation": "这里应该用〈但〉。虽引出的让步句要接“但”或“可是”，“于是”表示结果，不能接在“虽”后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
