INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88920, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "各个不同；与众不同。", "primary_collocate": null, "pronunciation": "gè bié", "ipa": "kɤ˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这些花的颜色各别，有红的，也有黄的。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的习惯各别，我们要互相尊重。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人的答案各别，没有一个和别人相同。", "target_word": "各别", "complexity_tier": "T3", "furigana": "jǐ gè rén de dá àn gè bié, méi yǒu yí gè hé bié rén xiāng tóng.", "sentence_source": "generated"}, {"text": "这套茶具的造型各别，没有两个是完全一样的。", "target_word": "各别", "complexity_tier": "T3", "furigana": "zhè tào chá jù de zào xíng gè bié, méi yǒu liǎng gè shì wán quán yí yàng de.", "sentence_source": "generated"}, {"text": "大家的性格各别，所以相处的方式也不同。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几位画家的画风各别，别人很难学得像。", "target_word": "各别", "complexity_tier": "T3", "furigana": "zhè jǐ wèi huà jiā de huà fēng gè bié, bié rén hěn nán xué de xiàng.", "sentence_source": "generated"}, {"text": "同一个班的学生，水平也各别，有高有低。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的这几件外套款式各别，大家都说他很会穿。", "target_word": "各别", "complexity_tier": "T3", "furigana": "tā de zhè jǐ jiàn wài tào kuǎn shì gè bié, dà jiā dōu shuō tā hěn huì chuān.", "sentence_source": "generated"}, {"text": "这座城市的建筑各别，没有一栋是重复的。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的画各别，每一张都有自己的想法。", "target_word": "各别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容各个不同，彼此有差别，或与众不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各别", "is_correct": true, "explanation": "正确：各别表示彼此不同，与“有红的，也有黄的”相符。"}, {"text": "统一", "is_correct": false, "explanation": "语义：统一说颜色完全相同，与“有红的，也有黄的”矛盾。"}, {"text": "单调", "is_correct": false, "explanation": "语义：单调说颜色变化少，与“有红的，也有黄的”的颜色多样矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：沉重形容分量或心情，不用来说花的颜色。"}], "explanations": {"各别": "正确：各别表示彼此不同，与“有红的，也有黄的”相符。", "统一": "语义：统一说颜色完全相同，与“有红的，也有黄的”矛盾。", "单调": "语义：单调说颜色变化少，与“有红的，也有黄的”的颜色多样矛盾。", "沉重": "搭配：沉重形容分量或心情，不用来说花的颜色。"}, "sentence_index": 0, "correct_answer": "各别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有各别选手迟到了，比赛推迟了十分钟。", "explanation": "这里应该用〈个别〉。个别表示少数几个，用来说“有个别选手迟到”；各别表示彼此不同，不能指少数选手。"}, {"text": "这次调薪，各别员工还没收到通知。", "explanation": "这里应该用〈个别〉。个别表示少数人，用来说“个别员工还没收到通知”；各别表示彼此不同，不能指少数员工。"}, {"text": "各别学生站在门口。", "explanation": "这里应该用〈个别〉。个别表示少数几个，用来说“个别学生站在门口”；各别表示彼此不同，不能指少数学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各别", "is_correct": true, "explanation": "正确：各别表示水平彼此不同，与“有高有低”相符。"}, {"text": "相同", "is_correct": false, "explanation": "语义：相同说水平一样，与“有高有低”矛盾。"}, {"text": "一致", "is_correct": false, "explanation": "语义：一致说水平统一，与“有高有低”矛盾。"}, {"text": "贫穷", "is_correct": false, "explanation": "搭配：贫穷形容经济状况，不用来说学生的水平。"}], "explanations": {"各别": "正确：各别表示水平彼此不同，与“有高有低”相符。", "相同": "语义：相同说水平一样，与“有高有低”矛盾。", "一致": "语义：一致说水平统一，与“有高有低”矛盾。", "贫穷": "搭配：贫穷形容经济状况，不用来说学生的水平。"}, "sentence_index": 6, "correct_answer": "各别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次展览有各别作品还没有挂出来。", "explanation": "这里应该用〈个别〉。个别表示少数，用来说“个别作品还没挂出”；各别表示彼此不同，不能指少数作品。"}, {"text": "班上有各别孩子今天没来上课。", "explanation": "这里应该用〈个别〉。个别表示少数，用来说“个别孩子没来”；各别表示彼此不同，不能指少数孩子。"}, {"text": "这次活动的各别环节出了问题，但大体顺利。", "explanation": "这里应该用〈个别〉。个别表示少数，用来说“个别环节出了问题”；各别表示彼此不同，不能指少数环节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几条裙子的颜色各别着，有蓝的，也有粉的。", "corrected_sentence": "这几条裙子的颜色各别，有蓝的，也有粉的。", "error_description": "“各别”是形容词，表示彼此不同，不能加动态助词“着”，应去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几幅画的风格各别地，每一幅都很有个性。", "corrected_sentence": "这几幅画的风格各别，每一幅都很有个性。", "error_description": "“各别”在这里作谓语，不加“地”，应去掉“地”，说“风格各别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
