INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对智力劳动成果依法享有的专有权利，如著作权、专利权、商标权。", "primary_collocate": null, "pronunciation": "zhī shi chǎn quán", "ipa": "ʈʂɻ̩˥ ʂɻ̩ ʈʂʰan˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "公司申请了专利，保护自己的知识产权。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "著作权、专利权和商标权都属于知识产权。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家越来越重视知识产权保护。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人抄袭他的作品，侵犯了他的知识产权。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知识产权法保护作者和发明人的权利。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有很多知识产权，每年收入很高。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师帮我们办理了知识产权登记。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用别人的图片之前，要问清楚知识产权属于谁。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业靠知识产权保护新产品。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一门知识产权课，讲专利和商标。", "target_word": "知识产权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "正式", "sense_fingerprint": "法律意义上的专利权、著作权、商标权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知识产权", "is_correct": true, "explanation": "正确。“保护自己的”后接的是专利、著作权等智力成果的专有权利。"}, {"text": "土地", "is_correct": false, "explanation": "语义：句中“申请了专利”说明被保护的是智力成果，土地不是智力成果，不能靠专利保护。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不能申请专利或被保护，与句意不合。"}, {"text": "水源", "is_correct": false, "explanation": "语义：“申请了专利”指向智力成果，水源不是专利所能保护的对象。"}], "explanations": {"知识产权": "正确。“保护自己的”后接的是专利、著作权等智力成果的专有权利。", "土地": "语义：句中“申请了专利”说明被保护的是智力成果，土地不是智力成果，不能靠专利保护。", "温度": "语义：“温度”指冷热程度，不能申请专利或被保护，与句意不合。", "水源": "语义：“申请了专利”指向智力成果，水源不是专利所能保护的对象。"}, "sentence_index": 0, "correct_answer": "知识产权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的知识产权很高，常常帮人解答问题。", "explanation": "这里应该用〈学历〉。“学历”指受教育的经历和程度，可以说“高”；知识产权是法律上的专有权利，不能说“高”。"}, {"text": "这套房子的知识产权写在他的名下。", "explanation": "这里应该用〈产权〉。房子是有形财产，产权指财产的所有权；知识产权只针对智力成果。"}, {"text": "他把自己的知识产权存进了银行，每年拿利息。", "explanation": "这里应该用〈存款〉。能存进银行、拿利息的是钱；知识产权是对智力成果的法定专有权利，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知识产权", "is_correct": true, "explanation": "正确。“知识产权登记”指办理专利、商标等权利的登记，是固定搭配。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“办理”常接手续、业务，不说“办理午饭”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能登记，句中“律师帮我们办理了”的对象必须是权利或手续。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能作为“登记”的对象，与律师办理的业务不符。"}], "explanations": {"知识产权": "正确。“知识产权登记”指办理专利、商标等权利的登记，是固定搭配。", "午饭": "搭配：“办理”常接手续、业务，不说“办理午饭”。", "心情": "语义：心情不能登记，句中“律师帮我们办理了”的对象必须是权利或手续。", "冰箱": "语义：冰箱是家用电器，不能作为“登记”的对象，与律师办理的业务不符。"}, "sentence_index": 6, "correct_answer": "知识产权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一把知识产权。", "explanation": "量词错误：“知识产权”应用〈项〉。〈把〉用于有柄的器具，不能修饰知识产权。"}, {"text": "这家公司申请了一张知识产权。", "explanation": "量词错误：“知识产权”应用〈项〉。〈张〉用于纸张、平面物，不能修饰知识产权。"}, {"text": "这家店卖了一辆知识产权。", "explanation": "量词错误：“知识产权”应用〈项〉。〈辆〉用于车辆，不能修饰知识产权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把一座知识产权保护得很好。", "corrected_sentence": "我们把一项知识产权保护得很好。", "error_description": "量词错误：“知识产权”的量词应为“项”，“座”用于山、房屋等大型固定物，不能修饰知识产权。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司拥有三台知识产权。", "corrected_sentence": "这家公司拥有三项知识产权。", "error_description": "量词错误：“知识产权”的量词应为“项”，“台”用于机器、仪器等，不能修饰知识产权。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高人是本领很高、比一般人强很多的人。", "primary_collocate": null, "pronunciation": "gāo rén", "ipa": "kau˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他是做饭的高人，什么菜都会做。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人下棋很厉害，是个高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里住着一位高人，会很多功夫。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想学好书法，最好去找个高人指点。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司来了一位修电脑的高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别小看他，他可是个高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到了高人，我的问题一下子就解决了。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间有很多高人，他们都不出名。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画画得太好了，真是个高人！", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拜一位高人为师，学打太极。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "本领比一般人强很多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新手", "is_correct": false, "explanation": "语义：“新手”指刚入门的人，不可能什么菜都会做，与后半句矛盾。"}, {"text": "高人", "is_correct": true, "explanation": "“高人”指本领很高、比一般人强很多的人，与“什么菜都会做”相符。"}, {"text": "废物", "is_correct": false, "explanation": "语义：“废物”指没用的人，与“什么菜都会做”矛盾。"}, {"text": "外行", "is_correct": false, "explanation": "语义：“外行”指不懂行的人，与“什么菜都会做”的本领描述相矛盾。"}], "explanations": {"新手": "语义：“新手”指刚入门的人，不可能什么菜都会做，与后半句矛盾。", "高人": "“高人”指本领很高、比一般人强很多的人，与“什么菜都会做”相符。", "废物": "语义：“废物”指没用的人，与“什么菜都会做”矛盾。", "外行": "语义：“外行”指不懂行的人，与“什么菜都会做”的本领描述相矛盾。"}, "sentence_index": 0, "correct_answer": "高人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候很胆小，见到生人就躲到妈妈身后，是个高人。", "explanation": "这里应该用〈胆小鬼〉。“高人”指本领很高、比一般人强很多的人，不能用来形容胆小、见人就躲的孩子。"}, {"text": "他是班里最用功的高人，每天都第一个到教室。", "explanation": "这里应该用〈学生〉。“高人”指本领高强、能给人指点的人，不指正在求学的人；说人在读书，要用“学生”。"}, {"text": "他是邻居家的高人，今年刚上小学。", "explanation": "这里应该用〈孩子〉。“高人”指本领高强的人，不能用来说刚上小学的年幼孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学徒", "is_correct": false, "explanation": "语义：“学徒”指正在学艺的人，不可能一下子解决别人的难题，与后半句矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指生病的人，与能帮人一下子解决问题的本领无关，句子不通。"}, {"text": "高人", "is_correct": true, "explanation": "“高人”指本领很高的人，遇到他才能让问题一下子解决，与后半句相符。"}, {"text": "坏蛋", "is_correct": false, "explanation": "语义：“坏蛋”指品行不好的人，不会帮我解决问题，与“我的问题一下子就解决了”矛盾。"}], "explanations": {"学徒": "语义：“学徒”指正在学艺的人，不可能一下子解决别人的难题，与后半句矛盾。", "病人": "语义：“病人”指生病的人，与能帮人一下子解决问题的本领无关，句子不通。", "高人": "“高人”指本领很高的人，遇到他才能让问题一下子解决，与后半句相符。", "坏蛋": "语义：“坏蛋”指品行不好的人，不会帮我解决问题，与“我的问题一下子就解决了”矛盾。"}, "sentence_index": 6, "correct_answer": "高人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是刚学乒乓球的高人，总是输给别人。", "explanation": "这里应该用〈初学者〉。“高人”指本领高超、能给人指点的人，刚学球、常输的人不能说“高人”。"}, {"text": "村里新建了一所高人，孩子们很高兴。", "explanation": "这里应该用〈学校〉。“高人”指人，不能用来指学校这样的机构。"}, {"text": "他刚拿到驾照，还是个高人，上路总有点紧张。", "explanation": "这里应该用〈新手〉。“高人”指本领高超、能给人指点的人，刚拿到驾照、还不熟练的人不能说“高人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里的老人都说，他是一只高人，什么事都能指点。", "corrected_sentence": "村里的老人都说，他是一位高人，什么事都能指点。", "error_description": "量词错误：“高人”指人，应说“一位高人”，不能说“一只高人”。“只”用于动物或成对的器物，把它用在人身上是常见的学习错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老先生平时话不多，却很高人。", "corrected_sentence": "那位老先生平时话不多，却是个高人。", "error_description": "用词错误：“高人”是名词，不能受“很”修饰，应说“是个高人”。把形容词“高”的用法套用到名词上，是常见的学习错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
