INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本领高强、见识超群的人。", "primary_collocate": null, "pronunciation": "gāo rén", "ipa": "kau˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他看问题很深，是位见识很广的高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这位高人的话，我明白了很多道理。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说，这件事要请高人来看一看。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很普通，其实是个高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讲的道理很透彻，真是高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题时，我总去请教那位高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位高人只说了几句话，就让大家明白了。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的高人常常住在深山里。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天遇到一位高人，他教了我很多。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是普通人，而是一位真正的高人。", "target_word": "高人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "本领高强、见识超群，能给人指点的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文盲", "is_correct": false, "explanation": "语义：“文盲”指不识字的人，与“见识很广”的描述相矛盾。"}, {"text": "醉鬼", "is_correct": false, "explanation": "语域：“醉鬼”是贬斥口语，用来夸人看问题深不合语域，且与“见识很广”矛盾。"}, {"text": "高人", "is_correct": true, "explanation": "“高人”指本领高强、见识超群的人，与“看问题很深”“见识很广”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会说话，不可能见识很广，与句子的赞扬相矛盾。"}], "explanations": {"文盲": "语义：“文盲”指不识字的人，与“见识很广”的描述相矛盾。", "醉鬼": "语域：“醉鬼”是贬斥口语，用来夸人看问题深不合语域，且与“见识很广”矛盾。", "高人": "“高人”指本领高强、见识超群的人，与“看问题很深”“见识很广”相符。", "婴儿": "语义：“婴儿”还不会说话，不可能见识很广，与句子的赞扬相矛盾。"}, "sentence_index": 0, "correct_answer": "高人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个高人才五岁，正在学写字。", "explanation": "这里应该用〈小朋友〉。“高人”指本领高强、见识超群的人，不能用来说年纪只有五岁的孩子。"}, {"text": "他刚进店，还是个高人，手艺不太熟练。", "explanation": "这里应该用〈学徒〉。“高人”指本领高强、见识超群的人，刚进门、还在学艺的人应说“学徒”。"}, {"text": "高人躺在摇篮里，哭个不停。", "explanation": "这里应该用〈婴儿〉。“高人”指本领高强的人，不能用来指躺在摇篮里哭闹的婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哑巴", "is_correct": false, "explanation": "体貌：“哑巴”指不能说话，与“只说了几句话”矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会说话，不可能“说了几句话就让大家明白”，与句意矛盾。"}, {"text": "高人", "is_correct": true, "explanation": "“高人”指本领高强、能给人指点的人，只说几句话就让大家明白，与句意相符。"}, {"text": "醉汉", "is_correct": false, "explanation": "语义：“醉汉”指喝醉酒的人，说话含糊，不可能只说几句话就让大家明白，与句意矛盾。"}], "explanations": {"哑巴": "体貌：“哑巴”指不能说话，与“只说了几句话”矛盾。", "婴儿": "语义：“婴儿”还不会说话，不可能“说了几句话就让大家明白”，与句意矛盾。", "高人": "“高人”指本领高强、能给人指点的人，只说几句话就让大家明白，与句意相符。", "醉汉": "语义：“醉汉”指喝醉酒的人，说话含糊，不可能只说几句话就让大家明白，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "高人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场棋赛里，他只是个高人，连输了三局。", "explanation": "这里应该用〈菜鸟〉。“高人”指见识超群、能给人指点的人，连输几局、水平还很低的人应说“菜鸟”。"}, {"text": "这家高人的菜很好吃，很多人慕名而来。", "explanation": "这里应该用〈饭馆〉。“高人”指人，不能用来指饭馆这样的地方。"}, {"text": "他是公司里的高人，业务还不熟，常常出错。", "explanation": "这里应该用〈新人〉。“高人”指本领高强的人，刚进公司、业务还不熟的人应说“新人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师傅不爱说话，却是一条见识超群的高人。", "corrected_sentence": "这位老师傅不爱说话，却是一位见识超群的高人。", "error_description": "量词错误：“高人”指人，要用量词“位”或“个”，不能用“条”。应说“一位高人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街坊都说，老先生很高人，凡事看得很透。", "corrected_sentence": "街坊都说，老先生是个高人，凡事看得很透。", "error_description": "用词错误：“高人”是名词，不能受“很”修饰，应说“是个高人”。把形容词“高”的用法套用到名词上，是常见的学习错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
