INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88925, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同路是跟别人走同一条路。", "primary_collocate": null, "pronunciation": "tóng lù", "ipa": "tʰʊŋ˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "你也去地铁站吗？我们正好同路。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他回家的时候不同路。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你住哪儿？说不定我们同路。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩上班同路，常常一起走。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，我和小王同路走了一段。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去图书馆，我去超市，我们不同路。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你也往东走吗？那我们同路。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天和邻居同路去学校。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只同路到前面的路口。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我和同学同路回家，一路上聊了很多。", "target_word": "同路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同路人", "label": "复合"}, {"form": "不同路", "label": "否定"}], "register": "中性", "sense_fingerprint": "跟别人走同一条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同路", "is_correct": true, "explanation": "同路：跟别人走同一条路，正确答案。"}, {"text": "通路", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，通路指可以通行的道路。"}, {"text": "同步", "is_correct": false, "explanation": "bù 与 lù 声母不同（b／l），同步指同时进行、步调一致。"}, {"text": "同住", "is_correct": false, "explanation": "zhù 与 lù 声母不同（zh／l），同住指住在一起。"}], "explanations": {"同路": "同路：跟别人走同一条路，正确答案。", "通路": "tōng（第一声）与 tóng（第二声）声调不同，通路指可以通行的道路。", "同步": "bù 与 lù 声母不同（b／l），同步指同时进行、步调一致。", "同住": "zhù 与 lù 声母不同（zh／l），同住指住在一起。"}, "sentence_index": null, "correct_answer": "同路"}, "level_3": {"options": [{"text": "同路", "is_correct": true, "explanation": "“同路”指走同一条路，与“你也去地铁站吗”的同向语境相符。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”指各走各的，与“也去地铁站”的同向前提相反。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是随意走走，与前句去地铁站的目的不符。"}, {"text": "迷路", "is_correct": false, "explanation": "搭配：“迷路”指找不到方向，不能用“我们正好迷路”来回应去地铁站的问题。"}], "explanations": {"同路": "“同路”指走同一条路，与“你也去地铁站吗”的同向语境相符。", "分开": "语义：“分开”指各走各的，与“也去地铁站”的同向前提相反。", "散步": "语义：“散步”是随意走走，与前句去地铁站的目的不符。", "迷路": "搭配：“迷路”指找不到方向，不能用“我们正好迷路”来回应去地铁站的问题。"}, "sentence_index": 0, "correct_answer": "同路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩对这件事的看法同路，所以很快就做出了决定。", "explanation": "这里应该用〈一致〉。同路只指人一起走同一条路，看法、想法不能说同路。"}, {"text": "这两台机器同路运转，声音很整齐。", "explanation": "这里应该用〈同步〉。同路指人或车辆走同一条路，机器运转要说同步。"}, {"text": "他和我同路，都是医生。", "explanation": "这里应该用〈同行〉。同路指走同一条路，两人职业相同要说同行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同路", "is_correct": true, "explanation": "“同路”表示同向、顺路，与“你也往东走吗”的前提一致。"}, {"text": "转弯", "is_correct": false, "explanation": "语义：“转弯”指改变行进方向，与“也往东走”的同向前提相反。"}, {"text": "迁居", "is_correct": false, "explanation": "语义：“迁居”指搬家，与问话里同向走路的语境无关。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“那我们结婚”接在“你也往东走吗”之后无法作为回应，语义不通。"}], "explanations": {"同路": "“同路”表示同向、顺路，与“你也往东走吗”的前提一致。", "转弯": "语义：“转弯”指改变行进方向，与“也往东走”的同向前提相反。", "迁居": "语义：“迁居”指搬家，与问话里同向走路的语境无关。", "结婚": "搭配：“那我们结婚”接在“你也往东走吗”之后无法作为回应，语义不通。"}, "sentence_index": 6, "correct_answer": "同路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一个人同路回家，一路上很安静。", "explanation": "同路指两人或两人以上一起走同一条路，只有一个人时不能说同路，这里应该说〈独自〉。"}, {"text": "我的手机和你的同路，都是去年买的。", "explanation": "这里应该用〈同样〉。同路指走同一条路，两样东西一样要说同样。"}, {"text": "我们同路去相反的方向，所以一直没有见面。", "explanation": "同路要求走同一方向，“相反的方向”与之矛盾，这里应该说〈分开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天和同事同路了上班。", "corrected_sentence": "我每天和同事同路去上班。", "error_description": "错误在“了”：“同路”是动词，后面不能直接加“了”，应说“同路去上班”，用“去”来带出动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学后，我和同学同路了去车站。", "corrected_sentence": "放学后，我和同学同路去了车站。", "error_description": "错误在“了”的位置：“了”表示完成，应放在动词“去”之后，不能直接放在“同路”后面，应说“同路去了车站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
