INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消息、声音等由一处传到另一处；传播。", "primary_collocate": null, "pronunciation": "chuán", "ipa": "ʈʂʰwan˧˥", "syllable_count": 1, "sentences": [{"text": "这个好消息很快就传开了。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处传来了一阵歌声。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里传出了笑声。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "声音在水里传得很快。", "target_word": "传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的歌声传得很远。", "target_word": "传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的话传到了老板那儿。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事一传出去，大家都知道了。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钟声传遍了整个小镇。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏消息传得比好消息快。", "target_word": "传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话里传来了妈妈的声音。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传了", "label": "体标（了）"}, {"form": "传过", "label": "体标（过）"}, {"form": "傳", "label": "繁体"}], "register": "通用", "sense_fingerprint": "传：消息、声音等传递、传播", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传", "is_correct": true, "explanation": "传：chuán（第二声），消息、声音等传递、传播，即本义的读音。"}, {"text": "穿", "is_correct": false, "explanation": "穿（chuān，第一声）与传（chuán，第二声）声调不同，意思是穿。"}, {"text": "床", "is_correct": false, "explanation": "床（chuáng）与传（chuán）韵母不同（ang 与 an），声调相同，意思是床。"}, {"text": "喘", "is_correct": false, "explanation": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。"}], "explanations": {"传": "传：chuán（第二声），消息、声音等传递、传播，即本义的读音。", "穿": "穿（chuān，第一声）与传（chuán，第二声）声调不同，意思是穿。", "床": "床（chuáng）与传（chuán）韵母不同（ang 与 an），声调相同，意思是床。", "喘": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "传"}, "level_3": {"options": [{"text": "传", "is_correct": true, "explanation": "传：消息传播开，与“很快就……开了”搭配。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是用力使物体移动，好消息不能被推开。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿开”的对象是具体物品，不能说拿开消息。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔开”指猛力摔，好消息不能被摔开。"}], "explanations": {"传": "传：消息传播开，与“很快就……开了”搭配。", "推": "语义：“推”是用力使物体移动，好消息不能被推开。", "拿": "搭配：“拿开”的对象是具体物品，不能说拿开消息。", "摔": "语义：“摔开”指猛力摔，好消息不能被摔开。"}, "sentence_index": 0, "correct_answer": "传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨滴传到了地上。", "explanation": "这里应该用〈落〉。“传”用于声音、消息的扩散，不能说雨滴传到地上，雨滴下落要用“落”。"}, {"text": "烟囱里传出了黑烟。", "explanation": "这里应该用〈冒〉。“传出”多用于声音、消息，黑烟从烟囱里冒出要用“冒”。"}, {"text": "树叶传了下来。", "explanation": "这里应该用〈掉〉。“传”没有“落下”的意思，树叶下落要用“掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88928, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "传", "is_correct": true, "explanation": "传：chuán（第二声），消息、声音等传递、传播，即本义的读音。"}, {"text": "串", "is_correct": false, "explanation": "串（chuàn，第四声）与传（chuán，第二声）声调不同，意思是成串的东西。"}, {"text": "川", "is_correct": false, "explanation": "川（chuān，第一声）与传（chuán，第二声）声调不同，意思是河流。"}, {"text": "喘", "is_correct": false, "explanation": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。"}], "explanations": {"传": "传：chuán（第二声），消息、声音等传递、传播，即本义的读音。", "串": "串（chuàn，第四声）与传（chuán，第二声）声调不同，意思是成串的东西。", "川": "川（chuān，第一声）与传（chuán，第二声）声调不同，意思是河流。", "喘": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "传"}, "level_3": {"options": [{"text": "传", "is_correct": true, "explanation": "传：消息传开，与“一……出去，大家都知道了”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体物品，不能说扔出去一件事。"}, {"text": "抬", "is_correct": false, "explanation": "搭配：“抬”指用手托起重物，不能说抬出去一件事。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是打击使物体破碎，与事情传开的意思不合。"}], "explanations": {"传": "传：消息传开，与“一……出去，大家都知道了”搭配。", "扔": "搭配：“扔”的对象是具体物品，不能说扔出去一件事。", "抬": "搭配：“抬”指用手托起重物，不能说抬出去一件事。", "砸": "语义：“砸”是打击使物体破碎，与事情传开的意思不合。"}, "sentence_index": 6, "correct_answer": "传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画传在墙上。", "explanation": "这里应该用〈挂〉。“传”不表示悬挂，把画挂在墙上要用“挂”。"}, {"text": "河水传得很快。", "explanation": "这里应该用〈流〉。“传”用于声音、消息，不能说水传得快。"}, {"text": "他在纸上传下了名字。", "explanation": "这里应该用〈写〉。“传”不表示书写，写下名字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息很快就传了全校。", "corrected_sentence": "这个消息很快就传遍了全校。", "error_description": "“传”后缺少补语“遍”，应说“传遍了全校”。只说“传了全校”，表示传播范围的补语缺失，不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在屋里，笑声从窗外传去了我的耳朵。", "corrected_sentence": "我在屋里，笑声从窗外传进了我的耳朵。", "error_description": "“传”后的趋向补语应指向说话人，声音传入“我的耳朵”要用“进”；“去”表示离开说话人，方向相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
