INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "破坏活动是故意把东西弄坏的事。", "primary_collocate": null, "pronunciation": "pò huài huó dòng", "ipa": "pʰwo˥˩ xwai˥˩ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "警察抓住了在公园里搞破坏活动的人。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人把学校的椅子都砸坏了，这是破坏活动。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉孩子，破坏活动是不对的。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里有人在车站搞破坏活动，打碎了很多玻璃。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店最近常有破坏活动，门和窗都坏了。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为参加破坏活动，赔了很多钱。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安晚上在门口看着，防止破坏活动。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里的破坏活动让邻居们很生气。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在墙上乱画，这也是一种破坏活动。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看见几个孩子搞破坏活动，马上喊了起来。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破壞活動", "label": "繁体"}], "register": "书面", "sense_fingerprint": "故意弄坏东西的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摄影", "is_correct": false, "explanation": "语义：摄影是爱好，不违法，警察不会因此抓人。"}, {"text": "破坏活动", "is_correct": true, "explanation": "正确：警察抓的是故意弄坏东西的人，“破坏活动”符合语境。"}, {"text": "体育活动", "is_correct": false, "explanation": "语义：体育活动不违法，与“抓住”的语境不合。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“搞”不能接“风景”，要说“看”或“拍”。"}], "explanations": {"摄影": "语义：摄影是爱好，不违法，警察不会因此抓人。", "破坏活动": "正确：警察抓的是故意弄坏东西的人，“破坏活动”符合语境。", "体育活动": "语义：体育活动不违法，与“抓住”的语境不合。", "风景": "搭配：“搞”不能接“风景”，要说“看”或“拍”。"}, "sentence_index": 0, "correct_answer": "破坏活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场破坏活动是司机没注意造成的。", "explanation": "这里应该用〈事故〉。破坏活动是故意弄坏或扰乱，司机不小心造成的应说〈事故〉。"}, {"text": "夜里车站出现了一条破坏活动。", "explanation": "量词用错。〈条〉用于长条形的东西，活动应用〈次〉或〈场〉。"}, {"text": "我们每天下午做破坏活动。", "explanation": "这里应该用〈运动〉。破坏活动是故意弄坏东西，每天锻炼身体应说〈运动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌声", "is_correct": false, "explanation": "语义：掌声是好事，“防止”针对的应是坏事。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不是需要保安防止的事。"}, {"text": "破坏活动", "is_correct": true, "explanation": "正确：保安防止的是坏事，“破坏活动”符合语境。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“防止”接的是不希望发生的事，不能接“散步”。"}], "explanations": {"掌声": "语义：掌声是好事，“防止”针对的应是坏事。", "生日": "语义：生日不是需要保安防止的事。", "破坏活动": "正确：保安防止的是坏事，“破坏活动”符合语境。", "散步": "搭配：“防止”接的是不希望发生的事，不能接“散步”。"}, "sentence_index": 6, "correct_answer": "破坏活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校每年都举办破坏活动，邀请家长来参加。", "explanation": "语义错误：〈破坏活动〉指故意弄坏的行为，这里误用成了“有计划组织的正式集体活动”的意思。"}, {"text": "妈妈在厨房里做破坏活动，准备晚饭。", "explanation": "语义错误：〈破坏活动〉是故意弄坏，做饭应说〈做饭〉。"}, {"text": "孩子们在操场上玩破坏活动，跳绳、踢球。", "explanation": "语义错误：跳绳、踢球是体育游戏，不是故意弄坏，应说〈运动〉或〈游戏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条破坏活动造成了很大损失。", "corrected_sentence": "这次破坏活动造成了很大损失。", "error_description": "量词用错：破坏活动应该用〈次〉或〈场〉，〈条〉用于长条形的东西。正确说法是“这次破坏活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经参加了一只破坏活动。", "corrected_sentence": "他曾经参加了一次破坏活动。", "error_description": "量词用错：破坏活动应该用〈次〉或〈场〉，〈只〉用于动物等，不能用于活动。正确说法是“一次破坏活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
