INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "蓄意损毁或扰乱的行动。", "primary_collocate": null, "pronunciation": "pò huài huó dòng", "ipa": "pʰwo˥˩ xwai˥˩ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "警方说，这是有人安排的破坏活动。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的破坏活动让工厂停了三天。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府一直在调查这次破坏活动的原因。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时有人进行破坏活动，比赛只好停下来。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织曾经做过很多破坏活动。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络上的破坏活动让网站打不开了。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在会场外搞破坏活动，会议没法开了。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发现有人对系统进行破坏活动，马上报了警。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用破坏活动让大家害怕。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何破坏活动，抓到的人要受罚。", "target_word": "破坏活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破壞活動", "label": "繁体"}], "register": "书面", "sense_fingerprint": "蓄意损毁或扰乱的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体形", "is_correct": false, "explanation": "体貌：体形是身体特征，不是可以被人“安排”的事件。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能说“安排”，应说“选择”或“搭配”。"}, {"text": "破坏活动", "is_correct": true, "explanation": "正确：警方说这是有人安排的蓄意行动，“破坏活动”符合语境。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格不是人为安排的事，句子说的是有人策划的行动。"}], "explanations": {"体形": "体貌：体形是身体特征，不是可以被人“安排”的事件。", "颜色": "搭配：颜色不能说“安排”，应说“选择”或“搭配”。", "破坏活动": "正确：警方说这是有人安排的蓄意行动，“破坏活动”符合语境。", "性格": "语义：性格不是人为安排的事，句子说的是有人策划的行动。"}, "sentence_index": 0, "correct_answer": "破坏活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚会上，同学们为老师准备了一个破坏活动节目。", "explanation": "这里应该用〈表演〉。破坏活动是蓄意损毁或扰乱的行动，不是晚会上给大家看的节目。"}, {"text": "会场里出现了一块破坏活动。", "explanation": "量词用错。〈块〉用于块状的东西，破坏活动应用〈起〉或〈次〉。"}, {"text": "他们的破坏活动很漂亮，大家都夸他们。", "explanation": "语义错误：〈破坏活动〉指蓄意损毁或扰乱的行动，这里误用成了“值得欣赏的美好作品”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午餐", "is_correct": false, "explanation": "语义：午餐不会让会议没法开，句子说的是有人制造的破坏。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“搞”不能接“散步”。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会让会议停下来，句子说的是破坏行动。"}, {"text": "破坏活动", "is_correct": true, "explanation": "正确：会场外的破坏行动导致会议没法开，符合语境。"}], "explanations": {"午餐": "语义：午餐不会让会议没法开，句子说的是有人制造的破坏。", "散步": "搭配：“搞”不能接“散步”。", "花朵": "语义：花朵不会让会议停下来，句子说的是破坏行动。", "破坏活动": "正确：会场外的破坏行动导致会议没法开，符合语境。"}, "sentence_index": 6, "correct_answer": "破坏活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上在操场上进行破坏活动，锻炼身体。", "explanation": "语义错误：〈破坏活动〉是蓄意损毁或扰乱，锻炼身体应说〈运动〉。"}, {"text": "志愿者们进行破坏活动，帮助了很多困难的人。", "explanation": "语义错误：〈破坏活动〉是有害的行为，不能用来帮助人，应说〈志愿活动〉。"}, {"text": "我们进行破坏活动，庆祝了妈妈的生日。", "explanation": "语义错误：〈破坏活动〉与庆祝相反，庆祝生日应说〈庆祝活动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只破坏活动是有人故意策划的。", "corrected_sentence": "这起破坏活动是有人故意策划的。", "error_description": "量词用错：破坏活动应该用〈起〉或〈次〉，〈只〉用于动物等，不能用于活动。正确说法是“这起破坏活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把破坏活动闹得很大。", "corrected_sentence": "这次破坏活动闹得很大。", "error_description": "量词用错：“把”用于有把手的东西，破坏活动应该用〈次〉或〈起〉。正确说法是“这次破坏活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
