INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟是身上有羽毛、会飞的小动物。", "primary_collocate": null, "pronunciation": "niǎo", "ipa": "niau˨˩˦", "syllable_count": 1, "sentences": [{"text": "树上有一只鸟在唱歌。", "target_word": "鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟有两只翅膀，身上长着羽毛。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，很多鸟飞回北方。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的树上有两只鸟。", "target_word": "鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟的羽毛是红色的。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子给鸟喂了一点米。", "target_word": "鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "笼子里的鸟飞不出去。", "target_word": "鸟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟在天上飞，鱼在水里游。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公园里看见一只白色的鸟。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟用树枝在树上做窝。", "target_word": "鸟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "小鸟", "label": "复合"}, {"form": "鸟儿", "label": "复合"}, {"form": "鳥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有羽毛、会飞的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b64ca331-cee2-4a4d-bcc5-b9b5a93b48c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88931, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟 niǎo（第三声）指身上有羽毛、会飞的小动物。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo 与 niǎo 声母不同（x/n），意思是小的。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo 与 niǎo 声母不同（q/n），意思是灵巧。"}, {"text": "表", "is_correct": false, "explanation": "biǎo 与 niǎo 声母不同（b/n），意思是手表。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo 与 niǎo 声母不同（m/n），意思是秒。"}], "explanations": {"鸟": "鸟 niǎo（第三声）指身上有羽毛、会飞的小动物。", "小": "xiǎo 与 niǎo 声母不同（x/n），意思是小的。", "巧": "qiǎo 与 niǎo 声母不同（q/n），意思是灵巧。", "表": "biǎo 与 niǎo 声母不同（b/n），意思是手表。", "秒": "miǎo 与 niǎo 声母不同（m/n），意思是秒。"}, "sentence_index": null, "correct_answer": "鸟"}, "level_3": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟会飞、会唱歌，“树上有一只鸟在唱歌”符合语境。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪不会在树上唱歌，与“唱歌”的动作不合。"}, {"text": "羊", "is_correct": false, "explanation": "体貌：羊的身体无法停在树上，与“树上”的位置不合。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会唱歌，与“在唱歌”不合。"}], "explanations": {"鸟": "鸟会飞、会唱歌，“树上有一只鸟在唱歌”符合语境。", "猪": "语义：猪不会在树上唱歌，与“唱歌”的动作不合。", "羊": "体貌：羊的身体无法停在树上，与“树上”的位置不合。", "狗": "语义：狗不会唱歌，与“在唱歌”不合。"}, "sentence_index": 0, "correct_answer": "鸟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在公园里看见一头鸟。", "explanation": "这里应该用〈只〉。“头”用于牛、猪等大牲畜，鸟要用“只”。"}, {"text": "这只鸟在院子里看门。", "explanation": "这里应该用〈狗〉。看门是狗的职能，鸟不能看门。"}, {"text": "这只鸟每天早上都哞哞叫。", "explanation": "这里应该用〈牛〉。“哞哞”是牛的叫声，鸟叫要说“叫”或“唱”，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88931, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟 niǎo（第三声）指身上有羽毛、会飞的小动物。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo 与 niǎo 声母不同（j/n），意思是角、角落。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo 与 niǎo 声母不同（j/n），意思是脚。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 没有 i 音，与 niǎo 不同，意思是大脑。"}], "explanations": {"鸟": "鸟 niǎo（第三声）指身上有羽毛、会飞的小动物。", "角": "jiǎo 与 niǎo 声母不同（j/n），意思是角、角落。", "脚": "jiǎo 与 niǎo 声母不同（j/n），意思是脚。", "脑": "nǎo 没有 i 音，与 niǎo 不同，意思是大脑。"}, "sentence_index": null, "correct_answer": "鸟"}, "level_3": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟会飞，“笼子里的鸟飞不出去”符合语境。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会飞，与“飞不出去”的动作不合。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会飞，与“飞不出去”不合。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“树”不能在笼子里飞，与“飞不出去”不搭配。"}], "explanations": {"鸟": "鸟会飞，“笼子里的鸟飞不出去”符合语境。", "鱼": "语义：鱼不会飞，与“飞不出去”的动作不合。", "猫": "语义：猫不会飞，与“飞不出去”不合。", "树": "搭配：“树”不能在笼子里飞，与“飞不出去”不搭配。"}, "sentence_index": 6, "correct_answer": "鸟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的鸟在公司上班。", "explanation": "这里应该用〈爸爸〉。鸟不能去公司上班，指人要用“爸爸”。"}, {"text": "鸟在教室里给学生上课。", "explanation": "这里应该用〈老师〉。给学生上课的是老师，鸟不能上课。"}, {"text": "鸟在路上开得很快。", "explanation": "这里应该用〈车〉。“开得很快”说的是车，鸟不能开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的那条鸟在树上叫个不停。", "corrected_sentence": "院子里的那只鸟在树上叫个不停。", "error_description": "“鸟”的量词应用“只”，不能用“条”（“条”用于细长的东西）。错误在“那条”，应为“那只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗台上停着一只的小鸟。", "corrected_sentence": "窗台上停着一只小鸟。", "error_description": "数量短语后多加了“的”。“一只”后直接接名词，不能在“一只”与“小鸟”之间加“的”，错误在“的”，应为“一只小鸟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
