INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88934, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示退一步设想，相当于“即使”。", "primary_collocate": null, "pronunciation": "nǎ pà", "ipa": "na˨˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "哪怕下雨，我也去。", "target_word": "哪怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哪怕只有一个人，他也要试试。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕很累，她也坚持跑步。", "target_word": "哪怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哪怕天气很冷，孩子们也在外面玩。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕你不同意，我也要说出来。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕再忙，他也会给妈妈打电话。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕只是一小步，也是进步。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕这次没考好，你也别放弃。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪怕路很远，我们也要走着去。", "target_word": "哪怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪怕要等很久，我也愿意等。", "target_word": "哪怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "哪怕：连词，退一步设想，常与“也／都”呼应，相当于即使", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪怕", "is_correct": true, "explanation": "哪怕：连词，表示退一步设想，与后面的“也”呼应。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，与“我也去”的退一步让步语气矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示结果，需要前文有原因，句首单用无法接“下雨”。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后承接，不表示退让的假设。"}], "explanations": {"哪怕": "哪怕：连词，表示退一步设想，与后面的“也”呼应。", "因为": "语义：“因为”引出原因，与“我也去”的退一步让步语气矛盾。", "所以": "搭配：“所以”表示结果，需要前文有原因，句首单用无法接“下雨”。", "然后": "语义：“然后”表示先后承接，不表示退让的假设。"}, "sentence_index": 0, "correct_answer": "哪怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哪怕他提醒了我，我才没有忘记。", "explanation": "这里应该用〈幸亏〉。哪怕表示退一步的设想，不表示因为有人提醒而避免失误的原因关系。"}, {"text": "哪怕天气好，我们就去。", "explanation": "这里应该用〈只要〉。哪怕表示让步，不表示“只要……就……”的充分条件。"}, {"text": "哪怕你来，我才高兴。", "explanation": "这里应该用〈只有〉。哪怕表示让步，不表示唯一条件；后面的“才”要求用“只有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪怕", "is_correct": true, "explanation": "哪怕：连词，表示退一步设想，此处为即使只是一小步，也算进步。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不能表示退一步的假设。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”引出并列的情况，与“只是一小步”组合后句子不成立。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语的因果连词，与这里口语化的让步语气不合。"}], "explanations": {"哪怕": "哪怕：连词，表示退一步设想，此处为即使只是一小步，也算进步。", "而且": "语义：“而且”表示递进或并列，不能表示退一步的假设。", "并且": "搭配：“并且”引出并列的情况，与“只是一小步”组合后句子不成立。", "故而": "语域：“故而”是书面语的因果连词，与这里口语化的让步语气不合。"}, "sentence_index": 6, "correct_answer": "哪怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哪怕孩子都知道这个道理。", "explanation": "这里应该用〈连〉。哪怕表示退一步的设想，不能用来强调“连……都”所表示的极端程度。"}, {"text": "他很生气，哪怕不愿意跟我说话。", "explanation": "这里应该用〈甚至〉。哪怕表示让步，不表示程度递进，这里语义不通。"}, {"text": "哪怕他来不来，我都要去。", "explanation": "这里应该用〈无论〉。哪怕表示一个假设的极端情况，不能用于“来不来”这种正反并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哪怕明天下大雨，我就会去。", "corrected_sentence": "哪怕明天下大雨，我也会去。", "error_description": "错误：“哪怕”后面应与“也”呼应，写成“就”不对。正确应为：“哪怕明天下大雨，我也会去。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哪怕这件事很难，他才愿意试。", "corrected_sentence": "哪怕这件事很难，他也愿意试。", "error_description": "错误：“哪怕”后面应与“也”呼应，写成“才”不对。正确应为：“哪怕这件事很难，他也愿意试。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "怀疑与确信相反：确信是心里很肯定，怀疑是心里不肯定，与“她确信自己的答案是对的”正好对立。"}, {"text": "承认", "is_correct": false, "explanation": "承认与确信不是反义关系：承认是认下某事，不表示心里对事情的把握程度。"}, {"text": "讨厌", "is_correct": false, "explanation": "讨厌与确信没有反义关系，它表示对人或事物的厌恶，不涉及对事实的把握。"}, {"text": "同意", "is_correct": false, "explanation": "同意与确信不构成反义关系：同意是赞成某个看法，确信是心里认定事实。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "怀疑与确信相反：确信是心里很肯定，怀疑是心里不肯定，与“她确信自己的答案是对的”正好对立。", "承认": "承认与确信不是反义关系：承认是认下某事，不表示心里对事情的把握程度。", "讨厌": "讨厌与确信没有反义关系，它表示对人或事物的厌恶，不涉及对事实的把握。", "同意": "同意与确信不构成反义关系：同意是赞成某个看法，确信是心里认定事实。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "怀疑与确信相反：确信是心里很肯定，怀疑是心里不肯定，与“妹妹确信那只猫是邻居家的”正好对立。"}, {"text": "赞同", "is_correct": false, "explanation": "赞同与确信没有反义关系，它表示同意某种看法，不涉及对事实的把握。"}, {"text": "吃惊", "is_correct": false, "explanation": "吃惊与确信不构成反义关系，它表示意外的情绪。"}, {"text": "生气", "is_correct": false, "explanation": "生气与确信没有反义关系，它表示发怒的情绪。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "怀疑与确信相反：确信是心里很肯定，怀疑是心里不肯定，与“妹妹确信那只猫是邻居家的”正好对立。", "赞同": "赞同与确信没有反义关系，它表示同意某种看法，不涉及对事实的把握。", "吃惊": "吃惊与确信不构成反义关系，它表示意外的情绪。", "生气": "生气与确信没有反义关系，它表示发怒的情绪。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "确信是心里很肯定这件事是真的。", "primary_collocate": null, "pronunciation": "què xìn", "ipa": "tɕʰɥe˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我确信自己把钥匙放在了桌子上。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他确信这个消息是真的。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了照片，我确信那就是我的老同学。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她确信自己的答案是对的。", "target_word": "确信", "complexity_tier": "T3", "furigana": "tā què xìn zì jǐ de dá àn shì duì de", "sentence_source": "generated"}, {"text": "我确信门已经锁好了。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师确信这次考试他能通过。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我确信昨天在车站见过他。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生确信这个办法有用。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你确信他今天会来吗？", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹确信那只猫是邻居家的。", "target_word": "确信", "complexity_tier": "T3", "furigana": "mèi mei què xìn nà zhī māo shì lín jū jiā de", "sentence_source": "generated"}], "morphological_forms": [{"form": "确信了", "label": "体标"}], "register": "中性", "sense_fingerprint": "心里肯定某事是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确信", "is_correct": true, "explanation": "确信表示心里很肯定，与“自己把钥匙放在了桌子上”这一已经发生的判断相符。"}, {"text": "打算", "is_correct": false, "explanation": "体貌：“打算”指对将来的安排，不能用于已经完成的“放在了”。"}, {"text": "邀请", "is_correct": false, "explanation": "配价：“邀请”要说明邀请谁做什么，“我邀请自己把钥匙放在了桌子上”不成立。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”要说明通知谁、通知什么，“通知自己”后面接事情不成立。"}], "explanations": {"确信": "确信表示心里很肯定，与“自己把钥匙放在了桌子上”这一已经发生的判断相符。", "打算": "体貌：“打算”指对将来的安排，不能用于已经完成的“放在了”。", "邀请": "配价：“邀请”要说明邀请谁做什么，“我邀请自己把钥匙放在了桌子上”不成立。", "通知": "配价：“通知”要说明通知谁、通知什么，“通知自己”后面接事情不成立。"}, "sentence_index": 0, "correct_answer": "确信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们确信了开会的时间。", "explanation": "这里应该用〈确定〉。确定指定下时间或方案；确信只表示心里认定某件事是真的，不能用来安排时间。"}, {"text": "我确信你。", "explanation": "这里应该用〈相信〉。确信后面要接一件事，如“确信你说的是真的”，不能直接带人；相信可以直接带人。"}, {"text": "警察确信了他的身份。", "explanation": "这里应该用〈确认〉。确认指核实身份、信息；确信指心里认定某件事是真的，不能直接带“身份”这类对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确信", "is_correct": true, "explanation": "确信表示心里很肯定，与“昨天在车站见过他”这一已经发生的判断相符。"}, {"text": "计划", "is_correct": false, "explanation": "体貌：“计划”指将来的安排，与“昨天”已经发生的见面不符。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”是允诺将来要做的事，不能用于已经发生的见面。"}, {"text": "建议", "is_correct": false, "explanation": "配价：“建议”要说明建议对方做什么，“我建议……见过他”缺少对象，不成立。"}], "explanations": {"确信": "确信表示心里很肯定，与“昨天在车站见过他”这一已经发生的判断相符。", "计划": "体貌：“计划”指将来的安排，与“昨天”已经发生的见面不符。", "答应": "语义：“答应”是允诺将来要做的事，不能用于已经发生的见面。", "建议": "配价：“建议”要说明建议对方做什么，“我建议……见过他”缺少对象，不成立。"}, "sentence_index": 6, "correct_answer": "确信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他确信佛教，从不动摇。", "explanation": "这里应该用〈信仰〉。确信后面要接一件事或一个判断，不能直接带“佛教”这样的宗教或信念。"}, {"text": "老师确信了他的努力。", "explanation": "这里应该用〈肯定〉。肯定可以用于表扬、认可某人的努力；确信表示心里认定事实，不能直接带“努力”作宾语。"}, {"text": "他确信了那只猫的年龄。", "explanation": "这里应该用〈估计〉。估计指根据情况推测数量或年龄；确信指心里认定某件事是真的，不能用来推测年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我确信得他会来。", "corrected_sentence": "我确信他会来。", "error_description": "“确信”后面不能直接接“得”；应说“我确信他会来”，多出的“得”要去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不确信得这件事是真的。", "corrected_sentence": "我不确信这件事是真的。", "error_description": "“确信”后面不能接“得”，“得”只用在动词后带补语时；应说“我不确信这件事是真的”，多出的“得”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
