INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88936, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "确实地相信。", "primary_collocate": null, "pronunciation": "què xìn", "ipa": "tɕʰɥe˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "大家都确信他是个诚实的人。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他确信只要努力，就能成功。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我确信这件事不是他做的。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她确信自己没有听错。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理确信这个计划行得通。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们确信这次比赛会赢。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就确信有一天会当医生。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我确信你说的是实话。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷确信这条路能走到山下。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太确信地址对不对。", "target_word": "确信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "确信了", "label": "体标"}], "register": "中性", "sense_fingerprint": "确实地相信某事是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确信", "is_correct": true, "explanation": "确信表示确实地相信，与“大家都……他是个诚实的人”这一判断相符。"}, {"text": "教", "is_correct": false, "explanation": "语义：“教”指传授知识或技能，不能用来判断某人的品性。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”要说明劝谁做什么，“劝他是个……的人”不成立。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”指迫使某人做事，与“是个诚实的人”的判断不相容。"}], "explanations": {"确信": "确信表示确实地相信，与“大家都……他是个诚实的人”这一判断相符。", "教": "语义：“教”指传授知识或技能，不能用来判断某人的品性。", "劝": "配价：“劝”要说明劝谁做什么，“劝他是个……的人”不成立。", "逼": "语义：“逼”指迫使某人做事，与“是个诚实的人”的判断不相容。"}, "sentence_index": 0, "correct_answer": "确信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们确信了出发的时间。", "explanation": "这里应该用〈确定〉。确定指定下时间或方案；确信指确实地相信某件事，不能用来安排出发时间。"}, {"text": "他确信了订单的金额。", "explanation": "这里应该用〈确认〉。确认指核实订单、金额等信息；确信指心里相信某件事，不能用于核对金额。"}, {"text": "双方确信了合作的方案。", "explanation": "这里应该用〈商定〉。商定指双方协商决定；确信指心里相信，不能用于双方协商定下的方案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确信", "is_correct": true, "explanation": "确信表示确实地相信，与“有一天会当医生”的判断相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起已经发生的事，与“有一天会”的将来不符。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”指对已经做过的事感到遗憾，不能用于将来的理想。"}, {"text": "请求", "is_correct": false, "explanation": "配价：“请求”要说明请求谁做什么，“请求他有一天会当医生”不成立。"}], "explanations": {"确信": "确信表示确实地相信，与“有一天会当医生”的判断相符。", "回忆": "语义：“回忆”指想起已经发生的事，与“有一天会”的将来不符。", "后悔": "语义：“后悔”指对已经做过的事感到遗憾，不能用于将来的理想。", "请求": "配价：“请求”要说明请求谁做什么，“请求他有一天会当医生”不成立。"}, "sentence_index": 6, "correct_answer": "确信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们确信了这份名单。", "explanation": "这里应该用〈核实〉。核实指查证名单是否属实；确信指心里相信某件事，不能用来说查对名单。"}, {"text": "他确信了这套方案。", "explanation": "这里应该用〈选定〉。选定指挑选并决定方案；确信指心里相信某件事是真的，不能用于挑选方案。"}, {"text": "他确信了老师的问题。", "explanation": "这里应该用〈回答〉。回答可以带“问题”作宾语；确信是心里认定某事，不能直接带“问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我确信地他不会来。", "corrected_sentence": "我确信他不会来。", "error_description": "“确信”后面直接接分句，“地”不能加在主语前面；应说“我确信他不会来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不确信得这次比赛会赢。", "corrected_sentence": "我不确信这次比赛会赢。", "error_description": "“确信”后面不能接“得”，“得”只用在动词后带补语时；应说“我不确信这次比赛会赢”，多出的“得”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
