INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分布是东西分散在很多地方。", "primary_collocate": null, "pronunciation": "fēn bù", "ipa": "fən˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的公园分布在东西南北。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市在城里分布得很广。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的雪山里分布着很多小村子。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的店分布在全国各地。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树主要分布在南方。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林里的野花分布在山坡的各处。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的书店分布得很均匀。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站分布在城市的各个地方。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小岛分布在海的中间。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫只分布在中国的一些山区。", "target_word": "分布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分布着", "label": "体标"}, {"form": "分布了", "label": "体标"}, {"form": "分布图", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西分散在很多地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 野花 (Zipf 3.05), 山坡 (Zipf 3.79), 各处 (Zipf 3.91)']::text[], '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "分布：事物散布在各处，公园分散在东、西、南、北各个方向，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：公园是场所，不能“唱”，“唱在东西南北”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的主体须是能进食的人或动物，公园不能吃。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要书写的内容作宾语，“公园”不能充当这个成分。"}], "explanations": {"分布": "分布：事物散布在各处，公园分散在东、西、南、北各个方向，符合语境。", "唱": "语义：公园是场所，不能“唱”，“唱在东西南北”不成立。", "吃": "语义：“吃”的主体须是能进食的人或动物，公园不能吃。", "写": "配价：“写”需要书写的内容作宾语，“公园”不能充当这个成分。"}, "sentence_index": 0, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他分布在北京的一家大公司里工作。", "explanation": "这里应该用〈任职〉。分布指许多事物散布在各处，不能用来说一个人在某处任职。"}, {"text": "老师把作业分布给每个学生。", "explanation": "这里应该用〈分配〉。分布指散布在各处，不表示把东西分给别人。"}, {"text": "这个会议分布在下午三点。", "explanation": "这里应该用〈安排〉。分布指散布于空间，不用于说时间上的安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "分布：事物散布在各处，书店分散在校园里，“分布得很均匀”符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：书店不能唱，“唱得很均匀”不合理。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“得很均匀”多用于分布、排列等，不说“跳得很均匀”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：书店不会哭，与“很均匀”的描述不合。"}], "explanations": {"分布": "分布：事物散布在各处，书店分散在校园里，“分布得很均匀”符合语境。", "唱": "语义：书店不能唱，“唱得很均匀”不合理。", "跳": "搭配：“得很均匀”多用于分布、排列等，不说“跳得很均匀”。", "哭": "语义：书店不会哭，与“很均匀”的描述不合。"}, "sentence_index": 6, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这群学生分布在教室的一角学习。", "explanation": "这里应该用〈集中〉。分布强调分散，而学生在一角学习需要聚在一起。"}, {"text": "他们俩上个月分布了。", "explanation": "这里应该用〈分手〉。分布指东西散布在各处，不表示两人之间断绝关系。"}, {"text": "这种病毒分布了很多人。", "explanation": "这里应该用〈感染〉。分布不能表示使人患病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些庙宇分布着在山谷的各处。", "corrected_sentence": "这些庙宇分布在山谷的各处。", "error_description": "“分布”后不应再加“着”，否则与引出地点的“在”重复。正确形式为“分布在山谷的各处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几家书店分布了很广。", "corrected_sentence": "这几家书店分布得很广。", "error_description": "程度补语应由“得”引出，“了”不能用于此处。错误形式把“得”写成“了”，正确形式为“分布得很广”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
