INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交给是把具体的东西递到别人手里，让他拿着。", "primary_collocate": null, "pronunciation": "jiāo gěi", "ipa": "tɕjɑʊ˥ kei˨˩", "syllable_count": 2, "sentences": [{"text": "请把这本书交给老师。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙交给了妈妈。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经把信交给她了。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把这个包交给门口的人。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把票交给了服务员。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把作业交给老师就走了。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把钱交给前面的阿姨。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把礼物交给了我。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机交给朋友拿着。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把花交给了女朋友。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交给了", "label": "完成体"}, {"form": "交给过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把具体的东西递到别人手里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问", "is_correct": false, "explanation": "语义：「问」是询问，书不能被用来询问老师，与句中把书递给老师的意思不符。"}, {"text": "交给", "is_correct": true, "explanation": "正确：「交给」是把书递到老师手中，与句意相符。"}, {"text": "骂", "is_correct": false, "explanation": "语义：「骂」是责备人，与请人把书递给老师的语境不符。"}, {"text": "找", "is_correct": false, "explanation": "搭配：「找」指去寻找人或东西，不能说“把这本书找老师”。"}], "explanations": {"问": "语义：「问」是询问，书不能被用来询问老师，与句中把书递给老师的意思不符。", "交给": "正确：「交给」是把书递到老师手中，与句意相符。", "骂": "语义：「骂」是责备人，与请人把书递给老师的语境不符。", "找": "搭配：「找」指去寻找人或东西，不能说“把这本书找老师”。"}, "sentence_index": 0, "correct_answer": "交给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把包裹交给了那扇门。", "explanation": "这里应该用〈放在〉。门不能接过东西，交给要递到能接手的人手中，应说把包裹放在门边。"}, {"text": "我把包裹交给了路边的树。", "explanation": "这里应该用〈放在〉。交给要托付给能接过东西或负责的人，树不能接手，应说把包裹放在树下。"}, {"text": "他把垃圾交给了垃圾桶。", "explanation": "这里应该用〈放进〉。交给的对象要能接过东西，垃圾桶只是容器，应说放进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追", "is_correct": false, "explanation": "语义：「追」是追赶，与把钱递给前面的阿姨的意思不符。"}, {"text": "交给", "is_correct": true, "explanation": "正确：「交给」是把钱递到阿姨手中，与句意相符。"}, {"text": "骗", "is_correct": false, "explanation": "语义：「骗」是欺骗，与句中礼貌的请求不符。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：「叫」指呼喊某人，不能说“把钱叫”来表示递交钱。"}], "explanations": {"追": "语义：「追」是追赶，与把钱递给前面的阿姨的意思不符。", "交给": "正确：「交给」是把钱递到阿姨手中，与句意相符。", "骗": "语义：「骗」是欺骗，与句中礼貌的请求不符。", "叫": "搭配：「叫」指呼喊某人，不能说“把钱叫”来表示递交钱。"}, "sentence_index": 6, "correct_answer": "交给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙交给了那盆花。", "explanation": "这里应该用〈藏在〉。交给要托付给能接过东西的人，花盆不能接手，藏钥匙应说藏在花盆里。"}, {"text": "他把水交给了杯子。", "explanation": "这里应该用〈倒进〉。交给的对象要能接过东西，杯子只是容器，倒水应说倒进。"}, {"text": "他把画交给了墙。", "explanation": "这里应该用〈挂在〉。墙不能接过东西，挂画应说挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这份报告交给着主任。", "corrected_sentence": "我把这份报告交给了主任。", "error_description": "体标错误：“交给”表示已经完成的交付，应用“了”；“着”表示持续状态，“交给着主任”不符合句意，应说“交给了主任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把手表交给了女朋友。", "corrected_sentence": "他没把手表交给女朋友。", "error_description": "体标错误：否定句中“没”后面的“交给”不能再加“了”，应说“他没把手表交给女朋友”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
