INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交给是把任务、事情或人托付给别人，让其负责。", "primary_collocate": null, "pronunciation": "jiāo gěi", "ipa": "tɕjɑʊ˥ kei˨˩", "syllable_count": 2, "sentences": [{"text": "这件事就交给我吧。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把工作交给了小王。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把班里的事交给他管。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把孩子交给奶奶照顾。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把新的任务交给了我们。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不要交给别人，你自己想想。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把店交给儿子管理。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把家里的事都交给妻子了。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日会交给我来准备吧。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把这个项目交给了她。", "target_word": "交给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交给了", "label": "完成体"}, {"form": "交给过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把任务、事情、人托付给别人负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍", "is_correct": false, "explanation": "搭配：「拍」多指拍照或拍打，不能说“这件事拍给我”。"}, {"text": "吓", "is_correct": false, "explanation": "语义：「吓」是使人害怕，与把事情托付给我的语境不符。"}, {"text": "交给", "is_correct": true, "explanation": "正确：「交给」是把事情托付给我负责，与句意相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：「砍」是用刀斩断，与托付事情无关。"}], "explanations": {"拍": "搭配：「拍」多指拍照或拍打，不能说“这件事拍给我”。", "吓": "语义：「吓」是使人害怕，与把事情托付给我的语境不符。", "交给": "正确：「交给」是把事情托付给我负责，与句意相符。", "砍": "语义：「砍」是用刀斩断，与托付事情无关。"}, "sentence_index": 0, "correct_answer": "交给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把孩子交给了一把椅子。", "explanation": "这里应该用〈坐在〉。交给要托付给能负责的人，椅子不能照看孩子，应说让孩子坐在椅子上。"}, {"text": "经理把这个任务交给了窗户。", "explanation": "这里应该用〈贴在〉。窗户不能负责任务，交给要托付给能负责的人，任务单只能贴在窗户上。"}, {"text": "我把猫交给了一个纸箱。", "explanation": "这里应该用〈装进〉。交给要托付给能负责的人，纸箱只是容器，应说把猫装进纸箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳给", "is_correct": false, "explanation": "语义：「跳给」是对人跳舞，不能带“店”，与把店托付给儿子管理的意思不符。"}, {"text": "讲给", "is_correct": false, "explanation": "搭配：「讲给」的对象多是话或故事，不能与“店”搭配。"}, {"text": "交给", "is_correct": true, "explanation": "正确：「交给」是把店托付给儿子管理，与句意相符。"}, {"text": "唱给", "is_correct": false, "explanation": "语义：「唱给」是对人唱歌，与把店交给儿子的意思不符。"}], "explanations": {"跳给": "语义：「跳给」是对人跳舞，不能带“店”，与把店托付给儿子管理的意思不符。", "讲给": "搭配：「讲给」的对象多是话或故事，不能与“店”搭配。", "交给": "正确：「交给」是把店托付给儿子管理，与句意相符。", "唱给": "语义：「唱给」是对人唱歌，与把店交给儿子的意思不符。"}, "sentence_index": 6, "correct_answer": "交给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份合同交给了那扇门。", "explanation": "这里应该用〈贴在〉。门不能接管事务，交给要托付给能负责的人，应说把合同贴在门上。"}, {"text": "老板把这个项目交给了电脑桌。", "explanation": "这里应该用〈放在〉。交给要托付给能负责的人，桌子不能负责项目，项目文件只能放在桌上。"}, {"text": "她把照顾小狗的事交给了狗窝。", "explanation": "这里应该用〈放进〉。狗窝不能负责照顾小狗，交给要托付给人，小狗只能放进狗窝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把孩子交给着奶奶照顾。", "corrected_sentence": "妈妈把孩子交给了奶奶照顾。", "error_description": "体标错误：表示完成的交付要用“了”，“着”表示持续状态，“交给着奶奶照顾”不符合句意，应说“交给了奶奶照顾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔生意我没交给了他做。", "corrected_sentence": "这笔生意我没交给他做。", "error_description": "体标错误：“没”否定的动作后面不能再加“了”，“交给”后直接接对象，应说“没交给他做”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
