INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88941, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "唯有是只有这一个。", "primary_collocate": null, "pronunciation": "wéi yǒu", "ipa": "wei˧˥ jou˨˩", "syllable_count": 2, "sentences": [{"text": "大家都走了，唯有他还在。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有努力，才能成功。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "唯有时间能证明一切。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外很安静，唯有风声。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他什么都不缺，唯有时间不够用。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有坚持，才能学好汉语。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友们都不同意，唯有小王支持我。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市很大，唯有这家书店让我难忘。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有亲自去看，你才会明白。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天的山上，唯有松树还是绿的。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "惟有", "label": "异形词"}], "register": "书面", "sense_fingerprint": "唯有：只有这一个，表示范围里仅此一项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有这一个，表示范围里仅此一项。"}, {"text": "没有", "is_correct": false, "explanation": "méiyǒu 与 wéiyǒu 声母不同（m 与 w），声调相同，意思是“没有”。"}, {"text": "未有", "is_correct": false, "explanation": "wèiyǒu：wèi（第四声）与 wéi（第二声）声调不同，意思是“尚未有”。"}, {"text": "为由", "is_correct": false, "explanation": "wéiyóu：yóu（第二声）与 yǒu（第三声）声调不同，意思是“理由、借口”。"}], "explanations": {"唯有": "唯有：副词，只有这一个，表示范围里仅此一项。", "没有": "méiyǒu 与 wéiyǒu 声母不同（m 与 w），声调相同，意思是“没有”。", "未有": "wèiyǒu：wèi（第四声）与 wéi（第二声）声调不同，意思是“尚未有”。", "为由": "wéiyóu：yóu（第二声）与 yǒu（第三声）声调不同，意思是“理由、借口”。"}, "sentence_index": null, "correct_answer": "唯有"}, "level_3": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有这一个，把他从其他人中单独挑出来。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样，与“大家都走了”矛盾，句子不通。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原先的情况，不表示从众人中单独挑出一个，与前文“大家都走了”的排他对比不符。"}, {"text": "难怪", "is_correct": false, "explanation": "搭配：“难怪”表示恍然明白，需要前文有现象或原因，这里单用不通。"}], "explanations": {"唯有": "唯有：副词，只有这一个，把他从其他人中单独挑出来。", "也": "语义：“也”表示同样，与“大家都走了”矛盾，句子不通。", "本来": "语义：“本来”表示原先的情况，不表示从众人中单独挑出一个，与前文“大家都走了”的排他对比不符。", "难怪": "搭配：“难怪”表示恍然明白，需要前文有现象或原因，这里单用不通。"}, "sentence_index": 0, "correct_answer": "唯有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "唯有努力，就能成功。", "explanation": "这里应该用〈只要〉，并与“就”呼应。唯有表示排他，要与“才”呼应。"}, {"text": "我唯有想问一个问题。", "explanation": "这里应该用〈只是〉。唯有表示排他，不表示“仅仅、不过”。"}, {"text": "他不但聪明，唯有勤奋。", "explanation": "这里应该用〈而且〉。唯有表示排除其他，与“不但……”的递进语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有这一个，把小王从不同意的人中单独挑出来。"}, {"text": "竟", "is_correct": false, "explanation": "搭配：“竟”表示意外，后面要接动词或形容词，不能直接接人名主语。"}, {"text": "都", "is_correct": false, "explanation": "语法：“都”是副词，不能放在主语“小王”前面；而且“都”表示全部，与只挑出一个人的意思相反。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示推测，与“都不同意”的确定语气不合，也不表示唯一。"}], "explanations": {"唯有": "唯有：副词，只有这一个，把小王从不同意的人中单独挑出来。", "竟": "搭配：“竟”表示意外，后面要接动词或形容词，不能直接接人名主语。", "都": "语法：“都”是副词，不能放在主语“小王”前面；而且“都”表示全部，与只挑出一个人的意思相反。", "大概": "语义：“大概”表示推测，与“都不同意”的确定语气不合，也不表示唯一。"}, "sentence_index": 6, "correct_answer": "唯有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唯有老师都不知道这件事。", "explanation": "这里应该用〈连〉。唯有表示排他，与表示全部的“都”矛盾；表示极端情况应说“连……都”。"}, {"text": "唯有他很累，我也要去。", "explanation": "这里应该用〈即使〉。唯有表示排他，不表示让步；“我也要去”的让步语气与“唯有”不合。"}, {"text": "我唯有喜欢喝茶。", "explanation": "这里应该用〈只〉。唯有用来从多项中挑出一项作对比，单纯限定自己的喜好应说“我只喜欢喝茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唯有坚持下去，就能看到结果。", "corrected_sentence": "唯有坚持下去，才能看到结果。", "error_description": "错误：“唯有”要与“才”呼应，写成“就”不对。正确应为：“唯有坚持下去，才能看到结果。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇很安静，唯有河水也在流。", "corrected_sentence": "这个小镇很安静，唯有河水在流。", "error_description": "错误：“唯有”表示只有河水一项，后面不能再用“也”表示同样，写成“河水也”矛盾。正确应为：“这个小镇很安静，唯有河水在流。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
