INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88942, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只有；惟独。", "primary_collocate": null, "pronunciation": "wéi yǒu", "ipa": "wei˧˥ jou˨˩", "syllable_count": 2, "sentences": [{"text": "大家都去了，唯有我没去。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "所有人都笑了，唯有老师没笑。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有读书，才能改变命运。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他什么都吃，唯有辣的不吃。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有真诚，才能换来朋友。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里很静，唯有月亮陪着我。", "target_word": "唯有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都懂，唯有他还不明白。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "唯有团结，我们才能赢。", "target_word": "唯有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里很空，唯有一张旧桌子。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些衣服我都喜欢，唯有这件不喜欢。", "target_word": "唯有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "惟有", "label": "异形词"}], "register": "书面", "sense_fingerprint": "唯有：只有、惟独，把某一项从其他项中单独挑出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有、惟独，把某一项从其他项中单独挑出来。"}, {"text": "没有", "is_correct": false, "explanation": "méiyǒu 与 wéiyǒu 声母不同（m 与 w），声调相同，意思是“没有”。"}, {"text": "未有", "is_correct": false, "explanation": "wèiyǒu：wèi（第四声）与 wéi（第二声）声调不同，意思是“尚未有”。"}, {"text": "为由", "is_correct": false, "explanation": "wéiyóu：yóu（第二声）与 yǒu（第三声）声调不同，意思是“理由、借口”。"}], "explanations": {"唯有": "唯有：副词，只有、惟独，把某一项从其他项中单独挑出来。", "没有": "méiyǒu 与 wéiyǒu 声母不同（m 与 w），声调相同，意思是“没有”。", "未有": "wèiyǒu：wèi（第四声）与 wéi（第二声）声调不同，意思是“尚未有”。", "为由": "wéiyóu：yóu（第二声）与 yǒu（第三声）声调不同，意思是“理由、借口”。"}, "sentence_index": null, "correct_answer": "唯有"}, "level_3": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有、惟独，把“我”从去了的大家中单独挑出来。"}, {"text": "也", "is_correct": false, "explanation": "语法：“也”是副词，不能放在主语“我”前面；而且“也”表示同样，与单独挑出一人的意思不合。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原先的情况，不表示从众人中单独挑出一个，与“大家都去了”的对比不符。"}, {"text": "难怪", "is_correct": false, "explanation": "搭配：“难怪”表示恍然明白，需要前文有现象或原因，这里单用不通。"}], "explanations": {"唯有": "唯有：副词，只有、惟独，把“我”从去了的大家中单独挑出来。", "也": "语法：“也”是副词，不能放在主语“我”前面；而且“也”表示同样，与单独挑出一人的意思不合。", "本来": "语义：“本来”表示原先的情况，不表示从众人中单独挑出一个，与“大家都去了”的对比不符。", "难怪": "搭配：“难怪”表示恍然明白，需要前文有现象或原因，这里单用不通。"}, "sentence_index": 0, "correct_answer": "唯有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "唯有老师都不知道这件事。", "explanation": "这里应该用〈连〉。唯有表示排他，与表示全部的“都”矛盾；表示极端情况应说“连……都”。"}, {"text": "唯有他很累，我也要去。", "explanation": "这里应该用〈即使〉。唯有表示排他，不表示让步；“我也要去”的让步语气与“唯有”不合。"}, {"text": "我唯有喜欢喝茶。", "explanation": "这里应该用〈只〉。唯有用来从多项中挑出一项作对比，单纯限定自己的喜好应说“我只喜欢喝茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唯有", "is_correct": true, "explanation": "唯有：副词，只有、惟独，把他从懂的人中单独挑出来说明不明白。"}, {"text": "竟", "is_correct": false, "explanation": "搭配：“竟”表示意外，后面要接动词或形容词，不能直接接人名主语。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，与“大家都懂”的语境不协调。"}, {"text": "都", "is_correct": false, "explanation": "语法：“都”是副词，不能放在主语“他”前面；而且“都”表示全部，与单独挑出一人的意思相反。"}], "explanations": {"唯有": "唯有：副词，只有、惟独，把他从懂的人中单独挑出来说明不明白。", "竟": "搭配：“竟”表示意外，后面要接动词或形容词，不能直接接人名主语。", "果然": "语义：“果然”表示与预料相符，与“大家都懂”的语境不协调。", "都": "语法：“都”是副词，不能放在主语“他”前面；而且“都”表示全部，与单独挑出一人的意思相反。"}, "sentence_index": 6, "correct_answer": "唯有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唯有努力，就能成功。", "explanation": "这里应该用〈只要〉，并与“就”呼应。唯有表示排他，要与“才”呼应。"}, {"text": "我唯有想问一个问题。", "explanation": "这里应该用〈只是〉。唯有表示排他，不表示“仅仅、不过”。"}, {"text": "他唯有三岁。", "explanation": "这里应该用〈只有〉。唯有表示从多项中单独挑出一项，不表示数量少；说年龄小应说“他只有三岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唯有努力，就能取得好成绩。", "corrected_sentence": "唯有努力，才能取得好成绩。", "error_description": "错误：“唯有”要与“才”呼应，写成“就”不对。正确应为：“唯有努力，才能取得好成绩。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都累了，唯有他也还在工作。", "corrected_sentence": "大家都累了，唯有他还在工作。", "error_description": "错误：“唯有”表示只有他一个，后面不能再用“也”表示同样，写成“他也”矛盾。正确应为：“大家都累了，唯有他还在工作。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
