INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "社会团体是很多人为了同一件事聚在一起的组织。", "primary_collocate": null, "pronunciation": "shè huì tuán tǐ", "ipa": "ʂɤ˥˩ xweɪ˥˩ tʰwan˧˥ tʰi˨˩", "syllable_count": 4, "sentences": [{"text": "这个社会团体有一百多个成员。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们街道有一个爱护小动物的社会团体。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个社会团体里做志愿者。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会团体常常开会讨论大家的想法。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社会团体每个周末都有活动。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们办了一个社会团体，一起唱歌。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想加入一个帮助孩子的社会团体。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社会团体的人都喜欢读书。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社会团体的成员常常一起去公园打扫卫生。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个社会团体在哪儿吗？", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个社会团体", "label": "量词"}, {"form": "社會團體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人因同一件事聚在一起的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会团体", "is_correct": true, "explanation": "正确：社会团体是很多人组成的组织，可以有成员。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是位置信息，没有成员，与“有一百多个成员”不符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能有成员。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能与“有一百多个成员”搭配。"}], "explanations": {"社会团体": "正确：社会团体是很多人组成的组织，可以有成员。", "地址": "语义：地址是位置信息，没有成员，与“有一百多个成员”不符。", "蔬菜": "语义：蔬菜是食物，不能有成员。", "天气": "搭配：“天气”不能与“有一百多个成员”搭配。"}, "sentence_index": 0, "correct_answer": "社会团体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子是一个社会团体，有三个卧室。", "explanation": "社会团体指很多人为同一件事聚在一起的组织，房子不是组织，这句与此义不符。"}, {"text": "这个社会团体重得很，搬不动。", "explanation": "社会团体指组织，不是有重量的实物，这句把它当作可以搬动的东西，与此义不符。"}, {"text": "我是一个社会团体，喜欢唱歌。", "explanation": "社会团体指很多人为同一件事组成的组织，不能指一个人。这句把它当成一个人，与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会团体", "is_correct": true, "explanation": "正确：社会团体是民间组织，可以被人加入。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物件，不是可以加入的组织。"}, {"text": "植物", "is_correct": false, "explanation": "配价：“加入”的对象应是组织或团体，植物不能作宾语。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是作品，不能被人加入。"}], "explanations": {"社会团体": "正确：社会团体是民间组织，可以被人加入。", "钥匙": "语义：钥匙是物件，不是可以加入的组织。", "植物": "配价：“加入”的对象应是组织或团体，植物不能作宾语。", "电影": "语义：电影是作品，不能被人加入。"}, "sentence_index": 6, "correct_answer": "社会团体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社会团体只有我一个人，我每天自己工作。", "explanation": "社会团体指很多人为同一件事聚在一起的组织，只有一个人不构成社会团体，这句与此义不符。"}, {"text": "这个社会团体是一棵大树，每年都开花。", "explanation": "社会团体指组织，不是植物，这句把它当作树木，与此义不符。"}, {"text": "我每天坐社会团体去上班。", "explanation": "社会团体指组织，不是交通工具，这句把它当作可以乘坐的车辆，与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区有一只帮助老人的社会团体。", "corrected_sentence": "我们小区有一个帮助老人的社会团体。", "error_description": "量词错误：社会团体是组织，应用量词“个”；“只”用于动物等，不能修饰社会团体。正确说法：一个社会团体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有一件学习外语的社会团体。", "corrected_sentence": "我们学校有一个学习外语的社会团体。", "error_description": "量词错误：“件”用于物品或事情，不能修饰社会团体；社会团体应用“个”。正确说法：一个社会团体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
