INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由公民自愿组成、为实现共同目的而开展活动的非营利性组织。", "primary_collocate": null, "pronunciation": "shè huì tuán tǐ", "ipa": "ʂɤ˥˩ xweɪ˥˩ tʰwan˧˥ tʰi˨˩", "syllable_count": 4, "sentences": [{"text": "这个社会团体不以赚钱为目的。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民可以自愿加入社会团体。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会团体要在政府部门登记。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社会团体每年为山区学校捐书。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个环保社会团体的负责人。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会团体的经费主要来自会员和捐款。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个社会团体组织了一次义务献血。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一些社会团体为老人提供免费帮助。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在社会团体工作了三年。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会团体的活动都是公开的。", "target_word": "社会团体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个社会团体", "label": "量词"}, {"form": "社會團體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公民自愿组成的非营利性组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会团体", "is_correct": true, "explanation": "正确：社会团体是非营利组织，本句说它不以赚钱为目的，符合定义。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司以盈利为目的，与“不以赚钱为目的”矛盾。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是物件，不是组织，不能说不以赚钱为目的。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物件，不是组织，与“不以赚钱为目的”无关。"}], "explanations": {"社会团体": "正确：社会团体是非营利组织，本句说它不以赚钱为目的，符合定义。", "公司": "语义：公司以盈利为目的，与“不以赚钱为目的”矛盾。", "电灯": "语义：电灯是物件，不是组织，不能说不以赚钱为目的。", "钥匙": "语义：钥匙是物件，不是组织，与“不以赚钱为目的”无关。"}, "sentence_index": 0, "correct_answer": "社会团体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用这个社会团体写作业。", "explanation": "社会团体指组织，不是可以用来写字的工具，这句把它当作书写工具，与此义不符。"}, {"text": "这个社会团体的股东每年分红很多。", "explanation": "社会团体是非营利组织，不向股东分配利润；这句说它有股东分红，与此义不符。"}, {"text": "这个社会团体是一家公司，每年为山区学校捐书。", "explanation": "社会团体是非营利的民间组织，这句把它说成营利性的单位，与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会团体", "is_correct": true, "explanation": "正确：社会团体是人组成的组织，可以组织活动。"}, {"text": "蔬菜", "is_correct": false, "explanation": "配价：“组织”需要能组织活动的主体，蔬菜不能作主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能组织活动，与“组织了一次义务献血”矛盾。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物件，不能组织献血活动。"}], "explanations": {"社会团体": "正确：社会团体是人组成的组织，可以组织活动。", "蔬菜": "配价：“组织”需要能组织活动的主体，蔬菜不能作主语。", "天气": "语义：天气不能组织活动，与“组织了一次义务献血”矛盾。", "钥匙": "语义：钥匙是物件，不能组织献血活动。"}, "sentence_index": 6, "correct_answer": "社会团体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的社会团体是我的儿子，今年十岁。", "explanation": "社会团体是组织，不能是人，这句把它说成儿子，与此义不符。"}, {"text": "昨天社会团体下了一场大雨。", "explanation": "社会团体指组织，不能下雨，这句把它当作天气的主语，与此义不符。"}, {"text": "我每天晚上都住在社会团体里。", "explanation": "社会团体是组织，不是住所或建筑，不能说住在里面，与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区有一台社会团体，成员都是老人。", "corrected_sentence": "我们小区有一个社会团体，成员都是老人。", "error_description": "量词错误：“台”用于机器等，社会团体是组织，应用“个”。正确说法：一个社会团体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个成立于二〇一〇年社会团体，每年都捐书。", "corrected_sentence": "我们这个成立于二〇一〇年的社会团体，每年都捐书。", "error_description": "修饰语结构错误：“成立于二〇一〇年”修饰“社会团体”时，中间要加“的”。正确说法：成立于二〇一〇年的社会团体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小型", "is_correct": true, "explanation": "小型与“大型”是反义词，指规模或体积小。"}, {"text": "安静", "is_correct": false, "explanation": "安静说声音或环境，与“大型”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮说光线或颜色，与“大型”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软说质地，与“大型”没有反义关系。"}], "correct_answer": "小型", "explanations": {"小型": "小型与“大型”是反义词，指规模或体积小。", "安静": "安静说声音或环境，与“大型”没有反义关系。", "明亮": "明亮说光线或颜色，与“大型”没有反义关系。", "柔软": "柔软说质地，与“大型”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小型", "is_correct": true, "explanation": "小型与“大型”是反义词，指规模或体积小。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说说明或视线，与“大型”没有反义关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓说速度，与“大型”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙说质地，与“大型”没有反义关系。"}], "correct_answer": "小型", "explanations": {"小型": "小型与“大型”是反义词，指规模或体积小。", "清楚": "清楚说说明或视线，与“大型”没有反义关系。", "迟缓": "迟缓说速度，与“大型”没有反义关系。", "粗糙": "粗糙说质地，与“大型”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大型是说体积大,或规模大。", "primary_collocate": null, "pronunciation": "dà xíng", "ipa": "ta˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校下周要开一个大型运动会。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多大型超市。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末广场上有大型音乐会。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司做过很多大型活动。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年这里要办一场大型展览。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节晚会是一台大型节目。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正在建设大型工程，需要很多工人。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大型商场里有电影院和饭店。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周六有大型打折活动，人特别多。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了几百人参加大型会议。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大型的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "活动、场所等规模大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：体积或规模大的。"}, {"text": "大兴", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，大兴意思是大规模兴建。"}, {"text": "大姓", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，大姓意思是人数多的姓氏。"}, {"text": "大熊", "is_correct": false, "explanation": "xióng 与 xíng 韵母不同（-iong 与 -ing），大熊意思是大型的熊。"}], "explanations": {"大型": "大型：体积或规模大的。", "大兴": "xīng（第一声）与 xíng（第二声）声调不同，大兴意思是大规模兴建。", "大姓": "xìng（第四声）与 xíng（第二声）声调不同，大姓意思是人数多的姓氏。", "大熊": "xióng 与 xíng 韵母不同（-iong 与 -ing），大熊意思是大型的熊。"}, "sentence_index": null, "correct_answer": "大型"}, "level_3": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：修饰“运动会”，表示规模大，与“一个”和“下周要开”相合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容人或物的身材，不能修饰运动会。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻说人的年纪，不能修饰运动会。"}, {"text": "慢", "is_correct": false, "explanation": "语义：慢说速度，与运动会的规模不搭。"}], "explanations": {"大型": "大型：修饰“运动会”，表示规模大，与“一个”和“下周要开”相合。", "高大": "体貌：高大形容人或物的身材，不能修饰运动会。", "年轻": "语义：年轻说人的年纪，不能修饰运动会。", "慢": "语义：慢说速度，与运动会的规模不搭。"}, "sentence_index": 0, "correct_answer": "大型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们公司取得了大型的成功。", "explanation": "这里应该用〈巨大〉。巨大可修饰成功、影响等抽象事物，大型只用于活动、场所、机器等具体事物的规模或体积。"}, {"text": "他们公司投入了大型的资金。", "explanation": "这里应该用〈大量〉。大量修饰资金、人员等数量多的事物，大型不用来修饰资金。"}, {"text": "他们公司确定了一个大型的目标。", "explanation": "这里应该用〈宏大〉。宏大可修饰目标、构想等抽象事物，大型只用于活动、场所、机器等具体事物的规模或体积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：体积或规模大的。"}, {"text": "大幸", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，大幸意思是非常幸运。"}, {"text": "代行", "is_correct": false, "explanation": "dài 与 dà 韵母不同（-ai 与 -a），代行意思是代替别人行使职权。"}, {"text": "大凶", "is_correct": false, "explanation": "xiōng（第一声）与 xíng（第二声）韵母不同（-iong 与 -ing），声调也不同，大凶意思是大的灾祸。"}], "explanations": {"大型": "大型：体积或规模大的。", "大幸": "xìng（第四声）与 xíng（第二声）声调不同，大幸意思是非常幸运。", "代行": "dài 与 dà 韵母不同（-ai 与 -a），代行意思是代替别人行使职权。", "大凶": "xiōng（第一声）与 xíng（第二声）韵母不同（-iong 与 -ing），声调也不同，大凶意思是大的灾祸。"}, "sentence_index": null, "correct_answer": "大型"}, "level_3": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：修饰“工程”，表示规模大，与“需要很多工人”相合。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：矮小形容人或物的身材，不能修饰工程。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：年幼说人的年纪，与工程无关。"}, {"text": "清淡", "is_correct": false, "explanation": "语义：清淡说味道或颜色，不能修饰工程。"}], "explanations": {"大型": "大型：修饰“工程”，表示规模大，与“需要很多工人”相合。", "矮小": "体貌：矮小形容人或物的身材，不能修饰工程。", "年幼": "语义：年幼说人的年纪，与工程无关。", "清淡": "语义：清淡说味道或颜色，不能修饰工程。"}, "sentence_index": 6, "correct_answer": "大型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师有大型的教学经验。", "explanation": "这里应该用〈丰富〉。丰富修饰经验、知识等抽象事物，大型只用于具体事物的规模或体积。"}, {"text": "他在会上提出了一个大型的建议。", "explanation": "这里应该用〈重大〉。重大可修饰建议、决定等抽象事情，大型不用于修饰建议。"}, {"text": "他在比赛中赢得了大型的奖金。", "explanation": "这里应该用〈高额〉。高额修饰奖金、费用等金额，大型只用于具体事物的规模或体积，不修饰金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府计划在江边建一座很大型体育馆。", "corrected_sentence": "市政府计划在江边建一座大型体育馆。", "error_description": "错误在“很大型”。“大型”是区别词，不能受“很”修饰，应说“一座大型体育馆”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区去年办的那场义卖是大型。", "corrected_sentence": "社区去年办的那场义卖是大型的。", "error_description": "错误在“大型”后面漏了“的”。“大型”是区别词，不能单独作谓语，应说“是大型的”，不能说“是大型”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小型", "is_correct": true, "explanation": "小型与“大型”是反义词，指形体或规模小。"}, {"text": "安静", "is_correct": false, "explanation": "安静说声音或环境，与“大型”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮说光线或颜色，与“大型”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软说质地，与“大型”没有反义关系。"}], "correct_answer": "小型", "explanations": {"小型": "小型与“大型”是反义词，指形体或规模小。", "安静": "安静说声音或环境，与“大型”没有反义关系。", "明亮": "明亮说光线或颜色，与“大型”没有反义关系。", "柔软": "柔软说质地，与“大型”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
