INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形体或规模较大的。", "primary_collocate": null, "pronunciation": "dà xíng", "ipa": "ta˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大型动物需要很大的地方生活。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里有很多大型机器。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上开过来一辆大型卡车。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象是大型动物，一天吃很多草。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口能停大型轮船。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店的厨房太小，放不下大型冰箱。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大型飞机需要很长的跑道。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着一台大型机器在田里干活。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的大型鸟住在很大的笼子里。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥很宽，大型汽车也能过。", "target_word": "大型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大型的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "动物、机器、车船等形体较大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 开着 (Zipf 3.73), 田里 (Zipf 3.31), 干活 (Zipf 3.95)']::text[], '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：形体或规模较大的。"}, {"text": "大兴", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，大兴意思是大规模兴建。"}, {"text": "大姓", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，大姓意思是人数多的姓氏。"}, {"text": "大熊", "is_correct": false, "explanation": "xióng 与 xíng 韵母不同（-iong 与 -ing），大熊意思是大型的熊。"}], "explanations": {"大型": "大型：形体或规模较大的。", "大兴": "xīng（第一声）与 xíng（第二声）声调不同，大兴意思是大规模兴建。", "大姓": "xìng（第四声）与 xíng（第二声）声调不同，大姓意思是人数多的姓氏。", "大熊": "xióng 与 xíng 韵母不同（-iong 与 -ing），大熊意思是大型的熊。"}, "sentence_index": null, "correct_answer": "大型"}, "level_3": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：修饰“动物”，指形体大，与“需要很大的地方”相合。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：清澈说水或眼睛，不能修饰动物。"}, {"text": "狭小", "is_correct": false, "explanation": "语义：狭小与“需要很大的地方”矛盾。"}, {"text": "微弱", "is_correct": false, "explanation": "搭配：微弱修饰光、声音等，不修饰动物。"}], "explanations": {"大型": "大型：修饰“动物”，指形体大，与“需要很大的地方”相合。", "清澈": "语义：清澈说水或眼睛，不能修饰动物。", "狭小": "语义：狭小与“需要很大的地方”矛盾。", "微弱": "搭配：微弱修饰光、声音等，不修饰动物。"}, "sentence_index": 0, "correct_answer": "大型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感到了大型的压力。", "explanation": "这里应该用〈巨大〉。压力是抽象的，要用巨大；大型只用于有形的器物、场所、动物等的体积或规模。"}, {"text": "这次改革产生了大型的影响。", "explanation": "这里应该用〈深远〉。深远修饰影响、意义等抽象事物，大型只用于形体或规模较大的具体事物。"}, {"text": "这家公司雇用了大型的员工。", "explanation": "这里应该用〈大量〉。大量修饰员工、人员等数量多的事物，大型只用于形体或规模较大的具体事物，不修饰人员数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：形体或规模较大的。"}, {"text": "大幸", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，大幸意思是非常幸运。"}, {"text": "代行", "is_correct": false, "explanation": "dài 与 dà 韵母不同（-ai 与 -a），代行意思是代替别人行使职权。"}, {"text": "大凶", "is_correct": false, "explanation": "xiōng（第一声）与 xíng（第二声）韵母不同（-iong 与 -ing），声调也不同，大凶意思是大的灾祸。"}], "explanations": {"大型": "大型：形体或规模较大的。", "大幸": "xìng（第四声）与 xíng（第二声）声调不同，大幸意思是非常幸运。", "代行": "dài 与 dà 韵母不同（-ai 与 -a），代行意思是代替别人行使职权。", "大凶": "xiōng（第一声）与 xíng（第二声）韵母不同（-iong 与 -ing），声调也不同，大凶意思是大的灾祸。"}, "sentence_index": null, "correct_answer": "大型"}, "level_3": {"options": [{"text": "大型", "is_correct": true, "explanation": "大型：修饰“飞机”，指体积大，与“需要很长的跑道”相合。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：温柔说性情，不能修饰飞机。"}, {"text": "矮胖", "is_correct": false, "explanation": "体貌：矮胖形容人或动物的体形，不能修饰飞机。"}, {"text": "短小", "is_correct": false, "explanation": "语义：短小与“需要很长的跑道”矛盾。"}], "explanations": {"大型": "大型：修饰“飞机”，指体积大，与“需要很长的跑道”相合。", "温柔": "语义：温柔说性情，不能修饰飞机。", "矮胖": "体貌：矮胖形容人或动物的体形，不能修饰飞机。", "短小": "语义：短小与“需要很长的跑道”矛盾。"}, "sentence_index": 6, "correct_answer": "大型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为违规被处以大型罚款。", "explanation": "这里应该用〈高额〉。高额修饰罚款、费用等金额，大型只用于形体或规模较大的具体事物，不修饰金额。"}, {"text": "他在工作中积累了大型的经验。", "explanation": "这里应该用〈丰富〉。丰富修饰经验、知识等抽象事物，大型只用于具体事物的规模或体积。"}, {"text": "他做出了一个大型的决定。", "explanation": "这里应该用〈重大〉。重大可修饰决定、建议等抽象事情，大型不用于修饰决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个码头可以停靠很大型货轮。", "corrected_sentence": "这个码头可以停靠大型货轮。", "error_description": "错误在“很大型”。“大型”是区别词，不能受“很”修饰，应说“大型货轮”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开的那辆卡车是大型。", "corrected_sentence": "他开的那辆卡车是大型的。", "error_description": "错误在“大型”后面漏了“的”。“大型”是区别词，不能单独作谓语，应说“是大型的”，不能说“是大型”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
