INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88947, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "什么地方是问在哪里。", "primary_collocate": null, "pronunciation": "shén me dì fāng", "ipa": "ʂən˧˥ mə ti˥˩ fɑŋ˥", "syllable_count": 4, "sentences": [{"text": "你昨天去了什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是什么地方？我没来过。", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在什么地方吃饭？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的书放在什么地方了？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在什么地方见面？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的那家店在什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末你们打算去什么地方玩？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，洗手间在什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是在什么地方学汉语的？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "什么地方：询问在哪里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么地方", "is_correct": true, "explanation": "正确：“你昨天去了什么地方”，询问去的处所。"}, {"text": "什么时候", "is_correct": false, "explanation": "语义：“什么时候”问时间，不问处所，与“去了”后的地点不符。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，不能作“去了”的宾语。"}, {"text": "什么东西", "is_correct": false, "explanation": "搭配：“去”的对象是处所，不能说“去了什么东西”。"}], "explanations": {"什么地方": "正确：“你昨天去了什么地方”，询问去的处所。", "什么时候": "语义：“什么时候”问时间，不问处所，与“去了”后的地点不符。", "为什么": "语义：“为什么”问原因，不能作“去了”的宾语。", "什么东西": "搭配：“去”的对象是处所，不能说“去了什么东西”。"}, "sentence_index": 0, "correct_answer": "什么地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天是什么地方？", "explanation": "这里应该用〈几号〉。问日期要用“几号”或“哪天”，“什么地方”只问处所，不能用来问日期。"}, {"text": "你的电话号码是什么地方？", "explanation": "这里应该用〈多少〉。问号码要用“多少”或“几号”，“什么地方”只问处所，不能用来问号码。"}, {"text": "他的身高是什么地方？", "explanation": "这里应该用〈多高〉。问身高要用“多高”或“多少”，“什么地方”只问处所，不能用来问身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么地方", "is_correct": true, "explanation": "正确：“你说的那家店在什么地方”，询问处所。"}, {"text": "什么原因", "is_correct": false, "explanation": "语义：“什么原因”问理由，不问处所，与“在……”的地点义不符。"}, {"text": "什么样子", "is_correct": false, "explanation": "搭配：“在……”之后接处所，不能说“在什么样子”。"}, {"text": "什么颜色", "is_correct": false, "explanation": "搭配：颜色不是处所，“那家店在什么颜色”不成立。"}], "explanations": {"什么地方": "正确：“你说的那家店在什么地方”，询问处所。", "什么原因": "语义：“什么原因”问理由，不问处所，与“在……”的地点义不符。", "什么样子": "搭配：“在……”之后接处所，不能说“在什么样子”。", "什么颜色": "搭配：颜色不是处所，“那家店在什么颜色”不成立。"}, "sentence_index": 6, "correct_answer": "什么地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事你什么地方看？", "explanation": "这里应该用〈怎么〉。问看法或方式要用“怎么”，“什么地方”只问处所。"}, {"text": "他的年纪是什么地方？", "explanation": "这里应该用〈多大〉。问年纪要用“多大”或“几岁”，“什么地方”只问处所，不能用来问年纪。"}, {"text": "这次考试的成绩是什么地方？", "explanation": "这里应该用〈多少分〉。问分数要用“多少分”或“几分”，“什么地方”只问处所，不能用来问成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天去了什么地方吗？", "corrected_sentence": "他昨天去了什么地方？", "error_description": "疑问代词问句不能再加语气词“吗”：“什么地方”已构成特指问，应删去“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在什么地方买的这本书吗？", "corrected_sentence": "你在什么地方买的这本书？", "error_description": "疑问代词问句不能再加语气词“吗”：“什么地方”已构成特指问，应删去“吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
