INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88948, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词性短语，询问处所。", "primary_collocate": null, "pronunciation": "shén me dì fāng", "ipa": "ʂən˧˥ mə ti˥˩ fɑŋ˥", "syllable_count": 4, "sentences": [{"text": "你们在什么地方上班？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在在什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机在什么地方？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有什么地方好玩？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他去了什么地方。", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在什么地方买的这件衣服？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们是从什么地方来的。", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去什么地方旅行？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在什么地方见过他？", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，车站在什么地方。", "target_word": "什么地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "什么地方：疑问短语，问处所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么地方", "is_correct": true, "explanation": "正确：“你们在什么地方上班”，询问上班的处所。"}, {"text": "什么东西", "is_correct": false, "explanation": "语义：“东西”不是处所，不能作“在……上班”的场所。"}, {"text": "什么颜色", "is_correct": false, "explanation": "搭配：颜色不能作为上班的场所，这样组合不成立。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，不问处所，不能放在“在……上班”的位置。"}], "explanations": {"什么地方": "正确：“你们在什么地方上班”，询问上班的处所。", "什么东西": "语义：“东西”不是处所，不能作“在……上班”的场所。", "什么颜色": "搭配：颜色不能作为上班的场所，这样组合不成立。", "为什么": "语义：“为什么”问原因，不问处所，不能放在“在……上班”的位置。"}, "sentence_index": 0, "correct_answer": "什么地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请问什么地方是老师？", "explanation": "这里应该用〈哪位〉。问人的身份要用“哪位”，“什么地方”问的是处所。"}, {"text": "门口站着的是什么地方？", "explanation": "这里应该用〈什么人〉。问人要用“什么人”或“谁”，“什么地方”只问处所，不能指站着的人。"}, {"text": "什么地方是老板？", "explanation": "这里应该用〈谁〉。判断身份要用“谁”，“什么地方”问的是处所，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么地方", "is_correct": true, "explanation": "正确：“老师问我们是从什么地方来的”，询问来源的处所。"}, {"text": "什么原因", "is_correct": false, "explanation": "语义：“什么原因”问理由，不问处所，与“从……来”的空间义不符。"}, {"text": "什么样子", "is_correct": false, "explanation": "搭配：“从……来”的对象是处所，不能说“从什么样子来”。"}, {"text": "什么菜", "is_correct": false, "explanation": "搭配：菜不是处所，不能作为“从……来”的起点，这样组合不成立。"}], "explanations": {"什么地方": "正确：“老师问我们是从什么地方来的”，询问来源的处所。", "什么原因": "语义：“什么原因”问理由，不问处所，与“从……来”的空间义不符。", "什么样子": "搭配：“从……来”的对象是处所，不能说“从什么样子来”。", "什么菜": "搭配：菜不是处所，不能作为“从……来”的起点，这样组合不成立。"}, "sentence_index": 6, "correct_answer": "什么地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他叫什么地方？", "explanation": "这里应该用〈什么名字〉。问人的名字要说“叫什么名字”，“什么地方”只问处所，不能用来问人名。"}, {"text": "这本书的价格是什么地方？", "explanation": "这里应该用〈多少〉。问价格要用“多少钱”，“什么地方”只问处所，不能用来问价格。"}, {"text": "明天是什么地方？", "explanation": "这里应该用〈哪一天〉。问日期要用“哪一天”，“什么地方”问的是处所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
