INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88949, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商量是几个人一起说说，决定怎么办。", "primary_collocate": null, "pronunciation": "shāng liang", "ipa": "ʂaŋ˥ liaŋ", "syllable_count": 2, "sentences": [{"text": "我们几个人坐下来商量去哪儿玩。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考完试，大家一起商量怎么庆祝。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人围着桌子商量搬家的事。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在商量毕业旅行去哪儿。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先商量，想好了再告诉我。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈商量了一晚上，决定买房子。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们商量好了，周六一起去爬山。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太大，我们得商量商量。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围成一圈，小声商量办法。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们商量着怎么给老师过生日。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商量了", "label": "体标"}, {"form": "商量过", "label": "体标"}, {"form": "商量着", "label": "体标"}, {"form": "商量商量", "label": "重叠"}], "register": "口语", "sense_fingerprint": "几个人一起说说，决定怎么办", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商量", "is_correct": true, "explanation": "正确。「坐下来商量去哪儿玩」指几个人一起说说、决定去哪儿，符合句意。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：「欢呼」指高兴地大声叫好，与「决定去哪儿玩」的讨论无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是房间、场地，不能说「打扫去哪儿玩」。"}, {"text": "排队", "is_correct": false, "explanation": "配价：「排队」是不及物动词，不能带「去哪儿玩」这样的动词短语作补充，句子不通。"}], "explanations": {"商量": "正确。「坐下来商量去哪儿玩」指几个人一起说说、决定去哪儿，符合句意。", "欢呼": "语义：「欢呼」指高兴地大声叫好，与「决定去哪儿玩」的讨论无关。", "打扫": "搭配：「打扫」的对象是房间、场地，不能说「打扫去哪儿玩」。", "排队": "配价：「排队」是不及物动词，不能带「去哪儿玩」这样的动词短语作补充，句子不通。"}, "sentence_index": 0, "correct_answer": "商量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸商量我考试考得太差。", "explanation": "这里应该用〈责备〉。商量是几个人交换意见、一起决定怎么办，对孩子的过错表示不满要用责备。"}, {"text": "老师商量他这次进步很大。", "explanation": "这里应该用〈表扬〉。商量是交换意见、决定怎么办，称赞别人的进步要用表扬。"}, {"text": "服务员商量客人请坐。", "explanation": "这里应该用〈招呼〉。商量要双方交换意见，请客人入座是礼貌地招呼，要用招呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商量", "is_correct": true, "explanation": "正确。「我们商量好了，周六一起去爬山」指双方已经交换意见并定下计划。"}, {"text": "写作", "is_correct": false, "explanation": "搭配：「写作」需要文章之类的对象，不能用「写作好了」表示计划已经定下。"}, {"text": "发怒", "is_correct": false, "explanation": "语义：「发怒」指生气，与「周六一起去爬山」的约定不相符。"}, {"text": "大哭", "is_correct": false, "explanation": "语义：「大哭」表示伤心哭泣，与约好一起去爬山的意思矛盾。"}], "explanations": {"商量": "正确。「我们商量好了，周六一起去爬山」指双方已经交换意见并定下计划。", "写作": "搭配：「写作」需要文章之类的对象，不能用「写作好了」表示计划已经定下。", "发怒": "语义：「发怒」指生气，与「周六一起去爬山」的约定不相符。", "大哭": "语义：「大哭」表示伤心哭泣，与约好一起去爬山的意思矛盾。"}, "sentence_index": 6, "correct_answer": "商量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "坏人商量我交出钱包。", "explanation": "这里应该用〈威胁〉。商量是双方平等地交换意见，逼对方照做要用威胁。"}, {"text": "妈妈商量我：‘不许再玩手机！’", "explanation": "这里应该用〈禁止〉。商量是双方平等地交换意见；单方面下令不许做某事要用禁止。"}, {"text": "老师商量全班同学立即起立。", "explanation": "这里应该用〈命令〉。商量是双方平等地交换意见，要求别人立刻执行要用命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经商量了好周末去哪儿。", "corrected_sentence": "我们已经商量好了周末去哪儿。", "error_description": "错误：「商量了好」。结果补语「好」要紧跟动词，应说「商量好了」，「了」放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我把你商量一下。", "corrected_sentence": "这件事我跟你商量一下。", "error_description": "错误：「把你商量」。「商量」的对象要用介词「跟」引出，不能用「把」字句；应说「跟你商量」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
