INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交换意见，讨论如何处理。", "primary_collocate": null, "pronunciation": "shāng liang", "ipa": "ʂaŋ˥ liaŋ", "syllable_count": 2, "sentences": [{"text": "买房子的事，我想跟你商量一下。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题可以商量，别一个人生气。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个安排有问题，我们得好好商量。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做决定以前，从来不跟家人商量。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去找经理商量请假的事。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长商量孩子的学习问题。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不能马上决定，明天再商量吧。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同事商量过这个办法，他同意。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有事好商量，你先别着急。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩商量了很久，还是没有结果。", "target_word": "商量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商量了", "label": "体标"}, {"form": "商量过", "label": "体标"}, {"form": "商量商量", "label": "重叠"}], "register": "口语", "sense_fingerprint": "和人交换意见，讨论事情怎么处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商量", "is_correct": true, "explanation": "正确。「我想跟你商量一下」指交换意见、讨论买房子的事，符合句意。"}, {"text": "摇晃", "is_correct": false, "explanation": "搭配：「摇晃」的对象是物体或身体，不能说「跟你摇晃一下」来谈买房子的事。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：「报销」针对费用，不能说「跟你报销一下买房子的事」。"}, {"text": "出售", "is_correct": false, "explanation": "语义：「出售」是卖东西，与「买房子的事，我想跟你……」的商讨意思不符。"}], "explanations": {"商量": "正确。「我想跟你商量一下」指交换意见、讨论买房子的事，符合句意。", "摇晃": "搭配：「摇晃」的对象是物体或身体，不能说「跟你摇晃一下」来谈买房子的事。", "报销": "搭配：「报销」针对费用，不能说「跟你报销一下买房子的事」。", "出售": "语义：「出售」是卖东西，与「买房子的事，我想跟你……」的商讨意思不符。"}, "sentence_index": 0, "correct_answer": "商量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家商量他考上了大学，都很开心。", "explanation": "这里应该用〈祝贺〉。商量是交换意见、讨论如何处理，对别人的喜事表示庆贺要用祝贺。"}, {"text": "我把好消息商量了妈妈。", "explanation": "这里应该用〈告诉〉。商量指双方交换意见，只是通知别人要用告诉。"}, {"text": "他商量朋友：‘别再冲动了！’", "explanation": "这里应该用〈劝〉。商量是双方平等地交换意见；要对方改变做法是劝，不是商量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商量", "is_correct": true, "explanation": "正确。「这件事不能马上决定，明天再商量吧」指明天再交换意见、讨论处理，符合句意。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：「发呆」是呆坐出神，与「明天再……吧」的讨论意思不符。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：「放映」的对象是电影、影片，不能说「明天再放映吧」来指讨论事情。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是一种运动，与“这件事不能马上决定”的讨论意思不符。"}], "explanations": {"商量": "正确。「这件事不能马上决定，明天再商量吧」指明天再交换意见、讨论处理，符合句意。", "发呆": "语义：「发呆」是呆坐出神，与「明天再……吧」的讨论意思不符。", "放映": "搭配：「放映」的对象是电影、影片，不能说「明天再放映吧」来指讨论事情。", "游泳": "语义：“游泳”是一种运动，与“这件事不能马上决定”的讨论意思不符。"}, "sentence_index": 6, "correct_answer": "商量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导商量我们：‘明天七点出发！’", "explanation": "这里应该用〈通知〉。商量是双方平等地交换意见；上级单方面宣布安排要用通知。"}, {"text": "妈妈商量我：‘现在就去写作业！’", "explanation": "这里应该用〈催促〉。商量是双方平等地交换意见；要对方立刻做某事要用催促。"}, {"text": "老师商量了他的努力。", "explanation": "这里应该用〈表扬〉。商量是交换意见、讨论处理，对别人的好表现表示肯定要用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这事我想先大家商量一下。", "corrected_sentence": "这事我想先跟大家商量一下。", "error_description": "介词省略：「商量」表示与人交换意见，需要用「跟」引出对象；应说「跟大家商量」，不能说「大家商量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事情我想给你们商量一下。", "corrected_sentence": "这件事情我想跟你们商量一下。", "error_description": "错误：「给你们商量」。「商量」的对象要用介词「跟」引出，不能用「给」；应说「跟你们商量」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
