INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代是一代人，指家族中的辈分，比如爷爷是上一代，爸爸是下一代。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "爷爷是上一代，爸爸是下一代。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一代又一代，人们都爱这个地方。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店已经传了五代了。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是家里的第三代。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一代人都有自己的生活。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事一代一代传下来。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一代人喜欢早睡早起。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是我们的下一代。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家四代同堂，很热闹。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的一代不太看报纸。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一代人", "label": "复合"}, {"form": "老一代", "label": "复合"}, {"form": "四代同堂", "label": "复合"}], "register": "中性", "sense_fingerprint": "一代人，家族的辈分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代", "is_correct": true, "explanation": "正确答案。dài（第四声）是“代”的读音，指一代人、家族的辈分。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài（第四声）声调不同，意思是“呆”。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 dài 声母不同（t 与 d），意思是“太”。"}, {"text": "派", "is_correct": false, "explanation": "pài 与 dài 声母不同（p 与 d），意思是“派”。"}, {"text": "大", "is_correct": false, "explanation": "dà 与 dài 韵母不同（a 与 ai），意思是“大”。"}], "explanations": {"代": "正确答案。dài（第四声）是“代”的读音，指一代人、家族的辈分。", "呆": "dāi（第一声）与 dài（第四声）声调不同，意思是“呆”。", "太": "tài 与 dài 声母不同（t 与 d），意思是“太”。", "派": "pài 与 dài 声母不同（p 与 d），意思是“派”。", "大": "dà 与 dài 韵母不同（a 与 ai），意思是“大”。"}, "sentence_index": null, "correct_answer": "代"}, "level_3": {"options": [{"text": "代", "is_correct": true, "explanation": "正确：“上一代”“下一代”中的“代”指辈分，“爷爷是上一代”说的是长辈的一辈。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”指时间，爷爷不能是“上一年”，说不通。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天”指时间，不能说人是“上一天”，说不通。"}, {"text": "月", "is_correct": false, "explanation": "搭配：表示上个月要说“上个月”，“上一月”不能指人，搭配不当。"}], "explanations": {"代": "正确：“上一代”“下一代”中的“代”指辈分，“爷爷是上一代”说的是长辈的一辈。", "年": "语义：“年”指时间，爷爷不能是“上一年”，说不通。", "天": "语义：“天”指时间，不能说人是“上一天”，说不通。", "月": "搭配：表示上个月要说“上个月”，“上一月”不能指人，搭配不当。"}, "sentence_index": 0, "correct_answer": "代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正处于学习代。", "explanation": "这里应该用〈阶段〉。“代”指世代、辈分，不指学习过程中的某个阶段；“处于学习阶段”不能把“阶段”换成“代”。"}, {"text": "这是一个伟大的代。", "explanation": "这里应该用〈时代〉。“代”单用时不能指一个时代，说“伟大的时代”才对。"}, {"text": "我家有三个代住在一起。", "explanation": "这里应该用〈三代〉。表示几代时，“代”直接接在数字后，不能在“代”前加量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "代", "is_correct": true, "explanation": "正确答案。dài（第四声）是“代”的读音，指一代人、家族的辈分。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g 与 d），意思是“盖”。"}, {"text": "在", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），意思是“在”。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 dài 韵母不同（ui 与 ai），意思是“对”。"}], "explanations": {"代": "正确答案。dài（第四声）是“代”的读音，指一代人、家族的辈分。", "盖": "gài 与 dài 声母不同（g 与 d），意思是“盖”。", "在": "zài 与 dài 声母不同（z 与 d），意思是“在”。", "对": "duì 与 dài 韵母不同（ui 与 ai），意思是“对”。"}, "sentence_index": null, "correct_answer": "代"}, "level_3": {"options": [{"text": "代", "is_correct": true, "explanation": "正确：“老一代人”指年长的一辈人，这里的“代”是辈分义。"}, {"text": "秒", "is_correct": false, "explanation": "语义：“秒”是最小的时间单位，不指人群，“老一秒人”说不通。"}, {"text": "周", "is_correct": false, "explanation": "语义：“周”指一周的时间，不能指人群，“老一周人”说不通。"}, {"text": "季", "is_correct": false, "explanation": "搭配：“季”与“春季”“四季”搭配，不能说“老一季人”。"}], "explanations": {"代": "正确：“老一代人”指年长的一辈人，这里的“代”是辈分义。", "秒": "语义：“秒”是最小的时间单位，不指人群，“老一秒人”说不通。", "周": "语义：“周”指一周的时间，不能指人群，“老一周人”说不通。", "季": "搭配：“季”与“春季”“四季”搭配，不能说“老一季人”。"}, "sentence_index": 6, "correct_answer": "代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的代比爸爸大。", "explanation": "这里应该用〈年龄〉。“代”不能用来比较人的年纪大小，说年纪要用“年龄”。"}, {"text": "他在这家公司工作了三代。", "explanation": "这里应该用〈年〉。“代”指一代人、世代，计算工作时间要用“年”，不能说“工作了三代”。"}, {"text": "这一家有四个代的人。", "explanation": "这里应该用〈四代〉。几代要直接说“四代”，“代”前不加量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全家住着三个代人。", "corrected_sentence": "全家住着三代人。", "error_description": "错误：“三个代人”；正确：“三代人”。计数“代”时，数字后直接接“代”，不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要为一下代着想。", "corrected_sentence": "我们要为下一代着想。", "error_description": "错误：“一下代”；正确：“下一代”。“下一”是固定组合，指后面的一辈，不能颠倒成“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
