INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时代；世代；辈。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "爷爷那一代人吃过很多苦。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这一代人是看电视长大的。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家三代人住在一起。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代都喜欢用手机。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一代人的故事很有意思。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要给下一代一个好环境。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里有四代人。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶、妈妈和我是三代人。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这一代人很爱学习。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该教育好下一代。", "target_word": "代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上一代", "label": "复合"}, {"form": "下一代", "label": "复合"}, {"form": "年轻一代", "label": "复合"}], "register": "中性", "sense_fingerprint": "世代，辈分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代", "is_correct": true, "explanation": "正确答案。dài（第四声）是“代”的读音，指世代、辈分。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài（第四声）声调不同，意思是“呆”。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 dài 声母不同（t 与 d），意思是“太”。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），意思是“再”。"}, {"text": "派", "is_correct": false, "explanation": "pài 与 dài 声母不同（p 与 d），意思是“派”。"}], "explanations": {"代": "正确答案。dài（第四声）是“代”的读音，指世代、辈分。", "呆": "dāi（第一声）与 dài（第四声）声调不同，意思是“呆”。", "太": "tài 与 dài 声母不同（t 与 d），意思是“太”。", "再": "zài 与 dài 声母不同（z 与 d），意思是“再”。", "派": "pài 与 dài 声母不同（p 与 d），意思是“派”。"}, "sentence_index": null, "correct_answer": "代"}, "level_3": {"options": [{"text": "代", "is_correct": true, "explanation": "正确：“那一代人”指爷爷那一辈的人，“代”指同一辈分的人群。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天”是时间单位，不指人群，“那一天人”说不通。"}, {"text": "岁", "is_correct": false, "explanation": "搭配：“岁”只与年龄数字搭配，不能说“那一岁人”。"}, {"text": "月", "is_correct": false, "explanation": "语义：“月”指月份，不能指一辈人，“那一月人”说不通。"}], "explanations": {"代": "正确：“那一代人”指爷爷那一辈的人，“代”指同一辈分的人群。", "天": "语义：“天”是时间单位，不指人群，“那一天人”说不通。", "岁": "搭配：“岁”只与年龄数字搭配，不能说“那一岁人”。", "月": "语义：“月”指月份，不能指一辈人，“那一月人”说不通。"}, "sentence_index": 0, "correct_answer": "代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年两代了。", "explanation": "这里应该用〈岁〉。“代”不用来计算年龄，说年龄要用“岁”。"}, {"text": "在困难代，大家互相帮助。", "explanation": "这里应该用〈时期〉。“代”单用时不指一段时期，“困难时期”的“时期”不能换成“代”。"}, {"text": "我家有三个代。", "explanation": "这里应该用〈三代〉。表示几代时，“代”直接接在数字后，不能在“代”前加量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88954, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "代", "is_correct": true, "explanation": "正确答案。dài（第四声）是“代”的读音，指世代、辈分。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g 与 d），意思是“盖”。"}, {"text": "在", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），意思是“在”。"}, {"text": "大", "is_correct": false, "explanation": "dà 与 dài 韵母不同（a 与 ai），意思是“大”。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 dài 韵母不同（ui 与 ai），意思是“对”。"}], "explanations": {"代": "正确答案。dài（第四声）是“代”的读音，指世代、辈分。", "盖": "gài 与 dài 声母不同（g 与 d），意思是“盖”。", "在": "zài 与 dài 声母不同（z 与 d），意思是“在”。", "大": "dà 与 dài 韵母不同（a 与 ai），意思是“大”。", "对": "duì 与 dài 韵母不同（ui 与 ai），意思是“对”。"}, "sentence_index": null, "correct_answer": "代"}, "level_3": {"options": [{"text": "代", "is_correct": true, "explanation": "正确：“有四代人”指四辈同住，“代”指同辈分的人群。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”是时间单位，不指人群，“四年人”说不通。"}, {"text": "周", "is_correct": false, "explanation": "语义：“周”指七天的时间，不能指人群，“四周人”说不通。"}, {"text": "季", "is_correct": false, "explanation": "搭配：“季”用于“春季”“四季”等，不能用来数人，“四季人”不成立。"}], "explanations": {"代": "正确：“有四代人”指四辈同住，“代”指同辈分的人群。", "年": "语义：“年”是时间单位，不指人群，“四年人”说不通。", "周": "语义：“周”指七天的时间，不能指人群，“四周人”说不通。", "季": "搭配：“季”用于“春季”“四季”等，不能用来数人，“四季人”不成立。"}, "sentence_index": 6, "correct_answer": "代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的代比我高。", "explanation": "这里应该用〈辈分〉。“代”不能单独表示辈分的高低，比较辈分要用“辈分”。"}, {"text": "这是上个代的建筑。", "explanation": "这里应该用〈世纪〉。“代”指世代、辈分，不指以百年为单位的时期；说“上个世纪的建筑”才对。"}, {"text": "我们家有两个代的人住在一起。", "explanation": "这里应该用〈两代〉。表示几代人时，数量后直接接“代”，不能加量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家住着两个代人。", "corrected_sentence": "他们家住着两代人。", "error_description": "错误：“两个代人”；正确：“两代人”。计数“代”时，数字后直接接“代”，不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家是四个代同堂的家庭。", "corrected_sentence": "我家是四代同堂的家庭。", "error_description": "错误：“四个代同堂”；正确：“四代同堂”。计数“代”时，数字后直接接“代”，不加量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
