INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地动是地面晃动，就是地震。", "primary_collocate": null, "pronunciation": "dì dòng", "ipa": "ti˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "古时候的人把地震叫作地动。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天夜里地动了，屋子晃了几下。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动的时候，桌上的杯子都在响。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说东边那个城市昨晚地动了。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动过后，大家都跑到了外面。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，这里很多年没有地动了。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里读到了那场地动造成的伤亡。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜地动，孩子们都吓醒了。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动来得很突然，我们没有准备。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一年地动很厉害，房子都倒了。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "书面", "sense_fingerprint": "地面晃动，即地震", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地动", "is_correct": true, "explanation": "正确。古时候的人把地震叫作“地动”，与定义“地面晃动，就是地震”一致。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是画出的地面示意图，不是地面晃动，“把地震叫作地图”说不通。"}, {"text": "地儿", "is_correct": false, "explanation": "语域：“地儿”是北京口语，指地方，与书面的叙述不合语域，且意思也不是地震。"}, {"text": "地雷", "is_correct": false, "explanation": "语义：地雷是爆炸武器，不是自然现象，“把地震叫作地雷”说不通。"}], "explanations": {"地动": "正确。古时候的人把地震叫作“地动”，与定义“地面晃动，就是地震”一致。", "地图": "语义：地图是画出的地面示意图，不是地面晃动，“把地震叫作地图”说不通。", "地儿": "语域：“地儿”是北京口语，指地方，与书面的叙述不合语域，且意思也不是地震。", "地雷": "语义：地雷是爆炸武器，不是自然现象，“把地震叫作地雷”说不通。"}, "sentence_index": 0, "correct_answer": "地动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心里一直地动，很不安。", "explanation": "这里应该用〈不安〉。地动指地面晃动，即地震，不能用来说人心里的感受。"}, {"text": "这块地动很平，适合种庄稼。", "explanation": "地动指地面晃动，即地震；这里把“地动”当成了土地，说平整的土地要用“地”，而不是“地动”。"}, {"text": "这辆老车在山路上地动得厉害。", "explanation": "这里应该用〈颠簸〉。地动指地面晃动，即地震；车辆在山路上一起一伏要用颠簸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地动", "is_correct": true, "explanation": "正确。“那场地动造成的伤亡”指地震造成的伤亡，符合句意。"}, {"text": "地形", "is_correct": false, "explanation": "语义：“那场”只用于事件，地形不是事件，“那场地形”说不通。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，与地面晃动无关，句意不通。"}, {"text": "地界儿", "is_correct": false, "explanation": "语域：“地界儿”是北京口语，指地方，书面语境中不合语域，且“那场地界儿”说不通。"}], "explanations": {"地动": "正确。“那场地动造成的伤亡”指地震造成的伤亡，符合句意。", "地形": "语义：“那场”只用于事件，地形不是事件，“那场地形”说不通。", "地毯": "语义：地毯是铺在地上的织物，与地面晃动无关，句意不通。", "地界儿": "语域：“地界儿”是北京口语，指地方，书面语境中不合语域，且“那场地界儿”说不通。"}, "sentence_index": 6, "correct_answer": "地动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗衣机一转，地动就很厉害。", "explanation": "这里应该用〈震动〉。地动专指地面晃动，即地震；洗衣机等物体的晃动要用震动。"}, {"text": "那几年社会地动，人们很不安。", "explanation": "这里应该用〈动荡〉。地动只指地面晃动，社会的不稳定要用动荡。"}, {"text": "医生说他的心脏老是地动。", "explanation": "这里应该用〈颤动〉。地动只指地面晃动，心脏等器官的颤动不能说地动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天夜里我地动了，屋子晃了一下。", "corrected_sentence": "昨天夜里地动了，屋子晃了一下。", "error_description": "错误在主语“我”。地动是自然现象，不能以人作主语，去掉“我”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚地动了一个，我被吓醒了。", "corrected_sentence": "昨晚地动了一下，我被吓醒了。", "error_description": "错误在计量词。地动是一次一次发生的事件，说动了多久（一下）时要用“一下”，不能用“一个”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
