INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地震。", "primary_collocate": null, "pronunciation": "dì dòng", "ipa": "ti˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "地动发生时，我正在厨房做饭。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地动的时间很短，没有人受伤。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，地动前动物常常不安。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在那次地动中失去了自己的家。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动以后，路上的车都停了下来。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，南方昨天有一场地动。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候经历过一次强烈的地动。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动的消息传来，大家都很担心。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了应对地动，学校常常组织躲避练习。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地动让这座老桥裂开了。", "target_word": "地动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "书面", "sense_fingerprint": "地震", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地动", "is_correct": true, "explanation": "正确。“地动”即地震，与“发生”搭配，符合句意。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“发生”不与“地毯”搭配，地毯不会“发生”。"}, {"text": "地形", "is_correct": false, "explanation": "语义：地形是地面的形态，不是会“发生”的事件，句意不通。"}, {"text": "地儿", "is_correct": false, "explanation": "语域：“地儿”是北京口语，书面语境中不合语域，且“地儿发生时”说不通。"}], "explanations": {"地动": "正确。“地动”即地震，与“发生”搭配，符合句意。", "地毯": "搭配：“发生”不与“地毯”搭配，地毯不会“发生”。", "地形": "语义：地形是地面的形态，不是会“发生”的事件，句意不通。", "地儿": "语域：“地儿”是北京口语，书面语境中不合语域，且“地儿发生时”说不通。"}, "sentence_index": 0, "correct_answer": "地动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在那块地动里种出了很多庄稼。", "explanation": "这里应该用〈地〉。地动指地震，不指土地；这里把“地动”当成了土地，说土地要用“地”。"}, {"text": "医生说，他的心脏有轻微地动。", "explanation": "这里应该用〈颤动〉。地动专指地面晃动，人体器官的颤动要用颤动。"}, {"text": "这台机器一开，地动就很厉害。", "explanation": "这里应该用〈震动〉。地动专指地面晃动，机器的晃动要用震动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地动", "is_correct": true, "explanation": "正确。“强烈的地动”指强烈的地震，与“经历过”相合。"}, {"text": "地壳", "is_correct": false, "explanation": "语义：地壳是地球的外层岩石，不是可以“经历”的强烈事件，句意不通。"}, {"text": "地产", "is_correct": false, "explanation": "搭配：“强烈”不修饰地产，“经历过一次强烈的地产”不成立。"}, {"text": "地窖", "is_correct": false, "explanation": "语义：地窖是地下的储藏室，不是可以“经历”的自然事件。"}], "explanations": {"地动": "正确。“强烈的地动”指强烈的地震，与“经历过”相合。", "地壳": "语义：地壳是地球的外层岩石，不是可以“经历”的强烈事件，句意不通。", "地产": "搭配：“强烈”不修饰地产，“经历过一次强烈的地产”不成立。", "地窖": "语义：地窖是地下的储藏室，不是可以“经历”的自然事件。"}, "sentence_index": 6, "correct_answer": "地动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几年的经济地动很厉害。", "explanation": "这里应该用〈动荡〉。地动只指地面晃动，经济、社会的不稳定要用动荡。"}, {"text": "他的信心有些地动，很难做决定。", "explanation": "这里应该用〈动摇〉。地动指地面晃动，人的信心、信念不稳要用动摇。"}, {"text": "这块地动很平，适合种菜。", "explanation": "地动指地面晃动，即地震；这里把“地动”当成了土地，平整的土地要说“地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校刚开学，我们就地动了一次。", "corrected_sentence": "学校刚开学，就地动了一次。", "error_description": "错误在主语“我们”。地动是自然现象，不能以人作主语，去掉“我们”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那一条地动让老房子塌了一半。", "corrected_sentence": "那一场地动让老房子塌了一半。", "error_description": "错误在量词。“地动”是一次发生的事件，要用“场”或“次”计量，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
