INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "童话是给小朋友讲的故事，里面有会说话的动物。", "primary_collocate": null, "pronunciation": "tóng huà", "ipa": "tʰʊŋ˧˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈每天晚上给我讲一个童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个童话里有一只会说话的兔子。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明最爱听奶奶讲童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，爸爸给弟弟讲了两个童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个童话很有意思，小朋友都喜欢。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给孩子们讲了一个关于小熊的童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐把这个童话讲给大家听。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候听过很多童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个童话的最后，小鸟飞回了家。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟听完童话，很快就睡着了。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个童话", "label": "量词"}, {"form": "一篇童话", "label": "量词"}, {"form": "童话故事", "label": "复合"}, {"form": "童话书", "label": "复合"}], "register": "口语", "sense_fingerprint": "大人讲给小朋友听的、有会说话动物的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "童话", "is_correct": true, "explanation": "童话：给小朋友讲的、带幻想色彩的故事，睡前讲给“我”听，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“讲”的对象是故事、道理等内容，不能说讲一个石头。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“讲”需要内容作宾语，“电脑”是实物，不能讲给人听。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是睡前可以讲的内容。"}], "explanations": {"童话": "童话：给小朋友讲的、带幻想色彩的故事，睡前讲给“我”听，符合句意。", "石头": "搭配：“讲”的对象是故事、道理等内容，不能说讲一个石头。", "电脑": "配价：“讲”需要内容作宾语，“电脑”是实物，不能讲给人听。", "书包": "语义：书包是装东西的袋子，不是睡前可以讲的内容。"}, "sentence_index": 0, "correct_answer": "童话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国古代流传着女娲补天的童话。", "explanation": "这里应该用〈神话〉。女娲补天是古代流传的神话；童话是专为儿童编写的作品，不能用来指古代神话。"}, {"text": "他讲的是自己亲身经历的童话。", "explanation": "这里应该用〈故事〉。童话是虚构的、带幻想色彩的，不能用来指亲身经历的真事。"}, {"text": "这本童话是作者每天睡前写下的日记。", "explanation": "这里应该用〈日记〉。日记记录作者自己每天的生活，童话是虚构的故事，不能用来指日记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "童话", "is_correct": true, "explanation": "童话：给小朋友讲的故事，这里是姐姐讲给大家听的内容，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讲给大家听”说的是内容，不说讲窗户。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是可以讲给别人听的东西。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“讲”的宾语应是故事、道理等内容，“汽车”是实物。"}], "explanations": {"童话": "童话：给小朋友讲的故事，这里是姐姐讲给大家听的内容，符合句意。", "窗户": "搭配：“讲给大家听”说的是内容，不说讲窗户。", "钥匙": "语义：钥匙是开锁的工具，不是可以讲给别人听的东西。", "汽车": "配价：“讲”的宾语应是故事、道理等内容，“汽车”是实物。"}, "sentence_index": 6, "correct_answer": "童话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟听完一只童话，很快就睡着了。", "explanation": "这里应该用〈个〉或〈篇〉。〈只〉主要用于动物，童话是作品，不能用“只”。"}, {"text": "弟弟听完一首童话，很快就睡着了。", "explanation": "这里应该用〈个〉或〈篇〉。〈首〉用于诗词、歌曲，童话是散文体的故事，不能用“首”。"}, {"text": "弟弟听完一座童话，很快就睡着了。", "explanation": "这里应该用〈个〉或〈篇〉。〈座〉用于山、桥、房屋等大型固定的东西，童话不能用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天读了一只童话。", "corrected_sentence": "我昨天读了一篇童话。", "error_description": "量词错误：“童话”作为文章要用“篇”，“只”用于动物，应说“一篇童话”，不能说“一只童话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈讲完了一只童话，就关灯了。", "corrected_sentence": "妈妈讲完了一个童话，就关灯了。", "error_description": "量词错误：“只”用于动物，“童话”作为讲述的故事应用“个”，应说“讲完了一个童话”，不能说“讲完了一只童话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
