INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专为儿童编写的、带有幻想色彩的故事。", "primary_collocate": null, "pronunciation": "tóng huà", "ipa": "tʰʊŋ˧˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "安徒生写了很多有名的童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "童话常常带有幻想的色彩。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家专门为孩子写童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部童话充满了奇妙的想象。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的童话把动物写得像人一样。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有十篇童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "童话是儿童文学的一种。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读过不少格林写的童话。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的童话能让孩子学到道理。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个作家的童话在很多国家出版了。", "target_word": "童话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇童话", "label": "量词"}, {"form": "一个童话", "label": "量词"}, {"form": "童话故事", "label": "复合"}, {"form": "童话世界", "label": "复合"}], "register": "书面", "sense_fingerprint": "作家专为儿童创作的、带幻想色彩的文学作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "童话", "is_correct": true, "explanation": "童话：专为儿童写的、带幻想色彩的文学作品，安徒生写的有名作品，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“写”的对象是文字作品，不能说写一块石头。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记录费用的单据，不是有名的文学作品。"}, {"text": "早饭", "is_correct": false, "explanation": "配价：“写”的宾语须是可以写下的内容，“早饭”是食物，不能被写出来。"}], "explanations": {"童话": "童话：专为儿童写的、带幻想色彩的文学作品，安徒生写的有名作品，符合句意。", "石头": "搭配：“写”的对象是文字作品，不能说写一块石头。", "账单": "语义：账单是记录费用的单据，不是有名的文学作品。", "早饭": "配价：“写”的宾语须是可以写下的内容，“早饭”是食物，不能被写出来。"}, "sentence_index": 0, "correct_answer": "童话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本童话记录了作者父亲的一生。", "explanation": "这里应该用〈传记〉。传记记录真实人物的经历，童话是虚构的作品，不能用来记录真人的一生。"}, {"text": "希腊童话里有很多神和英雄。", "explanation": "这里应该用〈神话〉。希腊神话是古代流传的神话，不是专为儿童创作的童话。"}, {"text": "今天的报纸上登了一篇关于车祸的童话。", "explanation": "这里应该用〈新闻〉或〈报道〉。报纸报道的是真实发生的事，童话是为儿童写的幻想故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "童话", "is_correct": true, "explanation": "童话：专为儿童创作的文学作品，属于儿童文学，符合句意。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画属于美术，不是儿童文学的一种。"}, {"text": "法律条文", "is_correct": false, "explanation": "语义：法律条文是规定法律的文字，不属于儿童文学。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是实用的饮食指南，不属于文学。"}], "explanations": {"童话": "童话：专为儿童创作的文学作品，属于儿童文学，符合句意。", "绘画": "语义：绘画属于美术，不是儿童文学的一种。", "法律条文": "语义：法律条文是规定法律的文字，不属于儿童文学。", "食谱": "语义：食谱是实用的饮食指南，不属于文学。"}, "sentence_index": 6, "correct_answer": "童话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个作家的一只童话在很多国家出版了。", "explanation": "这里应该用〈篇〉或〈个〉。〈只〉主要用于动物，童话是作品，不能用“只”。"}, {"text": "这个作家的一座童话在很多国家出版了。", "explanation": "这里应该用〈篇〉或〈个〉。〈座〉用于山、桥、房屋等，童话不能用“座”。"}, {"text": "这个作家的一棵童话在很多国家出版了。", "explanation": "这里应该用〈篇〉或〈个〉。〈棵〉用于树、草等植物，童话不能用“棵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家写了一首童话。", "corrected_sentence": "这位作家写了一篇童话。", "error_description": "量词错误：“童话”作为文章要用“篇”，“首”用于诗词、歌曲，应说“一篇童话”，不能说“一首童话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作家写完了一只童话，就交给了出版社。", "corrected_sentence": "作家写完了一篇童话，就交给了出版社。", "error_description": "量词错误：“只”用于动物，“童话”作为文学作品应用“篇”，应说“写完了一篇童话”，不能说“写完了一只童话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动", "is_correct": true, "explanation": "动与停意思相反，指开始运动，与停放不动相对。"}, {"text": "唱", "is_correct": false, "explanation": "唱指发出歌声，与停没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃指把食物咽下，与停没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写指用笔记录文字，与停没有反义关系。"}], "correct_answer": "动", "explanations": {"动": "动与停意思相反，指开始运动，与停放不动相对。", "唱": "唱指发出歌声，与停没有反义关系。", "吃": "吃指把食物咽下，与停没有反义关系。", "写": "写指用笔记录文字，与停没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动", "is_correct": true, "explanation": "动与停意思相反，指开始运动，与电梯停在五楼相对。"}, {"text": "读", "is_correct": false, "explanation": "读指看着文字出声或默念，与停没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡指闭眼休息，与停没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑指面部表情或发出笑声，与停没有反义关系。"}], "correct_answer": "动", "explanations": {"动": "动与停意思相反，指开始运动，与电梯停在五楼相对。", "读": "读指看着文字出声或默念，与停没有反义关系。", "睡": "睡指闭眼休息，与停没有反义关系。", "笑": "笑指面部表情或发出笑声，与停没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "停是不再动了，停在那里。", "primary_collocate": null, "pronunciation": "tíng", "ipa": "tʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "那辆白色的车停在楼下。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟停在树枝上唱歌。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船停在河边，没有动。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拖拉机停在田边的树下。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把自行车停在这里。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车停在仓库门口，一直没走。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车停了一晚上。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车停在路边，人们下了车。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶停在花上，一动也不动。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯停在五楼，门没有开。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停了", "label": "体标"}, {"form": "停着", "label": "体标"}, {"form": "停过", "label": "体标"}, {"form": "停止", "label": "复合"}, {"form": "停车", "label": "复合"}], "register": "中性", "sense_fingerprint": "停：不再动，停放在某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指不再动，停放在某处。"}, {"text": "听", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 tíng 韵母不同（o/i），意思是相同。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 tíng 韵母不同（e/i），意思是疼痛。"}, {"text": "零", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是数字零。"}], "explanations": {"停": "正确答案：停（tíng）指不再动，停放在某处。", "听": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。", "挺": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。", "同": "tóng 与 tíng 韵母不同（o/i），意思是相同。", "疼": "téng 与 tíng 韵母不同（e/i），意思是疼痛。", "零": "líng 与 tíng 声母不同（l/t），意思是数字零。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：车不再移动，停放在楼下，与语境相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，车不能飞。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”用于人或动物，不能说车坐在楼下。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与车停放的情境无关。"}], "explanations": {"停": "停：车不再移动，停放在楼下，与语境相符。", "飞": "语义：“飞”指在空中移动，车不能飞。", "坐": "搭配：“坐”用于人或动物，不能说车坐在楼下。", "唱": "语义：“唱”指发出歌声，与车停放的情境无关。"}, "sentence_index": 0, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那幅画停在墙上。", "explanation": "这里应该用〈挂〉。停指车、船、鸟等停留在某处，画要挂在墙上。"}, {"text": "书停在桌子上。", "explanation": "这里应该用〈放〉。停只用于车、船、鸟等停留，书要说放在桌子上。"}, {"text": "商品停在货架上。", "explanation": "这里应该用〈摆〉。停不用于商品的陈列，商品要说摆在货架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指不再动，停放在某处。"}, {"text": "厅", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。"}, {"text": "艇", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。"}, {"text": "灵", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是糖果。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}], "explanations": {"停": "正确答案：停（tíng）指不再动，停放在某处。", "厅": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。", "艇": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。", "灵": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。", "糖": "táng 与 tíng 韵母不同（a/i），意思是糖果。", "堂": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：车停放了一晚上，与语境相符。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”指人居住或留宿，车不能说住一晚上。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与车无关。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔记录文字，车不能写。"}], "explanations": {"停": "停：车停放了一晚上，与语境相符。", "住": "搭配：“住”指人居住或留宿，车不能说住一晚上。", "吃": "语义：“吃”指把食物咽下，与车无关。", "写": "语义：“写”指用笔记录文字，车不能写。"}, "sentence_index": 6, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把垃圾停在门口。", "explanation": "这里应该用〈扔〉。停只用于车、船、鸟等停留，垃圾要说扔掉或放在门口。"}, {"text": "这棵树停在河边。", "explanation": "这里应该用〈长〉。停指车、船或鸟等移动后停留，树是固定的植物，应说长在河边。"}, {"text": "行李停在车站门口。", "explanation": "这里应该用〈堆〉。停指车、船或鸟等停留，行李要说堆放在车站门口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used