INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "止住；不再继续前进或活动。", "primary_collocate": null, "pronunciation": "tíng", "ipa": "tʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "雨停了，我们出去走走吧。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车在门口停了一下，又开走了。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里停一下。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到桥边就停了。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟停了，现在几点？", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停了，天气也变好了。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，车都停下来了。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，想停一会儿。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐突然停了，大家都看着他。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直赶路，中间没有停。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停了", "label": "体标"}, {"form": "停着", "label": "体标"}, {"form": "停过", "label": "体标"}, {"form": "停止", "label": "复合"}, {"form": "停车", "label": "复合"}], "register": "中性", "sense_fingerprint": "停：止住，不再继续前进或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指止住，不再继续前进或活动。"}, {"text": "听", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 tíng 韵母不同（o/i），意思是相同。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 tíng 韵母不同（e/i），意思是疼痛。"}, {"text": "零", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是数字零。"}], "explanations": {"停": "正确答案：停（tíng）指止住，不再继续前进或活动。", "听": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。", "挺": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。", "同": "tóng 与 tíng 韵母不同（o/i），意思是相同。", "疼": "téng 与 tíng 韵母不同（e/i），意思是疼痛。", "零": "líng 与 tíng 声母不同（l/t），意思是数字零。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：雨止住，不再下，与“出去走走”的语境相符。"}, {"text": "刮", "is_correct": false, "explanation": "搭配：“刮”多用于风，不能说“雨刮了”。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，雨不会飞。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”要求食物作宾语，雨不能被吃。"}], "explanations": {"停": "停：雨止住，不再下，与“出去走走”的语境相符。", "刮": "搭配：“刮”多用于风，不能说“雨刮了”。", "飞": "语义：“飞”指在空中移动，雨不会飞。", "吃": "语义：“吃”要求食物作宾语，雨不能被吃。"}, "sentence_index": 0, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他停了外套，挂在椅子上。", "explanation": "这里应该用〈脱〉。停表示止住或不再继续，不能表示脱下衣物，应说“脱”。"}, {"text": "他停了桌子，然后坐下。", "explanation": "这里应该用〈擦〉。停表示止住，不能表示擦拭桌面，应说“擦”。"}, {"text": "他停好了碗，然后出门。", "explanation": "这里应该用〈洗〉。停表示止住，不能表示清洗餐具，应说“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88960, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指止住，不再继续前进或活动。"}, {"text": "厅", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。"}, {"text": "艇", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。"}, {"text": "灵", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是糖果。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}], "explanations": {"停": "正确答案：停（tíng）指止住，不再继续前进或活动。", "厅": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。", "艇": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。", "灵": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。", "糖": "táng 与 tíng 韵母不同（a/i），意思是糖果。", "堂": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：车因红灯止住，与“车都停下来了”的语境相符。"}, {"text": "掉", "is_correct": false, "explanation": "语义：“掉下来”指脱落或坠落，与红灯亮后车停下的情境不符。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”的主语通常是风或气，不能用于车。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑下来”指快速向下移动，与红灯亮后车要停下的情境相反。"}], "explanations": {"停": "停：车因红灯止住，与“车都停下来了”的语境相符。", "掉": "语义：“掉下来”指脱落或坠落，与红灯亮后车停下的情境不符。", "吹": "搭配：“吹”的主语通常是风或气，不能用于车。", "跑": "语义：“跑下来”指快速向下移动，与红灯亮后车要停下的情境相反。"}, "sentence_index": 6, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他停下了书包，坐在椅子上。", "explanation": "这里应该用〈放下〉。停下指使运动或动作止住，不能带“书包”这类物体作宾语。"}, {"text": "他停了窗户，屋里安静下来。", "explanation": "这里应该用〈关〉。停表示止住运动或动作，关上窗户要说“关”。"}, {"text": "他停了门，让客人进来。", "explanation": "这里应该用〈开〉。停指止住运动，打开门应说“开”，不能说“停门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车在路口停起来了。", "corrected_sentence": "车在路口停下来了。", "error_description": "错误：停起来。正确：停下来。“停”表示止住，“下来”表示动作由动转静，“起来”不能表示止住。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他中途停了过一次。", "corrected_sentence": "他中途停过一次。", "error_description": "错误：停了过。正确：停过。“过”表示经历，“了”表示完成，两者不能同时加在同一个动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
