INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报请是写下来，请上面的人同意。", "primary_collocate": null, "pronunciation": "bào qǐng", "ipa": "pɑʊ˥˩ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事要写成文件，报请上级同意。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把计划写好，报请校长同意。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师报请学校同意后，才带我们去参观。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动要先报请领导。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经报请总经理同意了。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经报请上级，正在等回复。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的事报请市里了吗？", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一份材料，报请局长同意。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有报请就做，是不对的。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办这个活动，需要报请上面同意。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报请了", "label": "体标（了）"}, {"form": "报请过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "写下来，请上面的人同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报请", "is_correct": true, "explanation": "正确。「报请」指写成书面材料请上级同意，与「写成文件」「同意」相合。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：「朗读」的对象是文字，不能说「朗读上级同意」。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：「撕毁」是把文件毁掉，与「写成文件，……同意」要的批准方向相反。"}, {"text": "叹气", "is_correct": false, "explanation": "配价：「叹气」是不及物动词，后面不能带「上级同意」这样的宾语。"}], "explanations": {"报请": "正确。「报请」指写成书面材料请上级同意，与「写成文件」「同意」相合。", "朗读": "搭配：「朗读」的对象是文字，不能说「朗读上级同意」。", "撕毁": "语义：「撕毁」是把文件毁掉，与「写成文件，……同意」要的批准方向相反。", "叹气": "配价：「叹气」是不及物动词，后面不能带「上级同意」这样的宾语。"}, "sentence_index": 0, "correct_answer": "报请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我报请朋友帮我搬家。", "explanation": "这里应该用〈请求〉。报请只用于向上级报告并请求批准，对朋友的一般请求要用请求。"}, {"text": "我向老师报请了数学难题。", "explanation": "这里应该用〈请教〉。报请是请上级批准某事，向老师问问题、求指点要用请教。"}, {"text": "我向老师报请了考试成绩。", "explanation": "这里应该用〈报告〉。报请要请上级批准，只陈述情况或结果时用报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报请", "is_correct": true, "explanation": "正确。「修路的事报请市里」指把修路的事向市里请示批准，符合句子语境。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」的对象是建筑、设施，不能说「修路的事拆除市里」。"}, {"text": "逃跑", "is_correct": false, "explanation": "配价：「逃跑」是不及物动词，后面不能带「市里」作宾语，也不能引出请示的对象。"}, {"text": "冲洗", "is_correct": false, "explanation": "语义：「冲洗」指用水冲洁或洗印照片，与修路的事和市里的关系无关，句子读不通。"}], "explanations": {"报请": "正确。「修路的事报请市里」指把修路的事向市里请示批准，符合句子语境。", "拆除": "搭配：「拆除」的对象是建筑、设施，不能说「修路的事拆除市里」。", "逃跑": "配价：「逃跑」是不及物动词，后面不能带「市里」作宾语，也不能引出请示的对象。", "冲洗": "语义：「冲洗」指用水冲洁或洗印照片，与修路的事和市里的关系无关，句子读不通。"}, "sentence_index": 6, "correct_answer": "报请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报请大家明天开会。", "explanation": "这里应该用〈通知〉。报请是向上级请求批准，不能用来告诉大家某件事。"}, {"text": "他向税务局报请了个人收入。", "explanation": "这里应该用〈申报〉。申报是向有关部门报告并登记，不需要上级批准；报请是请上级批准某事。"}, {"text": "他在会上报请了自己的看法。", "explanation": "这里应该用〈陈述〉。报请的内容必须是需要批准的事项，只表达自己的看法时用陈述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把方案报请给领导审批。", "corrected_sentence": "我们把方案报请领导审批。", "error_description": "错误：「报请给领导」。「报请」后面直接接请示的对象，不加介词「给」；应说「报请领导审批」。加了「给」会让句子读成把方案交给领导，不再是请领导批准。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事已经把报请局长批准了。", "corrected_sentence": "这件事已经报请局长批准了。", "error_description": "错误：「把报请局长」。「把」后面要接被处置的对象，不能直接接动词「报请」；这句的对象「这件事」已经在句首，应删去「把」，说「这件事已经报请局长批准了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
