INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向上级报告并请求批准。", "primary_collocate": null, "pronunciation": "bào qǐng", "ipa": "pɑʊ˥˩ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "工作人员报请上级批准了这个计划。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府将方案报请省政府批准。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工程已报请上级部门批准。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把这件事报请总公司批准。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报请批准以前，不能开工。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司报请过两次，上级都没有同意。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校报请教育局批准，开办了新班。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经报请上级，等着批准。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里把修桥的事报请县里批准。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告要先报请领导批准，再公布。", "target_word": "报请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报请了", "label": "体标（了）"}, {"form": "报请过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "向上级报告并请求批准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报请", "is_correct": true, "explanation": "正确。「报请」指向上级报告并请求批准，与「批准了这个计划」相合。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，后面不能带「上级」作宾语，句子不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：「打碎」的对象是易碎的物体，不能说「打碎上级批准了这个计划」。"}, {"text": "挂断", "is_correct": false, "explanation": "语义：「挂断」指结束通话，与「批准这个计划」没有关系。"}], "explanations": {"报请": "正确。「报请」指向上级报告并请求批准，与「批准了这个计划」相合。", "散步": "配价：「散步」是不及物动词，后面不能带「上级」作宾语，句子不通。", "打碎": "搭配：「打碎」的对象是易碎的物体，不能说「打碎上级批准了这个计划」。", "挂断": "语义：「挂断」指结束通话，与「批准这个计划」没有关系。"}, "sentence_index": 0, "correct_answer": "报请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周向经理报请工作进展。", "explanation": "这里应该用〈汇报〉。报请要请上级批准，只陈述工作进展时用汇报。"}, {"text": "我把结果报请了朋友。", "explanation": "这里应该用〈告诉〉。报请是对上级请求批准，告诉朋友消息要用告诉。"}, {"text": "他向大家报请了旅行的经历。", "explanation": "这里应该用〈讲述〉。报请针对需要批准的事项，讲述经历要用讲述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报请", "is_correct": true, "explanation": "正确。「学校报请教育局批准」指学校向上级请示批准，与「开办了新班」相合。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：「挂号」指在医院登记看病，与教育局批准开办新班的事情不相关。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：「修剪」的对象是花草、树枝，不能说「修剪教育局批准」。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：「微笑」是不及物动词，后面不能带「教育局」作宾语，句子不通。"}], "explanations": {"报请": "正确。「学校报请教育局批准」指学校向上级请示批准，与「开办了新班」相合。", "挂号": "语义：「挂号」指在医院登记看病，与教育局批准开办新班的事情不相关。", "修剪": "搭配：「修剪」的对象是花草、树枝，不能说「修剪教育局批准」。", "微笑": "配价：「微笑」是不及物动词，后面不能带「教育局」作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "报请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "企业每年都要向税务局报请利润。", "explanation": "这里应该用〈申报〉。报请要请上级批准，利润要向税务局申报登记，不需要批准。"}, {"text": "他在法庭上报请了事实经过。", "explanation": "这里应该用〈陈述〉。报请针对需要批准的事项，在法庭上陈述事实要用陈述。"}, {"text": "我报请朋友原谅我。", "explanation": "这里应该用〈请求〉。报请是向上级请求批准，请朋友原谅要用请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作人员把计划报请给上级批准。", "corrected_sentence": "工作人员把计划报请上级批准。", "error_description": "错误：「报请给上级」。「报请」后直接接上级，不加介词「给」；应说「报请上级批准」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥已经把报请市里批准了。", "corrected_sentence": "这座桥已经报请市里批准了。", "error_description": "错误：「把报请市里」。「把」后面要接被处置的对象，不能直接接动词「报请」；「这座桥」已在句首作话题，应删去「把」，说「这座桥已经报请市里批准了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
