INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理员是看着一个地方，管着东西的人。", "primary_collocate": null, "pronunciation": "guǎn lǐ yuán", "ipa": "kuan˨˩ li˨˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "图书馆的管理员正在整理书。", "target_word": "管理员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宿舍管理员每天晚上十点锁门。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙交给了管理员。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库的管理员很认真，东西都放得很整齐。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园管理员告诉我们这里不能喂鱼。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员看了看我的学生证，让我进去了。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池的管理员在门口检查大家的票。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小区当管理员已经三年了。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位管理员每天早上先打开所有的门。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员说球场晚上不开放。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "图书馆管理员", "label": "复合"}], "register": "中性", "sense_fingerprint": "看管某个场所或物品的人，如图书馆、宿舍、仓库的管理员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "搭配：“整理书”的主体应是人，钢琴不能整理书。"}, {"text": "管理员", "is_correct": true, "explanation": "正确：管理员是看管图书馆的人，能够整理书，与句意相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不是图书馆的工作人员，与“图书馆的”场所不合。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不能整理书，与“正在整理书”的动作不合。"}], "explanations": {"钢琴": "搭配：“整理书”的主体应是人，钢琴不能整理书。", "管理员": "正确：管理员是看管图书馆的人，能够整理书，与句意相符。", "乘客": "语义：乘客不是图书馆的工作人员，与“图书馆的”场所不合。", "树木": "语义：树木不能整理书，与“正在整理书”的动作不合。"}, "sentence_index": 0, "correct_answer": "管理员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个管理员有三层楼，里面堆满了货。", "explanation": "这里应该用〈仓库〉。管理员指看管场所或物品的人，不能指有楼层、堆满货物的建筑。"}, {"text": "这家饭店的管理员端来了我们点的菜。", "explanation": "这里应该用〈服务员〉。管理员负责看管场所或物品，不负责端菜。"}, {"text": "我们学校新来了一台管理员。", "explanation": "这里应该用〈位〉或〈个〉。〈台〉用于机器，指人时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是人，不能在门口检查大家的票。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“检查票”的主体应是人，冰箱不能与之搭配。"}, {"text": "餐具", "is_correct": false, "explanation": "语义：餐具不能在门口检查票，与游泳池的场景不合。"}, {"text": "管理员", "is_correct": true, "explanation": "正确：游泳池的管理员在门口检查票，与句意相符。"}], "explanations": {"鱼": "语义：鱼不是人，不能在门口检查大家的票。", "冰箱": "搭配：“检查票”的主体应是人，冰箱不能与之搭配。", "餐具": "语义：餐具不能在门口检查票，与游泳池的场景不合。", "管理员": "正确：游泳池的管理员在门口检查票，与句意相符。"}, "sentence_index": 6, "correct_answer": "管理员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个管理员很好吃，大家都吃了一个。", "explanation": "这里把“管理员”当作食物，但它指看管场所或物品的人，不能吃，也不能说“好吃”。"}, {"text": "我用管理员打开了那扇门。", "explanation": "这里把“管理员”当作工具，但它指人，不能用来开门。"}, {"text": "他把管理员擦得很干净。", "explanation": "这里把“管理员”当作可以擦洗的物体，但它指人，不能被擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天认识了一只管理员。", "corrected_sentence": "我昨天认识了一位管理员。", "error_description": "量词错误：“只”多用于动物，指人的“管理员”应用量词“位”，说“一位管理员”，不说“一只管理员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在图书馆管理员。", "corrected_sentence": "他在图书馆当管理员。", "error_description": "“管理员”作宾语表示身份时，前面要加动词“当”，应说“当管理员”；“在图书馆管理员”少了“当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
