INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责管理某项事务、某个系统或网络群组的人员。", "primary_collocate": null, "pronunciation": "guǎn lǐ yuán", "ipa": "kuan˨˩ li˨˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "我是这个微信群的管理员。", "target_word": "管理员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站管理员删除了那条广告。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找公司的网络管理员帮忙。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统管理员给每个人开了新账号。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当学校的档案管理员。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员把会议室的安排发给了大家。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群里有人乱发广告，管理员马上提醒了他。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，要先问问管理员。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个论坛的管理员很年轻。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的管理员每天检查新发的文章。", "target_word": "管理员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "系统管理员", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责某项事务或系统的管理人员，如群、网站、网络的管理员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是群的管理者，“微信群的饺子”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能指群的负责人，与句意不合。"}, {"text": "管理员", "is_correct": true, "explanation": "正确：管理员指负责管理微信群的人，与“我是这个微信群的……”相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“微信群”没有实体钥匙，“我是这个微信群的钥匙”不能成立。"}], "explanations": {"饺子": "语义：饺子是食物，不是群的管理者，“微信群的饺子”说不通。", "手机": "语义：手机是通讯工具，不能指群的负责人，与句意不合。", "管理员": "正确：管理员指负责管理微信群的人，与“我是这个微信群的……”相符。", "钥匙": "搭配：“微信群”没有实体钥匙，“我是这个微信群的钥匙”不能成立。"}, "sentence_index": 0, "correct_answer": "管理员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的管理员写得很精彩。", "explanation": "这里应该用〈作者〉。管理员负责管理事务或场所，不负责写作。"}, {"text": "管理员飞上了太空，还拍了很多照片。", "explanation": "这里应该用〈宇航员〉。管理员指负责管理事务或场所的人，不是飞上太空的人。"}, {"text": "公司新来了一辆管理员。", "explanation": "这里应该用〈位〉或〈个〉。〈辆〉用于车辆，指人时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "语义：电视不能主动提醒人，“电视马上提醒了他”说不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能在群里提醒人，与群聊的场景不合。"}, {"text": "管理员", "is_correct": true, "explanation": "正确：管理员负责管理群，可以提醒违规发广告的人，与句意相符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“提醒”的主体应是能说话的人或系统，面包不能与之搭配。"}], "explanations": {"电视": "语义：电视不能主动提醒人，“电视马上提醒了他”说不通。", "小猫": "语义：小猫不能在群里提醒人，与群聊的场景不合。", "管理员": "正确：管理员负责管理群，可以提醒违规发广告的人，与句意相符。", "面包": "搭配：“提醒”的主体应是能说话的人或系统，面包不能与之搭配。"}, "sentence_index": 6, "correct_answer": "管理员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块管理员很甜，我想再尝一口。", "explanation": "这里把“管理员”当作食物，但它指负责事务或系统的人员，不能品尝。"}, {"text": "我用管理员把饭菜煮好了。", "explanation": "这里把“管理员”当作炊具或工具，但它指人，不能用来煮饭。"}, {"text": "我每天给管理员浇水，它长得很好。", "explanation": "这里把“管理员”当作植物，但它指人，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的身份微信群管理员。", "corrected_sentence": "我的身份是微信群管理员。", "error_description": "“身份”后作判断的名词谓语时需要“是”，应说“我的身份是微信群管理员”；这里缺少“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有问题可以找一只管理员。", "corrected_sentence": "有问题可以找一位管理员。", "error_description": "量词错误：“只”多用于动物，指人的“管理员”应用量词“位”，说“找一位管理员”，不说“找一只管理员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
