INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88965, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "共和国是国家的一种，国家的大事由大家选出来的人来管。", "primary_collocate": null, "pronunciation": "gòng hé guó", "ipa": "kʊŋ˥˩ xɤ˧˥ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "共和国是国家的一种。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共和国的大事，大家选人来管。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的国家是共和国，有的不是。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是共和国。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共和国没有国王，人民选出领导人。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这个国家是共和国。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共和国和王国不一样。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解共和国是怎么管理的。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都是共和国。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书详细介绍了共和国的制度。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共和國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家的一种，大事由选出的人管理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "语义：公司是经济组织，不是一种国家，“是国家的一种”说不通。"}, {"text": "共和国", "is_correct": true, "explanation": "正确：共和国是国家的一种，句子给出的定义正是这个词。"}, {"text": "民族", "is_correct": false, "explanation": "搭配：“是国家的一种”要接国家类型，民族指人群共同体，不能这样接。"}, {"text": "联合国", "is_correct": false, "explanation": "语义：联合国是国际组织，不是国家，不能说它是国家的一种。"}], "explanations": {"公司": "语义：公司是经济组织，不是一种国家，“是国家的一种”说不通。", "共和国": "正确：共和国是国家的一种，句子给出的定义正是这个词。", "民族": "搭配：“是国家的一种”要接国家类型，民族指人群共同体，不能这样接。", "联合国": "语义：联合国是国际组织，不是国家，不能说它是国家的一种。"}, "sentence_index": 0, "correct_answer": "共和国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我梦想当这个共和国的国王。", "explanation": "这里应该用〈王国〉。共和国没有国王，由国王统治的国家要说王国。"}, {"text": "法国实行共和国，人民选举总统。", "explanation": "这里应该用〈共和制〉。“实行”后面接制度，共和国是国家，不能说“实行共和国”。"}, {"text": "我们这只共和国有三亿人口。", "explanation": "这里应该用〈个〉。共和国是国家，量词用“个”，“只”多用于动物等，不用于国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "王国", "is_correct": false, "explanation": "语义：“王国和王国不一样”不成立，两者是同一个词。"}, {"text": "共和国", "is_correct": true, "explanation": "正确：共和国与王国是两种不同的国家类型，句子意思成立。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能作“和王国不一样”的主语。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能作“和王国不一样”的主语。"}], "explanations": {"王国": "语义：“王国和王国不一样”不成立，两者是同一个词。", "共和国": "正确：共和国与王国是两种不同的国家类型，句子意思成立。", "非常": "语法：“非常”是副词，不能作“和王国不一样”的主语。", "因为": "语法：“因为”是连词，不能作“和王国不一样”的主语。"}, "sentence_index": 6, "correct_answer": "共和国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "共和国的权力掌握在国王手中。", "explanation": "这里应该用〈君主国〉。共和国的权力机关由选举产生，国王掌权的国家要说君主国。"}, {"text": "这把共和国的历史很长。", "explanation": "这里应该用〈个〉。共和国是国家，不能用“把”，“把”多用于有柄的器具。"}, {"text": "美国的政治制度是共和国，各州有很大的自主权。", "explanation": "这里应该用〈联邦制〉。“政治制度”后面接制度名称，共和国是国家，不能说“制度是共和国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "美国是一本共和国，首都是华盛顿。", "corrected_sentence": "美国是一个共和国，首都是华盛顿。", "error_description": "错误在量词：“共和国”是国家，应用量词“个”，写成“本”是错误的，“本”只用于书等物品。正确形式为“一个共和国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所共和国的首都很美丽。", "corrected_sentence": "这个共和国的首都很美丽。", "error_description": "错误在量词：“所”用于学校、医院、房屋等机构或建筑，“共和国”是国家，应用量词“个”。正确形式为“这个共和国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
