INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88967, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大爷是对年纪大的男人的尊称，也指爸爸的哥哥。", "primary_collocate": null, "pronunciation": "dà ye", "ipa": "ta˥˩ jɛ", "syllable_count": 2, "sentences": [{"text": "公园里有位大爷在打太极拳。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大爷，请问去地铁站怎么走？", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我大爷是我爸爸的哥哥。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我去大爷家吃饭。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大爷每天早上都在河边钓鱼。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大爷拎着菜篮子，慢慢走回家。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位大爷把捡到的钱包交给了警察。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我大爷比我爸爸大五岁。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口的大爷帮我看着自行车。", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大爷笑着说：“年轻人，慢点儿走。”", "target_word": "大爷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "大爷们", "label": "复数"}], "register": "口语", "sense_fingerprint": "尊称年长男子；爸爸的哥哥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大爷", "is_correct": true, "explanation": "正确。大爷（dà ye），尊称年长的男子，也指爸爸的哥哥。"}, {"text": "大衣", "is_correct": false, "explanation": "dàyī 与 dàye 的韵母不同（yī 与 ye），意思是外套。"}, {"text": "大叶", "is_correct": false, "explanation": "dàyè 与 dàye 的声调不同（第四声与轻声），意思是大的叶子。"}, {"text": "大牙", "is_correct": false, "explanation": "dàyá 与 dàye 的韵母不同（yá 与 ye），意思是臼齿。"}], "explanations": {"大爷": "正确。大爷（dà ye），尊称年长的男子，也指爸爸的哥哥。", "大衣": "dàyī 与 dàye 的韵母不同（yī 与 ye），意思是外套。", "大叶": "dàyè 与 dàye 的声调不同（第四声与轻声），意思是大的叶子。", "大牙": "dàyá 与 dàye 的韵母不同（yá 与 ye），意思是臼齿。"}, "sentence_index": null, "correct_answer": "大爷"}, "level_3": {"options": [{"text": "大爷", "is_correct": true, "explanation": "正确。“有位”之后要用指年长男子的名词，“大爷”符合句意。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“老虎”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能打太极拳，与句中的动作矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，也不能打太极拳。"}], "explanations": {"大爷": "正确。“有位”之后要用指年长男子的名词，“大爷”符合句意。", "老虎": "搭配：量词“位”只用于人，不能修饰“老虎”。", "石头": "语义：石头不能打太极拳，与句中的动作矛盾。", "窗户": "语义：窗户不是人，也不能打太极拳。"}, "sentence_index": 0, "correct_answer": "大爷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在公司门口遇见一位大爷，他刚二十出头。", "explanation": "这里应该用〈小伙子〉。“大爷”指年长的男子，二十出头的年轻男子应说“小伙子”。"}, {"text": "我大爷是我爸爸的妹妹。", "explanation": "这里应该用〈姑姑〉。“大爷”指爸爸的哥哥，是男性；爸爸的妹妹应说“姑姑”。"}, {"text": "我大爷是我妈妈的妹妹。", "explanation": "这里应该用〈小姨〉。“大爷”指爸爸的哥哥，是男性；妈妈的妹妹应说“小姨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88967, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大爷", "is_correct": true, "explanation": "正确。大爷（dà ye），尊称年长的男子，也指爸爸的哥哥。"}, {"text": "大意", "is_correct": false, "explanation": "dàyì 与 dàye 的韵母不同（yì 与 ye），意思是疏忽。"}, {"text": "大鱼", "is_correct": false, "explanation": "dàyú 与 dàye 的韵母不同（yú 与 ye），意思是大鱼。"}, {"text": "大业", "is_correct": false, "explanation": "dàyè 与 dàye 的声调不同（第四声与轻声），意思是伟大的事业。"}], "explanations": {"大爷": "正确。大爷（dà ye），尊称年长的男子，也指爸爸的哥哥。", "大意": "dàyì 与 dàye 的韵母不同（yì 与 ye），意思是疏忽。", "大鱼": "dàyú 与 dàye 的韵母不同（yú 与 ye），意思是大鱼。", "大业": "dàyè 与 dàye 的声调不同（第四声与轻声），意思是伟大的事业。"}, "sentence_index": null, "correct_answer": "大爷"}, "level_3": {"options": [{"text": "大爷", "is_correct": true, "explanation": "正确。“一位”指人，“大爷”指年长男子，能够捡到并交出钱包。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“桌子”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会捡东西，也不能把钱包交给警察。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会捡东西，也不能把钱包交给警察。"}], "explanations": {"大爷": "正确。“一位”指人，“大爷”指年长男子，能够捡到并交出钱包。", "桌子": "搭配：量词“位”只用于人，不能修饰“桌子”。", "椅子": "语义：椅子不会捡东西，也不能把钱包交给警察。", "树": "语义：树不会捡东西，也不能把钱包交给警察。"}, "sentence_index": 6, "correct_answer": "大爷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大爷比我爸爸小三岁。", "explanation": "这里应该用〈小叔〉。“大爷”指爸爸的哥哥，比爸爸年长，不能比爸爸小。"}, {"text": "我大爷是我的同班同学，我们每天一起上学。", "explanation": "这里应该用〈同学〉。“大爷”指年长男子或伯父，同班同学应说“同学”，不能用“大爷”。"}, {"text": "我家的大爷很可爱，每天都吃奶。", "explanation": "这里应该用〈婴儿〉。“大爷”指年长的男子，不能指每天吃奶的婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里有一位大爷们在下棋。", "corrected_sentence": "公园里有一位大爷在下棋。", "error_description": "复数错误：“一位”已表示数量，“大爷”后不能再加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一大爷把钱包交给了警察。", "corrected_sentence": "一位大爷把钱包交给了警察。", "error_description": "量词缺失：“大爷”指人，前面的数词“一”要配量词“位”，不能直接说“一大爷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
