INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "米制是用米、千克来量东西的一种办法。", "primary_collocate": null, "pronunciation": "mǐ zhì", "ipa": "mi˨˩˦ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家用米制，路牌上写的是公里。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国人常用英制，我们习惯米制。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用米制来量，这张桌子长两米。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么用米制量东西。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的尺子是按米制做的。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从英国来，还不习惯米制。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买菜时我们用米制，一千克多少钱？", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书用米制介绍各种东西的大小。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用米制来说，这条路长五公里。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会换算米制和英制？", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "米制单位", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常量东西时用米、千克的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：用米、千克来量东西的一种办法。"}, {"text": "米市", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。"}, {"text": "蜜制", "is_correct": false, "explanation": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。"}, {"text": "米纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。"}, {"text": "理智", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}], "explanations": {"米制": "米制：用米、千克来量东西的一种办法。", "米市": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。", "蜜制": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。", "米纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。", "理智": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“这个国家用米制”，路牌写公里，两者相合。"}, {"text": "英制", "is_correct": false, "explanation": "语义：“英制”用英里、英尺、磅等单位，与后面“路牌上写的是公里”矛盾。"}, {"text": "英里", "is_correct": false, "explanation": "语义：“英里”是英制的长度单位，用英里的国家路牌不会写“公里”，与后半句矛盾。"}, {"text": "英尺", "is_correct": false, "explanation": "语义：“英尺”是英制的长度单位，路牌上写“公里”说明这个国家用的不是英尺。"}], "explanations": {"米制": "正确：“这个国家用米制”，路牌写公里，两者相合。", "英制": "语义：“英制”用英里、英尺、磅等单位，与后面“路牌上写的是公里”矛盾。", "英里": "语义：“英里”是英制的长度单位，用英里的国家路牌不会写“公里”，与后半句矛盾。", "英尺": "语义：“英尺”是英制的长度单位，路牌上写“公里”说明这个国家用的不是英尺。"}, "sentence_index": 0, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种米制很香，我每天都买。", "explanation": "这里的“米制”是“大米”的意思，不是度量衡制度；指大米要说〈大米〉，“米制”不能指大米。"}, {"text": "妈妈在厨房里用米制煮饭。", "explanation": "这里的“米制”不是度量办法，是“米”的意思；煮饭说的“米”不能用“米制”。"}, {"text": "老师教我们怎么用米制做饭。", "explanation": "“米制”指度量衡办法，不能用来做饭，这个搭配不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88969, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：用米、千克来量东西的一种办法。"}, {"text": "美制", "is_correct": false, "explanation": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。"}, {"text": "礼制", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}], "explanations": {"米制": "米制：用米、千克来量东西的一种办法。", "美制": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。", "体制": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。", "礼制": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“买菜时我们用米制”，与后面的“一千克多少钱”相合。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：“公里”是长度单位，买菜不用它计量，与“一千克”不搭。"}, {"text": "英寸", "is_correct": false, "explanation": "搭配：“英寸”是长度单位，买菜不用它计量，句中的“一千克”也对不上。"}, {"text": "英制", "is_correct": false, "explanation": "语义：“英制”是英尺、磅等单位体系，英国、美国使用，买菜时不会这样用，与“一千克”也对不上。"}], "explanations": {"米制": "正确：“买菜时我们用米制”，与后面的“一千克多少钱”相合。", "公里": "搭配：“公里”是长度单位，买菜不用它计量，与“一千克”不搭。", "英寸": "搭配：“英寸”是长度单位，买菜不用它计量，句中的“一千克”也对不上。", "英制": "语义：“英制”是英尺、磅等单位体系，英国、美国使用，买菜时不会这样用，与“一千克”也对不上。"}, "sentence_index": 6, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用公斤这个单位称东西，而不是用米制这个单位称东西。", "explanation": "这里的“米制”指整个度量制度，不是单个单位，不能说“这个单位”。"}, {"text": "我们用厘米这个单位量身高，也可以用米制这个单位量身高。", "explanation": "这里的“米制”指整个度量制度，不是单个单位，不能说“这个单位”。"}, {"text": "我们用英寸这个单位量布，不用米制这个单位量布。", "explanation": "这里的“米制”指整个度量制度，不是单个单位，不能说“这个单位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用一把米制量长度。", "corrected_sentence": "我们用米制量长度。", "error_description": "量词错误：“米制”是一种度量办法，不是东西，前面不能加“一把”（“把”用于有柄的器具）。应删去“一把”，说“我们用米制量长度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在学校里米制量布料。", "corrected_sentence": "我们在学校里用米制量布料。", "error_description": "动词缺失：“米制”后面要有动词“用”，应说“用米制量布料”，不能省略“用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
