INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以米为长度基本单位、千克为质量基本单位的度量衡制度。", "primary_collocate": null, "pronunciation": "mǐ zhì", "ipa": "mi˨˩˦ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "米制是一种以米和千克为基础的度量衡制度。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制最早是在法国开始使用的。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多国家都实行米制。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制的长度单位是米。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制的质量单位是千克。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家都用米制做实验。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制让各国的计量更容易统一。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了米制的历史。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制比英制更容易换算。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制在世界上用得很广。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "米制单位", "label": "复合"}], "register": "中性", "sense_fingerprint": "以米和千克为基本单位的度量衡制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：以米和千克为基本单位的度量衡制度。"}, {"text": "米市", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。"}, {"text": "蜜制", "is_correct": false, "explanation": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。"}, {"text": "米纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。"}, {"text": "理智", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}], "explanations": {"米制": "米制：以米和千克为基本单位的度量衡制度。", "米市": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。", "蜜制": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。", "米纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。", "理智": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“米制是一种以米和千克为基础的度量衡制度”。"}, {"text": "英制", "is_correct": false, "explanation": "语义：“英制”以英尺、磅为基础，与句中“以米和千克为基础”不符。"}, {"text": "市制", "is_correct": false, "explanation": "语义：“市制”以尺、斤为基础，与句中“以米和千克为基础”矛盾。"}, {"text": "英里", "is_correct": false, "explanation": "搭配：“英里”是一个长度单位，不是度量衡制度，不能作主语。"}], "explanations": {"米制": "正确：“米制是一种以米和千克为基础的度量衡制度”。", "英制": "语义：“英制”以英尺、磅为基础，与句中“以米和千克为基础”不符。", "市制": "语义：“市制”以尺、斤为基础，与句中“以米和千克为基础”矛盾。", "英里": "搭配：“英里”是一个长度单位，不是度量衡制度，不能作主语。"}, "sentence_index": 0, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈去超市买了两斤米制。", "explanation": "这里的“米制”不是度量衡制度，不能买；买大米要说〈大米〉。"}, {"text": "奶奶每天用米制熬粥。", "explanation": "这里的“米制”不是度量衡制度，是“大米”的意思，熬粥说的“米”不能用“米制”。"}, {"text": "我们班买了一包米制，放在讲台上。", "explanation": "这里的“米制”不是度量衡制度，是大米的意思；装在包里的大米要说〈大米〉，“米制”不能指大米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：以米和千克为基本单位的度量衡制度。"}, {"text": "美制", "is_correct": false, "explanation": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。"}, {"text": "礼制", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}], "explanations": {"米制": "米制：以米和千克为基本单位的度量衡制度。", "美制": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。", "体制": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。", "礼制": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“米制让各国的计量更容易统一”，主语是度量衡制度。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是度量制度，不能让计量统一。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，与计量统一无关。"}, {"text": "英寸", "is_correct": false, "explanation": "搭配：“英寸”是长度单位，不是能让计量统一的制度。"}], "explanations": {"米制": "正确：“米制让各国的计量更容易统一”，主语是度量衡制度。", "天气": "语义：“天气”不是度量制度，不能让计量统一。", "桌子": "语义：“桌子”是家具，与计量统一无关。", "英寸": "搭配：“英寸”是长度单位，不是能让计量统一的制度。"}, "sentence_index": 6, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "米制是质量的基本单位。", "explanation": "这里应该用〈千克〉。“米制”是整个度量衡制度，不是单个质量单位。"}, {"text": "我们用米制这个单位称鸡蛋。", "explanation": "这里应该用〈克〉作单位。“米制”不能当作单个单位使用。"}, {"text": "我们用米制这个单位量布料。", "explanation": "这里应该用〈米〉作单位。“米制”是度量办法，不是长度单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "许多国家都在用一把米制。", "corrected_sentence": "许多国家都在用米制。", "error_description": "量词错误：“米制”是度量衡制度，不能用“把”（“把”用于有柄的器具），应直接说“用米制”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把米制，大家都在用。", "corrected_sentence": "这里用的是米制，大家都在用。", "error_description": "量词错误：“米制”是度量衡制度，不能用“把”（“把”用于有柄的器具），“米制”前一般不加量词，应说“用的是米制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本", "is_correct": true, "explanation": "反义词：“利”指本金之外多出的钱，与“本”（本钱）相对，如“本利”。"}, {"text": "桌子", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}, {"text": "书包", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}, {"text": "花", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}], "correct_answer": "本", "explanations": {"本": "反义词：“利”指本金之外多出的钱，与“本”（本钱）相对，如“本利”。", "桌子": "与“利”没有反义关系，二者不构成相对的概念。", "书包": "与“利”没有反义关系，二者不构成相对的概念。", "花": "与“利”没有反义关系，二者不构成相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本", "is_correct": true, "explanation": "反义词：“利”指本金之外多出的钱，与“本”（本钱）相对，如“本利”。"}, {"text": "椅子", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}, {"text": "瓶子", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}, {"text": "地图", "is_correct": false, "explanation": "与“利”没有反义关系，二者不构成相对的概念。"}], "correct_answer": "本", "explanations": {"本": "反义词：“利”指本金之外多出的钱，与“本”（本钱）相对，如“本利”。", "椅子": "与“利”没有反义关系，二者不构成相对的概念。", "瓶子": "与“利”没有反义关系，二者不构成相对的概念。", "地图": "与“利”没有反义关系，二者不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利是做一件事后得到的好处或者多出来的钱。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "借钱要还本，也要还利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借出去的钱，一年后拿回本和利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只想要回本钱，不想要利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利滚利，欠的钱会越来越多。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意有本有利，才能做下去。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖做完，本和利都分给大家。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行每年给存款付的利，比我想的少。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一年本钱没少，还多了一点利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把本和利都存进了银行。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱放在银行里，一年后会多出一点利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "利息", "label": "复合"}, {"form": "利润", "label": "复合"}], "register": "书面", "sense_fingerprint": "做事后多出来的钱，与本钱相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利", "is_correct": true, "explanation": "正确答案。“利”读 lì（第四声），指做事后得到的好处或多出来的钱。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是里面。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是道理。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì 声调不同，意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是礼物。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同，意思是逆向。"}], "explanations": {"利": "正确答案。“利”读 lì（第四声），指做事后得到的好处或多出来的钱。", "里": "lǐ（第三声）与 lì（第四声）声调不同，意思是里面。", "理": "lǐ（第三声）与 lì 声调不同，意思是道理。", "离": "lí（第二声）与 lì 声调不同，意思是离开。", "礼": "lǐ（第三声）与 lì 声调不同，意思是礼物。", "逆": "nì（第四声）与 lì 声母不同，意思是逆向。"}, "sentence_index": null, "correct_answer": "利"}, "level_3": {"options": [{"text": "利", "is_correct": true, "explanation": "正确。“利”指还钱之外多出的部分，与“本”相对，符合句意。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”已在前句出现，“也要还本”重复，句意不清。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“还”后面接的是借来的东西，“树”不能被归还。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“还”不能与“雨”搭配，雨不是借来的东西。"}], "explanations": {"利": "正确。“利”指还钱之外多出的部分，与“本”相对，符合句意。", "本": "语义：“本”已在前句出现，“也要还本”重复，句意不清。", "树": "搭配：“还”后面接的是借来的东西，“树”不能被归还。", "雨": "搭配：“还”不能与“雨”搭配，雨不是借来的东西。"}, "sentence_index": 0, "correct_answer": "利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔存款一年后多出了一把利。", "explanation": "这里应该用〈笔〉。“利”指钱款，量词要用“笔”；“把”用于刀、椅等有柄或有座的物件，不能用于钱款。"}, {"text": "他向银行借了三万元的利。", "explanation": "这里应该用〈本金〉。借入的是本金，“利”指本金之外多出的钱，不能说借利。"}, {"text": "这件事对大家很有利。", "explanation": "“有利”在此指好处，是“利”的另一义项，与本题所教的利息或利润义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利", "is_correct": true, "explanation": "正确答案。“利”读 lì（第四声），指做事后得到的好处或多出来的钱。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是礼物。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lì 声调不同，意思是梨子。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同，意思是油腻。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是里面。"}], "explanations": {"利": "正确答案。“利”读 lì（第四声），指做事后得到的好处或多出来的钱。", "礼": "lǐ（第三声）与 lì 声调不同，意思是礼物。", "梨": "lí（第二声）与 lì 声调不同，意思是梨子。", "腻": "nì（第四声）与 lì 声母不同，意思是油腻。", "里": "lǐ（第三声）与 lì 声调不同，意思是里面。"}, "sentence_index": null, "correct_answer": "利"}, "level_3": {"options": [{"text": "利", "is_correct": true, "explanation": "正确。“利”指银行付给存款的钱，符合句意。"}, {"text": "税", "is_correct": false, "explanation": "语义：税是缴给政府的，银行不会付税给存款人，句意不合。"}, {"text": "票", "is_correct": false, "explanation": "搭配：“付”后面接的是钱款，不能接“票”。"}, {"text": "草", "is_correct": false, "explanation": "语义：“草”与金钱无关，句子讲存款的收益，不合。"}], "explanations": {"利": "正确。“利”指银行付给存款的钱，符合句意。", "税": "语义：税是缴给政府的，银行不会付税给存款人，句意不合。", "票": "搭配：“付”后面接的是钱款，不能接“票”。", "草": "语义：“草”与金钱无关，句子讲存款的收益，不合。"}, "sentence_index": 6, "correct_answer": "利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔存款一年后多出了一颗利。", "explanation": "这里应该用〈笔〉。“利”指钱款，量词要用“笔”；“颗”用于粒状的小东西，不能用于钱款。"}, {"text": "这次投资让他蒙受了很大的利。", "explanation": "这里应该用〈损失〉。“蒙受”后接的是损失，“利”指好处或钱款的增加，不能说“蒙受利”。"}, {"text": "他的刀很利。", "explanation": "“利”在此指锋利，是同形异义词，与本题所教的钱款义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔存款一年后多出了一个利。", "corrected_sentence": "这笔存款一年后多出了一点利。", "error_description": "量词错误：“利”不可数，要说“一点利”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱一年后会出多一点利。", "corrected_sentence": "这笔钱一年后会多出一点利。", "error_description": "补语顺序错误：“多出”是动词加结果补语，不能颠倒成“出多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
