INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好处；利益；利润。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "这个办法利大于弊，我们可以试试。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事利少弊多，我们别做了。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不为名，也不为利，只想帮帮大家。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃夜宵利少弊多，对身体不好。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定前，先想想是利还是弊。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划利多弊少，大家都同意。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看眼前的利，要看长远的好处。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眼里只有利，没有朋友。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名和利，他都不要。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做这件事，不是为了自己的利。", "target_word": "利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "利益", "label": "复合"}, {"form": "利润", "label": "复合"}], "register": "书面", "sense_fingerprint": "好处、利益，常与弊或名相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利", "is_correct": true, "explanation": "正确答案。“利”读 lì（第四声），指好处、利益。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是礼物。"}, {"text": "李", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是李子。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同，意思是油腻。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是里面。"}], "explanations": {"利": "正确答案。“利”读 lì（第四声），指好处、利益。", "礼": "lǐ（第三声）与 lì 声调不同，意思是礼物。", "李": "lǐ（第三声）与 lì 声调不同，意思是李子。", "腻": "nì（第四声）与 lì 声母不同，意思是油腻。", "里": "lǐ（第三声）与 lì 声调不同，意思是里面。"}, "sentence_index": null, "correct_answer": "利"}, "level_3": {"options": [{"text": "利", "is_correct": true, "explanation": "正确。“利大于弊”中的“利”指好处，与“弊”相比，符合句意。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”指名声，与“弊”相比较没有道理，句意不通。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”不能与“大于弊”构成比较，句中比较的是好处与弊端。"}, {"text": "色", "is_correct": false, "explanation": "语义：“色”与“弊”没有可比性，句中要比较的是好处与坏处。"}], "explanations": {"利": "正确。“利大于弊”中的“利”指好处，与“弊”相比，符合句意。", "名": "语义：“名”指名声，与“弊”相比较没有道理，句意不通。", "本": "搭配：“本”不能与“大于弊”构成比较，句中比较的是好处与弊端。", "色": "语义：“色”与“弊”没有可比性，句中要比较的是好处与坏处。"}, "sentence_index": 0, "correct_answer": "利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革给大家带来了一张利。", "explanation": "这里应该用〈点〉。“利”指好处时量词用“点”；“张”用于纸、桌子等平面物件，不能用于好处。"}, {"text": "他的利是认真。", "explanation": "这里应该用〈长处〉。“利”指好处、利益，指人的优点要说“长处”。"}, {"text": "这次投资让他蒙受了很大的利。", "explanation": "这里应该用〈损失〉。“利”指好处，蒙受的是损失，不能说“蒙受利”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利", "is_correct": true, "explanation": "正确答案。“利”读 lì（第四声），指好处、利益。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是里面。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì 声调不同，意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì 声调不同，意思是礼物。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同，意思是逆向。"}], "explanations": {"利": "正确答案。“利”读 lì（第四声），指好处、利益。", "里": "lǐ（第三声）与 lì 声调不同，意思是里面。", "离": "lí（第二声）与 lì 声调不同，意思是离开。", "礼": "lǐ（第三声）与 lì 声调不同，意思是礼物。", "逆": "nì（第四声）与 lì 声母不同，意思是逆向。"}, "sentence_index": null, "correct_answer": "利"}, "level_3": {"options": [{"text": "利", "is_correct": true, "explanation": "正确。“眼前的利”指眼前的好处，与“长远的好处”相对，符合句意。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”与“好处”无关，“只看眼前的车”句意不通。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”与句中讲的得失无关，不能用在这里。"}, {"text": "铁", "is_correct": false, "explanation": "搭配：“看”后接“铁”不构成与“长远的好处”相对的表达。"}], "explanations": {"利": "正确。“眼前的利”指眼前的好处，与“长远的好处”相对，符合句意。", "车": "语义：“车”与“好处”无关，“只看眼前的车”句意不通。", "猫": "语义：“猫”与句中讲的得失无关，不能用在这里。", "铁": "搭配：“看”后接“铁”不构成与“长远的好处”相对的表达。"}, "sentence_index": 6, "correct_answer": "利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿出一份利送给朋友。", "explanation": "这里应该用〈礼物〉。“利”指好处或利润，不是实物，送人的东西要说“礼物”。"}, {"text": "他吃了一碗利。", "explanation": "这里应该用〈饭〉。“利”指好处、利益，是抽象的，不能吃。"}, {"text": "他每月拿到一把利。", "explanation": "这里应该用〈点〉。“利”指好处时量词用“点”；“把”用于刀、椅等有柄或有座的物件，不能用于好处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革给大家带来了一把利。", "corrected_sentence": "这次改革给大家带来了一点利。", "error_description": "量词错误：“利”指好处时要用“点”，“把”是用于有柄物件的量词，不能用于“利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这样做，不是为了别人利。", "corrected_sentence": "他这样做，不是为了别人的利。", "error_description": "漏字：“别人”和“利”之间要加“的”，应为“别人的利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶化", "is_correct": true, "explanation": "反义：“恶化”指情况变坏，与“好转”正相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指悠闲地走动，与情况的变化没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“好转”不构成反义。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”指出游，与病情、局面的变化没有反义关系。"}], "correct_answer": "恶化", "explanations": {"恶化": "反义：“恶化”指情况变坏，与“好转”正相反。", "散步": "无关：“散步”指悠闲地走动，与情况的变化没有反义关系。", "讨论": "无关：“讨论”指交换意见，与“好转”不构成反义。", "旅行": "无关：“旅行”指出游，与病情、局面的变化没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶化", "is_correct": true, "explanation": "反义：“恶化”指情况变坏，与“好转”正相反。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”是体育运动，与情况的变化没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "无关：“写作”指写文章，与“好转”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指修复器物，与“好转”不构成反义。"}], "correct_answer": "恶化", "explanations": {"恶化": "反义：“恶化”指情况变坏，与“好转”正相反。", "游泳": "无关：“游泳”是体育运动，与情况的变化没有反义关系。", "写作": "无关：“写作”指写文章，与“好转”不构成反义。", "修理": "无关：“修理”指修复器物，与“好转”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "好转是变好了，不像以前那样差了。", "primary_collocate": null, "pronunciation": "hǎo zhuǎn", "ipa": "xau˨˩˦ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "经过治疗，奶奶的病情慢慢好转了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的身体正在好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天天气好转，我们可以出去玩了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，孩子的发烧好转了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的生意最近开始好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系好转以后，大家都很高兴。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济好转，找工作也容易多了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况一直没有好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他的心情好转了不少。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气质量慢慢好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好转了", "label": "体标"}, {"form": "好转过", "label": "体标"}, {"form": "好轉", "label": "繁体"}], "register": "通用", "sense_fingerprint": "病情、情况变好了，不再像以前那样差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好转", "is_correct": true, "explanation": "好转：病情由差变好，与“经过治疗”的效果相符。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能用来说病情的变化方向。"}, {"text": "出现", "is_correct": false, "explanation": "语义：「出现」指新的情况、人或物显现，不表示病情由差变好，与「经过治疗」的效果不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是房间、地面等，不能说「病情打扫了」。"}], "explanations": {"好转": "好转：病情由差变好，与“经过治疗”的效果相符。", "增加": "搭配：“增加”说数量，不能用来说病情的变化方向。", "出现": "语义：「出现」指新的情况、人或物显现，不表示病情由差变好，与「经过治疗」的效果不符。", "打扫": "搭配：「打扫」的对象是房间、地面等，不能说「病情打扫了」。"}, "sentence_index": 0, "correct_answer": "好转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的存款好转了不少。", "explanation": "这里应该用〈增加〉。好转用于病情、局面等由差变好的状况，存款等数量的增长要用增加。"}, {"text": "这把椅子最近好转了很多。", "explanation": "这里应该用〈修好〉。椅子由坏变好是修理的结果，要说修好；好转多用于病情、局面、关系等状况，不用于具体物件。"}, {"text": "我的电话费最近好转了很多。", "explanation": "这里应该用〈降低〉。费用的减少要用降低，好转指病情、局面等由差变好的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好转", "is_correct": true, "explanation": "好转：经济由差变好，与后句“找工作也容易多了”一致。"}, {"text": "下滑", "is_correct": false, "explanation": "语义：“下滑”指经济变差，与“找工作也容易多了”矛盾。"}, {"text": "减少", "is_correct": false, "explanation": "搭配：“减少”说数量，不能用来形容经济的整体状况。"}, {"text": "发生", "is_correct": false, "explanation": "语义：「发生」指事情产生，不表示经济由差变好，与「找工作也容易多了」的结果不符。"}], "explanations": {"好转": "好转：经济由差变好，与后句“找工作也容易多了”一致。", "下滑": "语义：“下滑”指经济变差，与“找工作也容易多了”矛盾。", "减少": "搭配：“减少”说数量，不能用来形容经济的整体状况。", "发生": "语义：「发生」指事情产生，不表示经济由差变好，与「找工作也容易多了」的结果不符。"}, "sentence_index": 6, "correct_answer": "好转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆新车的速度好转了很多。", "explanation": "这里应该用〈加快〉。速度的提升要用加快，好转指病情、局面等由差变好。"}, {"text": "孩子这一年的身高好转了不少。", "explanation": "这里应该用〈长高〉。身高的增长要用长高，好转指状况由差变好。"}, {"text": "这家公司的规模好转了很多。", "explanation": "这里应该用〈扩大〉。规模的增大要用扩大，好转指状况由差变好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把病情慢慢好转了。", "corrected_sentence": "病情慢慢好转了。", "error_description": "错误：“把病情慢慢好转了”。正确：“病情慢慢好转了”。“好转”是不及物动词，不能带“把”构成处置式，前面多加了“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气渐渐被好转了，大家都很开心。", "corrected_sentence": "天气渐渐好转了，大家都很开心。", "error_description": "错误：“天气渐渐被好转了”。正确：“天气渐渐好转了”。“好转”是不及物动词，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
