INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向好的方向转变。", "primary_collocate": null, "pronunciation": "hǎo zhuǎn", "ipa": "xau˨˩˦ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "市场情况从春天起开始好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望局面能早点好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系慢慢好转，又成了朋友。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府说明年经济会好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，路上的情况也好转了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作环境好转以后，大家更愿意留下来。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的情绪在朋友的帮助下好转了。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的情况从去年开始好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想让形势好转，大家得一起努力。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说下个月生意会有所好转。", "target_word": "好转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好转了", "label": "体标"}, {"form": "好转过", "label": "体标"}, {"form": "好轉", "label": "繁体"}], "register": "通用", "sense_fingerprint": "形势、局面等朝好的方向转变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好转", "is_correct": true, "explanation": "好转：市场情况由差变好，与“从春天起”的变化相符。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“开始”与“结束”语义冲突，“开始结束”不通。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于言论、文章，不能用于市场情况。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”用于电影、节目，不能用于市场情况。"}], "explanations": {"好转": "好转：市场情况由差变好，与“从春天起”的变化相符。", "结束": "语义：“开始”与“结束”语义冲突，“开始结束”不通。", "发表": "搭配：“发表”用于言论、文章，不能用于市场情况。", "放映": "搭配：“放映”用于电影、节目，不能用于市场情况。"}, "sentence_index": 0, "correct_answer": "好转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月报名的人数好转了不少。", "explanation": "这里应该用〈增加〉。人数的增多要用增加，好转指形势由差变好。"}, {"text": "今年工厂的产量好转了很多。", "explanation": "这里应该用〈提高〉。产量的提升要用提高，好转指形势由差变好。"}, {"text": "这家工厂的成本好转了不少。", "explanation": "这里应该用〈降低〉。成本的下降要用降低，好转指形势由差变好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好转", "is_correct": true, "explanation": "好转：情绪由差变好，与“朋友的帮助”的效果相符。"}, {"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”用于范围、规模，不能用来说情绪。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：「装修」的对象是房屋等建筑，不能用来说情绪的变化。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”需要带“讨论”“交流”等动作宾语，这里缺少宾语，句子不通。"}], "explanations": {"好转": "好转：情绪由差变好，与“朋友的帮助”的效果相符。", "扩大": "搭配：“扩大”用于范围、规模，不能用来说情绪。", "装修": "搭配：「装修」的对象是房屋等建筑，不能用来说情绪的变化。", "进行": "配价：“进行”需要带“讨论”“交流”等动作宾语，这里缺少宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "好转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的规模好转了很多。", "explanation": "这里应该用〈扩大〉。规模的增大要用扩大，好转指形势由差变好。"}, {"text": "这条河的深度最近好转了很多。", "explanation": "这里应该用〈加深〉。河流深度的增加要用加深，好转指病情、局面等由差变好的状况。"}, {"text": "这辆汽车的车速好转了不少。", "explanation": "这里应该用〈加快〉。车速的提升要用加快，好转指形势由差变好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府努力以后，经济好转着了。", "corrected_sentence": "政府努力以后，经济好转了。", "error_description": "错误：“经济好转着了”。正确：“经济好转了”。“好转”表示变化，与表示持续的“着”不合，“着”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "形势被好转了，大家都很高兴。", "corrected_sentence": "形势好转了，大家都很高兴。", "error_description": "错误：“形势被好转了”。正确：“形势好转了”。“好转”是不及物动词，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
