INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "粉碎是把东西弄得很碎很碎。", "primary_collocate": null, "pronunciation": "fěn suì", "ipa": "fən˨˩ swei˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器能把石头粉碎。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用机器把豆子粉碎了。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些纸粉碎，不要留下。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在粉碎旧砖头。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把冰块粉碎，放进果汁里。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器可以粉碎很硬的东西。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把饼干粉碎了，喂给小鸟吃。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把没用的文件都粉碎了。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用力一踩，就能粉碎这些小石子。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的机器正在粉碎花生。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉碎了", "label": "体标"}, {"form": "粉碎过", "label": "体标"}, {"form": "粉碎机", "label": "复合"}, {"form": "粉碎性骨折", "label": "复合"}], "register": "口语", "sense_fingerprint": "用力或用机器把具体的东西弄成很碎的小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉碎", "is_correct": true, "explanation": "粉碎：用机器把具体的石头弄成很碎的小块，符合句意。"}, {"text": "消化", "is_correct": false, "explanation": "语义：消化是食物在体内分解，机器不能消化石头。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是录音、影像，不能说播放石头。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译针对语言文字，石头不是可以翻译的内容。"}], "explanations": {"粉碎": "粉碎：用机器把具体的石头弄成很碎的小块，符合句意。", "消化": "语义：消化是食物在体内分解，机器不能消化石头。", "播放": "搭配：“播放”的对象是录音、影像，不能说播放石头。", "翻译": "语义：翻译针对语言文字，石头不是可以翻译的内容。"}, "sentence_index": 0, "correct_answer": "粉碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一用力就粉碎了那只袜子。", "explanation": "这里应该用〈撕破〉或〈穿破〉。袜子是布料，弄破应说撕破或穿破；粉碎指弄成很细的碎块。"}, {"text": "他不小心粉碎了一碗汤。", "explanation": "这里应该用〈打翻〉。汤是液体，洒了应说打翻，不能说粉碎。"}, {"text": "他不小心粉碎了一根头发。", "explanation": "这里应该用〈扯断〉或〈剪断〉。头发细长，断了应说扯断或剪断，不能说粉碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉碎", "is_correct": true, "explanation": "粉碎：把饼干弄成很碎的小块，再喂给小鸟，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，饼干不能唱。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”要求的宾语是申请、计划等事项，不能批准饼干。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、话题，不说讨论饼干。"}], "explanations": {"粉碎": "粉碎：把饼干弄成很碎的小块，再喂给小鸟，符合句意。", "唱": "语义：唱的对象是歌曲，饼干不能唱。", "批准": "配价：“批准”要求的宾语是申请、计划等事项，不能批准饼干。", "讨论": "搭配：“讨论”的对象是问题、话题，不说讨论饼干。"}, "sentence_index": 6, "correct_answer": "粉碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把湿衣服粉碎了，挂在阳台上晾。", "explanation": "这里应该用〈拧干〉。拧是把湿衣服里的水挤出来，衣服不能粉碎，应说拧干。"}, {"text": "妈妈把冰箱里的牛奶粉碎了。", "explanation": "这里应该用〈倒掉〉或〈喝完〉。牛奶是液体，不能弄成碎块；粉碎只用于固体的东西。"}, {"text": "他用力一握，把那个气球粉碎了。", "explanation": "这里应该用〈捏破〉或〈戳破〉。气球是薄膜，破了应说捏破或戳破，不能说粉碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在粉碎了这些旧木头。", "corrected_sentence": "工人们正在粉碎这些旧木头。", "error_description": "体标错误：“正在”表示动作进行中，不能再加“了”，应说“正在粉碎这些旧木头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里的机器把花生粉碎很细。", "corrected_sentence": "厨房里的机器把花生粉碎得很细。", "error_description": "程度补语缺“得”：说明程度要用“粉碎得很细”，“粉碎很细”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
