INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彻底打垮、摧毁（敌人、阴谋、希望等）。", "primary_collocate": null, "pronunciation": "fěn suì", "ipa": "fən˨˩ swei˥˩", "syllable_count": 2, "sentences": [{"text": "我们粉碎了敌人的阴谋。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察粉碎了这个犯罪团伙。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场胜利粉碎了对手的希望。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话粉碎了我所有的幻想。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察及时粉碎了一起抢劫计划。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队彻底粉碎了敌人的进攻。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息粉碎了谣言。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，粉碎了他们的计划。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些证据粉碎了他的谎言。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民粉碎了敌人的封锁。", "target_word": "粉碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉碎了", "label": "体标"}, {"form": "粉碎过", "label": "体标"}], "register": "书面", "sense_fingerprint": "彻底打垮敌人、阴谋、计划，或使希望、幻想破灭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉碎", "is_correct": true, "explanation": "粉碎：彻底打垮敌人的阴谋，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，阴谋不能喝。"}, {"text": "修复", "is_correct": false, "explanation": "语义：修复针对损坏的器物，阴谋不是可以修复的东西。"}, {"text": "雇用", "is_correct": false, "explanation": "配价：“雇用”的对象是人，不能说雇用阴谋。"}], "explanations": {"粉碎": "粉碎：彻底打垮敌人的阴谋，符合句意。", "喝": "搭配：“喝”的对象是液体，阴谋不能喝。", "修复": "语义：修复针对损坏的器物，阴谋不是可以修复的东西。", "雇用": "配价：“雇用”的对象是人，不能说雇用阴谋。"}, "sentence_index": 0, "correct_answer": "粉碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心粉碎了一杯水。", "explanation": "这里应该用〈打翻〉。水是液体，不能粉碎，洒了说打翻。"}, {"text": "他粉碎了整个下午的时间，什么也没做。", "explanation": "这里应该用〈浪费〉。粉碎指弄碎或彻底打垮，时间不能被粉碎，浪费时间应说浪费。"}, {"text": "他粉碎了客人。", "explanation": "这里应该用〈打发〉。打发是请客人离开；粉碎表示彻底打垮敌人、计划等，不能用来说请客人离开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉碎", "is_correct": true, "explanation": "粉碎：彻底打垮谣言，符合句意。"}, {"text": "吹奏", "is_correct": false, "explanation": "搭配：“吹奏”用于乐器，谣言不能吹奏。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是人或景物，不能说拍摄谣言。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”的对象是艺术作品或美好的事物，谣言不能欣赏。"}], "explanations": {"粉碎": "粉碎：彻底打垮谣言，符合句意。", "吹奏": "搭配：“吹奏”用于乐器，谣言不能吹奏。", "拍摄": "搭配：“拍摄”的对象是人或景物，不能说拍摄谣言。", "欣赏": "配价：“欣赏”的对象是艺术作品或美好的事物，谣言不能欣赏。"}, "sentence_index": 6, "correct_answer": "粉碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于粉碎了自己的梦想，当上了医生。", "explanation": "这里应该用〈实现〉。当上医生是梦想成真，粉碎梦想意思正好相反。"}, {"text": "医生粉碎了他的病，他很快就好了。", "explanation": "这里应该用〈治好〉。粉碎用于敌人、阴谋、希望等，不用于治病。"}, {"text": "我们粉碎了一个新计划，明天开始做。", "explanation": "这里应该用〈制定〉。粉碎计划是把计划彻底打垮，不能再开始做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没有粉碎了敌人的阴谋。", "corrected_sentence": "我们没有粉碎敌人的阴谋。", "error_description": "体标错误：“没有”否定的是未发生的动作，不能与“了”同用，应说“没有粉碎敌人的阴谋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人民把敌人的封锁粉碎。", "corrected_sentence": "人民把敌人的封锁粉碎了。", "error_description": "把字句错误：“把”字句中动词“粉碎”后要有其他成分，应说“把敌人的封锁粉碎了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": true, "explanation": "出发指离开起点，与“到达”互为反义。"}, {"text": "停留", "is_correct": false, "explanation": "停留指在某处暂时待着，与“到达”的“走到”没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停下来放松，与“到达”不构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "等待指在原地期待某事，与“到达”不是反义关系。"}], "correct_answer": "出发", "explanations": {"出发": "出发指离开起点，与“到达”互为反义。", "停留": "停留指在某处暂时待着，与“到达”的“走到”没有对立关系。", "休息": "休息指停下来放松，与“到达”不构成反义关系。", "等待": "等待指在原地期待某事，与“到达”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": true, "explanation": "出发指离开起点，与“到达”互为反义。"}, {"text": "停靠", "is_correct": false, "explanation": "停靠指车船暂时停在某处，与“到达”不是反义关系。"}, {"text": "逗留", "is_correct": false, "explanation": "逗留指在某地多待一会儿，与“到达”没有对立关系。"}, {"text": "守候", "is_correct": false, "explanation": "守候指在原地等待，与“到达”不构成反义。"}], "correct_answer": "出发", "explanations": {"出发": "出发指离开起点，与“到达”互为反义。", "停靠": "停靠指车船暂时停在某处，与“到达”不是反义关系。", "逗留": "逗留指在某地多待一会儿，与“到达”没有对立关系。", "守候": "守候指在原地等待，与“到达”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到达是走到了要去的地方。", "primary_collocate": null, "pronunciation": "dào dá", "ipa": "taʊ̯˥˩ ta˧˥", "syllable_count": 2, "sentences": [{"text": "我们坐了两个小时的车，终于到达了山脚下。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车几点到达北京？", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个到达了终点。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机已经到达上海了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到达学校后给我打电话。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了一个下午，才到达那个小村子。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她到达的时候，会议已经开始了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到达车站了吗？", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到达山顶以后，我们坐下来休息。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有到达过那么远的地方。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到达了", "label": "完成体"}, {"form": "到达过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "走到要去的地方，如山顶、终点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达某个地点，与“坐了两个小时的车”和“山脚下”的句意相符。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”要说“从…出发”或“向…出发”，不能直接带“山脚下”作宾语。"}, {"text": "骑", "is_correct": false, "explanation": "语义：前文说“坐了车”，“骑”与之矛盾，而且“骑”的宾语应是马或车，不是地点。"}, {"text": "登上", "is_correct": false, "explanation": "搭配：“登上”指爬到高处，与位置低的“山脚下”不搭配。"}], "explanations": {"到达": "到达表示抵达某个地点，与“坐了两个小时的车”和“山脚下”的句意相符。", "出发": "配价：“出发”要说“从…出发”或“向…出发”，不能直接带“山脚下”作宾语。", "骑": "语义：前文说“坐了车”，“骑”与之矛盾，而且“骑”的宾语应是马或车，不是地点。", "登上": "搭配：“登上”指爬到高处，与位置低的“山脚下”不搭配。"}, "sentence_index": 0, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我的成绩到达了九十分。", "explanation": "这里应该用〈达到〉。到达指走到某个地点，成绩、分数等数量要用达到。"}, {"text": "两家公司终于到达了合作协议。", "explanation": "这里应该用〈达成〉。到达指走到某处，协议要用达成。"}, {"text": "她努力工作，终于到达了自己的梦想。", "explanation": "这里应该用〈实现〉。到达指走到某个地点，梦想要用实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达，符合“她……的时候，会议已经开始了”的时间关系。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”的对象是会议、活动等，不能以“她”作主语，说“她举行的时候”句子不通。"}, {"text": "散会", "is_correct": false, "explanation": "配价：“散会”的主语应是会议，不能以“她”作主语。"}, {"text": "闭幕", "is_correct": false, "explanation": "语义：“闭幕”指活动终了，与“会议已经开始了”的状态不符，而且不能以人作主语。"}], "explanations": {"到达": "到达表示抵达，符合“她……的时候，会议已经开始了”的时间关系。", "举行": "配价：“举行”的对象是会议、活动等，不能以“她”作主语，说“她举行的时候”句子不通。", "散会": "配价：“散会”的主语应是会议，不能以“她”作主语。", "闭幕": "语义：“闭幕”指活动终了，与“会议已经开始了”的状态不符，而且不能以人作主语。"}, "sentence_index": 6, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上到达了老朋友。", "explanation": "这里应该用〈遇到〉。到达指走到某个地点，遇见人要用遇到。"}, {"text": "我终于到达了老师。", "explanation": "这里应该用〈见到〉。到达指走到某处，见人要用见到。"}, {"text": "他终于到达了任务。", "explanation": "这里应该用〈完成〉。到达指走到某地，任务要用完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天下午到达了机场。", "corrected_sentence": "我们明天下午到达机场。", "error_description": "错误在“到达”后面的“了”。“明天下午”是将来的时间，动作还没有发生，不能用“到达了”，应去掉“了”，说“我们明天下午到达机场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车八点在到达车站。", "corrected_sentence": "火车八点到达车站。", "error_description": "错误在“到达”前面的“在”。“到达”是瞬时动词，不能用“在”表示进行，应去掉“在”，说“火车八点到达车站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
