INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抵达；到了某个地点。", "primary_collocate": null, "pronunciation": "dào dá", "ipa": "taʊ̯˥˩ ta˧˥", "syllable_count": 2, "sentences": [{"text": "客人下午三点到达酒店。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船明天早上到达港口。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨晚到达了成都。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到达机场时，天已经黑了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这班飞机准时到达了北京。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家到达以后，先在门口等了一会儿。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十点才到达公司，所以迟到了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在八点前到达学校门口。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友已经到达了，你们快来吧。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车到达终点站后，大家都下车了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到达了", "label": "完成体"}, {"form": "到达过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "抵达某地，如机场、车站、港口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达某地，与“下午三点”和“酒店”相符。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”后不能直接带“酒店”，要说“从…出发”。"}, {"text": "登记", "is_correct": false, "explanation": "语义：“登记”指办理登记手续，不表示人走到某地。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象应是人，不说“拜访酒店”。"}], "explanations": {"到达": "到达表示抵达某地，与“下午三点”和“酒店”相符。", "出发": "配价：“出发”后不能直接带“酒店”，要说“从…出发”。", "登记": "语义：“登记”指办理登记手续，不表示人走到某地。", "拜访": "搭配：“拜访”的对象应是人，不说“拜访酒店”。"}, "sentence_index": 0, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终于到达了冠军。", "explanation": "这里应该用〈夺得〉。到达指走到某地，冠军要用夺得。"}, {"text": "他的演讲到达了全场的掌声。", "explanation": "这里应该用〈赢得〉。到达指走到某处，掌声要用赢得。"}, {"text": "这次实验到达了好成绩。", "explanation": "这里应该用〈取得〉。到达指走到某个地点，成绩要用取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达公司，与“十点才”迟到的句意相符。"}, {"text": "上班", "is_correct": false, "explanation": "配价：“上班”不带处所宾语，应说“到公司上班”，不能直接说“上班公司”。"}, {"text": "下班", "is_correct": false, "explanation": "配价：“下班”同样不能直接带“公司”作宾语。"}, {"text": "开会", "is_correct": false, "explanation": "搭配：“开会”后不能直接接处所“公司”，句意不通。"}], "explanations": {"到达": "到达表示抵达公司，与“十点才”迟到的句意相符。", "上班": "配价：“上班”不带处所宾语，应说“到公司上班”，不能直接说“上班公司”。", "下班": "配价：“下班”同样不能直接带“公司”作宾语。", "开会": "搭配：“开会”后不能直接接处所“公司”，句意不通。"}, "sentence_index": 6, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在大学到达了很多朋友。", "explanation": "这里应该用〈结交〉。到达指走到某处，交朋友要用结交。"}, {"text": "她终于到达了奖状。", "explanation": "这里应该用〈拿到〉。到达指走到某地，奖状要用拿到。"}, {"text": "我在门外到达了一声喊叫。", "explanation": "这里应该用〈听到〉。到达指走到某处，声音要用听到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人明天下午到达了酒店。", "corrected_sentence": "客人明天下午到达酒店。", "error_description": "错误在“到达”后面的“了”。“明天下午”是将来的时间，动作还没有发生，不能用“到达了”，应去掉“了”，说“客人明天下午到达酒店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们晚上十点在到达成都。", "corrected_sentence": "他们晚上十点到达成都。", "error_description": "错误在“到达”前面的“在”。“到达”是瞬时动词，不能用“在”表示进行，应去掉“在”，说“他们晚上十点到达成都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
