INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审讯是警察或法官问坏人问题，弄清楚事情。", "primary_collocate": null, "pronunciation": "shěn xùn", "ipa": "ʂən˨˩˦ ɕɥn˥˩", "syllable_count": 2, "sentences": [{"text": "警察在审讯那个小偷。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审讯了坏人，想弄清楚事情。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察审讯坏人，问了很多问题。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天警察审讯了一个小偷。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正审讯着抢钱的坏人。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "审讯以后，警察知道了事情的经过。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要审讯坏人，才能知道真相。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察审讯过他，但他没说实话。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察一边审讯，一边写记录。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里警察审讯坏人的样子很严肃。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审讯了", "label": "体标（了）"}, {"form": "审讯过", "label": "体标（过）"}, {"form": "审讯着", "label": "体标（着）"}], "register": "正式", "sense_fingerprint": "警察或法官问坏人问题，弄清楚事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审讯", "is_correct": true, "explanation": "正确：“审讯”指警察向坏人查问事情，与句中的警察和小偷相符。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：“批发”的对象是货物，不能说“批发那个小偷”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞人，不会用来处理小偷。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用火烤制食品，不能用于人。"}], "explanations": {"审讯": "正确：“审讯”指警察向坏人查问事情，与句中的警察和小偷相符。", "批发": "搭配：“批发”的对象是货物，不能说“批发那个小偷”。", "表扬": "语义：“表扬”是称赞人，不会用来处理小偷。", "烘焙": "语义：“烘焙”指用火烤制食品，不能用于人。"}, "sentence_index": 0, "correct_answer": "审讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生审讯了病人的心脏。", "explanation": "这里应该用〈检查〉。审讯的对象是人，不能用于身体器官，应说“检查”。"}, {"text": "他仔细审讯了那张旧地图。", "explanation": "这里应该用〈查看〉。审讯的对象是人，地图这类物品要用“查看”。"}, {"text": "海关审讯了这批货物。", "explanation": "这里应该用〈检验〉。审讯的对象是人，货物要用“检验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审讯", "is_correct": true, "explanation": "正确：“审讯”指法官查问坏人，才能知道真相，与句中的法官相符。"}, {"text": "放生", "is_correct": false, "explanation": "语义：“放生”是把动物放回自然，不能用于坏人。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”的对象是内容或知识，不能说“讲解坏人”。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“才能知道真相”的逻辑不合。"}], "explanations": {"审讯": "正确：“审讯”指法官查问坏人，才能知道真相，与句中的法官相符。", "放生": "语义：“放生”是把动物放回自然，不能用于坏人。", "讲解": "搭配：“讲解”的对象是内容或知识，不能说“讲解坏人”。", "赞美": "语义：“赞美”是称赞，与“才能知道真相”的逻辑不合。"}, "sentence_index": 6, "correct_answer": "审讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷昨晚审讯了偷吃饼干的小孙子。", "explanation": "这里应该用〈教训〉。“审讯”只指警察或法官向坏人查问以弄清事情，爷爷用它来说管教小孙子，是把它误用成了家里的“教训”。"}, {"text": "班主任审讯了考试作弊的同学。", "explanation": "这里应该用〈询问〉。“审讯”只指警察或法官向坏人查问以弄清事情，班主任问考试作弊的同学，应说“询问”。"}, {"text": "邻居审讯了那个乱扔垃圾的人。", "explanation": "这里应该用〈劝阻〉。“审讯”只指警察或法官向坏人查问以弄清事情，邻居要制止乱扔垃圾的人，应说“劝阻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察正在审讯了那个小偷，想找出赃物。", "corrected_sentence": "警察正在审讯那个小偷，想找出赃物。", "error_description": "时态冲突：“正在”表示动作进行，不能与表示完成的“了”同用，应说“正在审讯那个小偷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官把坏人审讯，才能查清真相。", "corrected_sentence": "法官把坏人审讯完，才能查清真相。", "error_description": "补语缺失：“把”字句的动词后要有补语，应说“把坏人审讯完”，只说“把坏人审讯”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
