INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "司法机关向案件相关者查问案情。", "primary_collocate": null, "pronunciation": "shěn xùn", "ipa": "ʂən˨˩˦ ɕɥn˥˩", "syllable_count": 2, "sentences": [{"text": "警察审讯了嫌疑人三个小时。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官正在审讯那名犯罪嫌疑人。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察连夜审讯着两名嫌疑人。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察昨晚审讯过他两次。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法机关依法审讯嫌疑人。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "审讯时，嫌疑人一直不说话。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察要先审讯，才能弄清案情。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们审讯了一整夜，还是没有结果。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官亲自审讯了这起案件的主要嫌疑人。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嫌疑人说，警察审讯时很严格。", "target_word": "审讯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审讯了", "label": "体标（了）"}, {"form": "审讯过", "label": "体标（过）"}, {"form": "审讯着", "label": "体标（着）"}], "register": "正式", "sense_fingerprint": "司法机关向案件相关者查问案情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审讯", "is_correct": true, "explanation": "正确：“审讯”指司法机关向案件相关者查问案情，与句中的警察和嫌疑人相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与句中查问嫌疑人的行为不符。"}, {"text": "调解", "is_correct": false, "explanation": "搭配：“调解”的对象是纠纷或矛盾，不能说“调解嫌疑人”。"}, {"text": "放映", "is_correct": false, "explanation": "语义：“放映”指播放影片，不能用在嫌疑人身上。"}], "explanations": {"审讯": "正确：“审讯”指司法机关向案件相关者查问案情，与句中的警察和嫌疑人相符。", "表扬": "语义：“表扬”是称赞，与句中查问嫌疑人的行为不符。", "调解": "搭配：“调解”的对象是纠纷或矛盾，不能说“调解嫌疑人”。", "放映": "语义：“放映”指播放影片，不能用在嫌疑人身上。"}, "sentence_index": 0, "correct_answer": "审讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向路人审讯去车站的路。", "explanation": "这里应该用〈询问〉。审讯只用于司法机关向案件相关者查问案情，向路人问路不能用“审讯”。"}, {"text": "警方审讯了这起案件。", "explanation": "这里应该用〈调查〉。审讯的对象是案件相关的人，不能用于案件本身。"}, {"text": "海关审讯了我的护照。", "explanation": "这里应该用〈审查〉。审讯的对象是人，护照这类物品要用〈审查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审讯", "is_correct": true, "explanation": "正确：“审讯”指司法机关查问案情，正是要先做的事，才能弄清案情。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指修饰房屋，与“弄清案情”无关。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要搬运的对象，句中没有受事，不能单独说“要先搬运”。"}, {"text": "煮饭", "is_correct": false, "explanation": "语义：“煮饭”是做饭，不能用来弄清案情。"}], "explanations": {"审讯": "正确：“审讯”指司法机关查问案情，正是要先做的事，才能弄清案情。", "装修": "语义：“装修”指修饰房屋，与“弄清案情”无关。", "搬运": "配价：“搬运”需要搬运的对象，句中没有受事，不能单独说“要先搬运”。", "煮饭": "语义：“煮饭”是做饭，不能用来弄清案情。"}, "sentence_index": 6, "correct_answer": "审讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈昨天审讯了不肯吃饭的弟弟。", "explanation": "这里应该用〈教育〉。审讯的主体是司法机关，妈妈管教孩子不能用“审讯”。"}, {"text": "班长审讯了迟到的同学。", "explanation": "这里应该用〈询问〉。“审讯”只指司法人员向案件相关者查问案情，班长用它来盘问迟到的同学，是把它误用成了班级里的“盘问”。"}, {"text": "老板审讯了辞职的员工，问他为什么要走。", "explanation": "这里应该用〈询问〉。老板不是司法机关，问员工辞职原因不能用“审讯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把审讯完嫌疑人，就去休息了。", "corrected_sentence": "警察审讯完嫌疑人，就去休息了。", "error_description": "「把」字位置错误：「把」后面要先接宾语，再接动词。应说「审讯完嫌疑人」或「把嫌疑人审讯完」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察审讯了跟嫌疑人一整夜，还是没有结果。", "corrected_sentence": "警察审讯了嫌疑人一整夜，还是没有结果。", "error_description": "介词错误：「审讯」直接带受事宾语，不用介词「跟」引出嫌疑人。应说「审讯了嫌疑人一整夜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”与“糟”构成反义，指情况好。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”与“糟”不构成反义，不是本义项的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“糟”不构成反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”指外表好看，与“糟”不构成反义。"}], "correct_answer": "好", "explanations": {"好": "正确：“好”与“糟”构成反义，指情况好。", "复杂": "“复杂”与“糟”不构成反义，不是本义项的反义词。", "聪明": "“聪明”形容人的智力，与“糟”不构成反义。", "漂亮": "“漂亮”指外表好看，与“糟”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”与“糟”构成反义，指情况好。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”指价格低，与“糟”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不紧张、不费力，与“糟”不构成反义。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、喧闹，与“糟”不构成反义。"}], "correct_answer": "好", "explanations": {"好": "正确：“好”与“糟”构成反义，指情况好。", "便宜": "“便宜”指价格低，与“糟”不构成反义。", "轻松": "“轻松”指不紧张、不费力，与“糟”不构成反义。", "热闹": "“热闹”指人多、喧闹，与“糟”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "糟是不好，一团乱。", "primary_collocate": null, "pronunciation": "zāo", "ipa": "tsau˥", "syllable_count": 1, "sentences": [{"text": "今天天气太糟了，我们别出去了。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天的心情很糟，不想说话。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很糟，我看不懂。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得太糟了。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开得很糟，大家吵了一个小时。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果很糟，我们输了。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情变得越来越糟，他不知道怎么办。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天睡得很糟，今天没有精神。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的情况不算太糟，医生说很快会好。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的服务糟透了，我们等了一小时。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "糟糕", "label": "复合"}], "register": "口语", "sense_fingerprint": "情况不好、很乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糟", "is_correct": true, "explanation": "zāo，意思是情况不好、一团乱，即本词。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早上。"}, {"text": "造", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zāo 的声母不同（zh 与 z），意思是招手、招收。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 zāo 的声母不同（c 与 z），意思是操练、体操。"}], "explanations": {"糟": "zāo，意思是情况不好、一团乱，即本词。", "早": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早上。", "造": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。", "招": "zhāo（第一声）与 zāo 的声母不同（zh 与 z），意思是招手、招收。", "操": "cāo（第一声）与 zāo 的声母不同（c 与 z），意思是操练、体操。"}, "sentence_index": null, "correct_answer": "糟"}, "level_3": {"options": [{"text": "糟", "is_correct": true, "explanation": "正确：“太糟了”描述天气不好，与后句“别出去了”相符。"}, {"text": "好", "is_correct": false, "explanation": "语义：天气好就该出去，“别出去了”与“好”矛盾。"}, {"text": "大", "is_correct": false, "explanation": "搭配：“大”用于体积，不说“天气太大”。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”用于人的情绪，不修饰天气。"}], "explanations": {"糟": "正确：“太糟了”描述天气不好，与后句“别出去了”相符。", "好": "语义：天气好就该出去，“别出去了”与“好”矛盾。", "大": "搭配：“大”用于体积，不说“天气太大”。", "高兴": "搭配：“高兴”用于人的情绪，不修饰天气。"}, "sentence_index": 0, "correct_answer": "糟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的安排很糟，大家都说很精彩。", "explanation": "这里应该用〈好〉。糟表示不好，与后句“大家都说很精彩”矛盾。"}, {"text": "他把这块布糟了，现在没法穿了。", "explanation": "这里应该用〈糟蹋〉。糟不能作动词表示“毁坏、浪费”，这一意思要说“糟蹋”。"}, {"text": "他有个糟习惯，总是迟到。", "explanation": "这里应该用〈坏〉。“坏习惯”是固定说法，糟用于情况或状态，不修饰习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "糟", "is_correct": true, "explanation": "zāo，意思是情况不好、一团乱，即本词。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。"}, {"text": "灶", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。"}, {"text": "枣", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是红枣。"}, {"text": "凿", "is_correct": false, "explanation": "záo（第二声）与 zāo（第一声）声调不同，意思是凿子、凿开。"}], "explanations": {"糟": "zāo，意思是情况不好、一团乱，即本词。", "澡": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。", "灶": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。", "枣": "zǎo（第三声）与 zāo（第一声）声调不同，意思是红枣。", "凿": "záo（第二声）与 zāo（第一声）声调不同，意思是凿子、凿开。"}, "sentence_index": null, "correct_answer": "糟"}, "level_3": {"options": [{"text": "糟", "is_correct": true, "explanation": "正确：“越来越糟”描述事情变坏，与后句“不知道怎么办”相符。"}, {"text": "顺利", "is_correct": false, "explanation": "语义：事情越来越顺利时，不会“不知道怎么办”，与后句矛盾。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容人或景物，不说“事情变得美丽”。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“幸福”多用于人的生活和感受，不说“事情变得幸福”。"}], "explanations": {"糟": "正确：“越来越糟”描述事情变坏，与后句“不知道怎么办”相符。", "顺利": "语义：事情越来越顺利时，不会“不知道怎么办”，与后句矛盾。", "美丽": "搭配：“美丽”形容人或景物，不说“事情变得美丽”。", "幸福": "搭配：“幸福”多用于人的生活和感受，不说“事情变得幸福”。"}, "sentence_index": 6, "correct_answer": "糟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的裁判很糟，观众都很满意。", "explanation": "这里应该用〈好〉。糟表示不好，与后句“观众都很满意”矛盾。"}, {"text": "他的新电脑很糟，运行得特别快。", "explanation": "这里应该用〈好〉。糟表示不好，与后句“运行得特别快”矛盾。"}, {"text": "这间教室的桌椅很糟，每一张都很结实。", "explanation": "这里应该用〈好〉。糟表示不好，与后句“每一张都很结实”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次演出我们演很糟，观众都走了。", "corrected_sentence": "这次演出我们演得很糟，观众都走了。", "error_description": "补语标记“得”缺失：“很糟”是“演”的补语，中间必须用“得”引出，应说“演得很糟”，不能说“演很糟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的天气很太糟了，大家都很失望。", "corrected_sentence": "这次旅行的天气太糟了，大家都很失望。", "error_description": "程度副词重复：“太”和“很”不能同时修饰“糟”，应去掉“很”，说“太糟了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
