INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88982, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（木头、布、绳子等）腐烂，不结实。", "primary_collocate": null, "pronunciation": "zāo", "ipa": "tsau˥", "syllable_count": 1, "sentences": [{"text": "这根木头太糟了，一踩就断。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下的木板已经糟了，不能走。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条绳子糟了，别用它拉东西。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的窗框都糟了，风吹进来。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服放了很多年，布都糟了。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的底糟了，东西会掉出来。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头泡在水里太久，会变糟。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把椅子的腿糟了，千万别坐。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙角的木门糟得一碰就碎。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船在海边放了十年，船底早就糟了。", "target_word": "糟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "糟糕", "label": "复合"}], "register": "口语", "sense_fingerprint": "木头、布、绳子等腐烂不结实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糟", "is_correct": true, "explanation": "zāo，意思是腐烂、不结实，即本词。"}, {"text": "枣", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是红枣。"}, {"text": "凿", "is_correct": false, "explanation": "záo（第二声）与 zāo（第一声）声调不同，意思是凿子、凿开。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。"}, {"text": "造", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。"}], "explanations": {"糟": "zāo，意思是腐烂、不结实，即本词。", "枣": "zǎo（第三声）与 zāo（第一声）声调不同，意思是红枣。", "凿": "záo（第二声）与 zāo（第一声）声调不同，意思是凿子、凿开。", "澡": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。", "造": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。"}, "sentence_index": null, "correct_answer": "糟"}, "level_3": {"options": [{"text": "糟", "is_correct": true, "explanation": "正确：“太糟了”描述木头腐坏，与后句“一踩就断”相符。"}, {"text": "结实", "is_correct": false, "explanation": "语义：木头结实就不会“一踩就断”，“结实”与后句矛盾。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”用于人的情绪，不修饰木头。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”用于人的智力，不修饰木头。"}], "explanations": {"糟": "正确：“太糟了”描述木头腐坏，与后句“一踩就断”相符。", "结实": "语义：木头结实就不会“一踩就断”，“结实”与后句矛盾。", "高兴": "搭配：“高兴”用于人的情绪，不修饰木头。", "聪明": "搭配：“聪明”用于人的智力，不修饰木头。"}, "sentence_index": 0, "correct_answer": "糟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块铁板泡在水里太久，已经糟了。", "explanation": "这里应该用〈锈〉。糟指木头、布等腐烂，铁不会糟，只会生锈。"}, {"text": "这些苹果放了太久，都糟了。", "explanation": "这里应该用〈烂〉。水果变坏说“烂了”，糟用于木头、布、绳子等不结实。"}, {"text": "这块石头放了很多年，已经糟了。", "explanation": "这里应该用〈旧〉。石头不会腐烂，糟只用于木头、布等会腐烂的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88982, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "糟", "is_correct": true, "explanation": "zāo，意思是腐烂、不结实，即本词。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早上。"}, {"text": "招", "is_correct": false, "explanation": "zhāo（第一声）与 zāo 的声母不同（zh 与 z），意思是招手、招收。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 zāo 的声母不同（c 与 z），意思是操练、体操。"}, {"text": "灶", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。"}], "explanations": {"糟": "zāo，意思是腐烂、不结实，即本词。", "早": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早上。", "招": "zhāo（第一声）与 zāo 的声母不同（zh 与 z），意思是招手、招收。", "操": "cāo（第一声）与 zāo 的声母不同（c 与 z），意思是操练、体操。", "灶": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。"}, "sentence_index": null, "correct_answer": "糟"}, "level_3": {"options": [{"text": "糟", "is_correct": true, "explanation": "正确：“会变糟”描述木头泡水后腐坏，与句中“太久”相符。"}, {"text": "好", "is_correct": false, "explanation": "语义：木头泡在水里太久不会“变好”，与句中的“太久”矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "语义：木头不会“变甜”，与句意不符。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容人或景物，不用于木头的变化。"}], "explanations": {"糟": "正确：“会变糟”描述木头泡水后腐坏，与句中“太久”相符。", "好": "语义：木头泡在水里太久不会“变好”，与句中的“太久”矛盾。", "甜": "语义：木头不会“变甜”，与句意不符。", "美丽": "搭配：“美丽”形容人或景物，不用于木头的变化。"}, "sentence_index": 6, "correct_answer": "糟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批刚砍下来的木料很糟，但是很硬。", "explanation": "这里的“糟”指腐烂损坏，刚砍下的木料很硬时说“很糟”自相矛盾，应说“很硬”。"}, {"text": "这盆刚栽下的花根很糟，长得特别好。", "explanation": "这里应该用〈好〉。糟指腐烂损坏，花根长得特别好时说“很糟”自相矛盾。"}, {"text": "这个铁锅用了很多年，锅底都糟了。", "explanation": "这里应该用〈锈〉。铁不会腐烂，糟用于木头、布、绳子等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX