INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧木板已经糟的，不能再用。", "corrected_sentence": "这些旧木板已经糟了，不能再用。", "error_description": "“糟”表示状态出现变化，应说“糟了”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些竹竿糟泡了。", "corrected_sentence": "他把这些竹竿泡糟了。", "error_description": "结果补语位置错误：“糟”是“泡”的结果补语，应说“泡糟了”，不能说“糟泡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
