INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写下是用笔把字写在纸上，留下来。", "primary_collocate": null, "pronunciation": "xiě xià", "ipa": "ɕjɛ˨˩˦ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "请在纸上写下你的名字。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起笔，在本子上写下了地址。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在卡片上写下了新年愿望。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用笔写下你的电话号码。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在纸条上写下了房间号。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在信纸上写下了几行字。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在购物单上写下了要买的东西。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先在答题纸上写下你的姓名。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在笔记本上写下过他的地址。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用红笔在小纸条上写下了一句话。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写下了", "label": "完成体"}, {"form": "写下过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用笔把字写在纸上留下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88985, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下 xiě xià 指用笔把字写在纸上留下来，即本词。"}, {"text": "卸下", "is_correct": false, "explanation": "卸下 xiè xià 与写下 xiě xià 第一个音节声调不同：xiè（第四声）与 xiě（第三声）不同，意思是把东西从身上或车上取下。"}, {"text": "解下", "is_correct": false, "explanation": "解下 jiě xià 与写下 xiě xià 声母不同：j 与 x 不同，声调相同，意思是解开后取下。"}, {"text": "西下", "is_correct": false, "explanation": "西下 xī xià 与写下 xiě xià 第一个音节声调不同：xī（第一声）与 xiě（第三声）不同，意思是（太阳）向西落下，如夕阳西下。"}, {"text": "歇下", "is_correct": false, "explanation": "歇下 xiē xià 与写下 xiě xià 第一个音节声调不同：xiē（第一声）与 xiě（第三声）不同，意思是停下来休息。"}], "explanations": {"写下": "正确。写下 xiě xià 指用笔把字写在纸上留下来，即本词。", "卸下": "卸下 xiè xià 与写下 xiě xià 第一个音节声调不同：xiè（第四声）与 xiě（第三声）不同，意思是把东西从身上或车上取下。", "解下": "解下 jiě xià 与写下 xiě xià 声母不同：j 与 x 不同，声调相同，意思是解开后取下。", "西下": "西下 xī xià 与写下 xiě xià 第一个音节声调不同：xī（第一声）与 xiě（第三声）不同，意思是（太阳）向西落下，如夕阳西下。", "歇下": "歇下 xiē xià 与写下 xiě xià 第一个音节声调不同：xiē（第一声）与 xiě（第三声）不同，意思是停下来休息。"}, "sentence_index": null, "correct_answer": "写下"}, "level_3": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下表示用笔把字写在纸上留下来，与“在纸上”和“你的名字”搭配。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：唱出是发出声音，无法在纸上进行，与“在纸上”的语境冲突。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，不说吃掉名字。"}, {"text": "吞下", "is_correct": false, "explanation": "搭配：“吞下”多用于食物或药物，不能用于名字。"}], "explanations": {"写下": "正确。写下表示用笔把字写在纸上留下来，与“在纸上”和“你的名字”搭配。", "唱出": "语义：唱出是发出声音，无法在纸上进行，与“在纸上”的语境冲突。", "吃掉": "搭配：“吃掉”的对象是食物，不说吃掉名字。", "吞下": "搭配：“吞下”多用于食物或药物，不能用于名字。"}, "sentence_index": 0, "correct_answer": "写下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上写下了一只小猫。", "explanation": "这里应该用〈画下〉。画下指用笔画出图形，写下指用笔写字，不能用来表示画一只小猫。"}, {"text": "妈妈写下了一张全家福。", "explanation": "这里应该用〈留下〉。留下指把照片、纪念品保存下来，写下只用于文字，照片不能写下。"}, {"text": "工人在墙上写下了一只鸟。", "explanation": "这里应该用〈刻下〉。刻下指用刀在墙上或石头上刻出图案，写下只用于文字，不能用来表示刻出一只鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下表示把东西记录在纸上，与“购物单上”和“要买的东西”搭配。"}, {"text": "煮熟", "is_correct": false, "explanation": "搭配：“煮熟”的对象是食物，不能用来指把东西记在购物单上。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”多用于衣物、鞋袜，不说穿上要买的东西。"}, {"text": "咬下", "is_correct": false, "explanation": "语义：咬下需要用嘴咬，购物单是纸，与“咬”的动作无法在纸上进行。"}], "explanations": {"写下": "正确。写下表示把东西记录在纸上，与“购物单上”和“要买的东西”搭配。", "煮熟": "搭配：“煮熟”的对象是食物，不能用来指把东西记在购物单上。", "穿上": "搭配：“穿上”多用于衣物、鞋袜，不说穿上要买的东西。", "咬下": "语义：咬下需要用嘴咬，购物单是纸，与“咬”的动作无法在纸上进行。"}, "sentence_index": 6, "correct_answer": "写下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在合同上写下了一个印章。", "explanation": "这里应该用〈盖下〉。盖下用于印章、戳记，写下用于文字，不能用来表示写一个印章。"}, {"text": "她把书包写下了。", "explanation": "这里应该用〈放下〉。放下指把东西放到某处，写下是用笔写字，书包不能被写下。"}, {"text": "这次比赛为她的未来写下了基础。", "explanation": "这里应该用〈打下〉。打下基础指奠定基础，写下只能用于记录文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写下着一个名字。", "corrected_sentence": "他写下了一个名字。", "error_description": "错误：“写下着”。“写下”表示动作已经完成，完成体应用“了”，“着”表示动作持续，不能与“写下”搭配，正确为“写下了一个名字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写下过过一首诗。", "corrected_sentence": "她写下过一首诗。", "error_description": "错误：“写下过过”。“过”只能出现一次，紧跟动词，应为“写下过一首诗”；正确句为“她写下过一首诗。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
