INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写出来；记录下来。", "primary_collocate": null, "pronunciation": "xiě xià", "ipa": "ɕjɛ˨˩˦ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他在日记里写下了今天的心情。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作家写下了自己的童年故事。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想写下这次旅行的感受。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在书里写下了一生的经历。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我愿意写下我们的故事。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写下了对朋友的感谢。", "target_word": "写下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在作文里写下了自己的梦想。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写下对这门课的看法。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士写下了病人每天的变化。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写下过很多关于家乡的诗。", "target_word": "写下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写下了", "label": "完成体"}, {"form": "写下过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把想法、经历等写出来记录下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88986, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下 xiě xià 指把想法或经历写出来、记录下来，即本词。"}, {"text": "卸下", "is_correct": false, "explanation": "卸下 xiè xià 与写下 xiě xià 第一个音节声调不同：xiè（第四声）与 xiě（第三声）不同，意思是把东西从身上或车上取下。"}, {"text": "解下", "is_correct": false, "explanation": "解下 jiě xià 与写下 xiě xià 声母不同：j 与 x 不同，声调相同，意思是解开后取下。"}, {"text": "西下", "is_correct": false, "explanation": "西下 xī xià 与写下 xiě xià 第一个音节声调不同：xī（第一声）与 xiě（第三声）不同，意思是（太阳）向西落下。"}, {"text": "歇下", "is_correct": false, "explanation": "歇下 xiē xià 与写下 xiě xià 第一个音节声调不同：xiē（第一声）与 xiě（第三声）不同，意思是停下来休息。"}], "explanations": {"写下": "正确。写下 xiě xià 指把想法或经历写出来、记录下来，即本词。", "卸下": "卸下 xiè xià 与写下 xiě xià 第一个音节声调不同：xiè（第四声）与 xiě（第三声）不同，意思是把东西从身上或车上取下。", "解下": "解下 jiě xià 与写下 xiě xià 声母不同：j 与 x 不同，声调相同，意思是解开后取下。", "西下": "西下 xī xià 与写下 xiě xià 第一个音节声调不同：xī（第一声）与 xiě（第三声）不同，意思是（太阳）向西落下。", "歇下": "歇下 xiē xià 与写下 xiě xià 第一个音节声调不同：xiē（第一声）与 xiě（第三声）不同，意思是停下来休息。"}, "sentence_index": null, "correct_answer": "写下"}, "level_3": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下表示把心情写出来记录下来，与“在日记里”和“今天的心情”搭配。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：唱出是发出声音，日记是文字记录，二者不相符。"}, {"text": "吃下", "is_correct": false, "explanation": "搭配：“吃下”的对象是食物，不说吃下心情。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”多用于衣物，不说穿上心情。"}], "explanations": {"写下": "正确。写下表示把心情写出来记录下来，与“在日记里”和“今天的心情”搭配。", "唱出": "语义：唱出是发出声音，日记是文字记录，二者不相符。", "吃下": "搭配：“吃下”的对象是食物，不说吃下心情。", "穿上": "搭配：“穿上”多用于衣物，不说穿上心情。"}, "sentence_index": 0, "correct_answer": "写下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用彩笔在墙上写下了一只小鸟。", "explanation": "这里应该用〈画下〉。画下指用笔画出图形，写下指把想法或经历写成文字，不能用来表示画一只小鸟。"}, {"text": "老人在书里写下了一张照片。", "explanation": "这里应该用〈留下〉。留下指把照片、纪念品保存下来，写下只用于文字，照片不能写下。"}, {"text": "老人在书里写下了一台冰箱。", "explanation": "这里应该用〈买下〉。买下指把东西买来，写下只能用于文字，冰箱不能被写下，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写下", "is_correct": true, "explanation": "正确。写下表示把梦想写出来记录下来，与“在作文里”和“自己的梦想”搭配。"}, {"text": "煮熟", "is_correct": false, "explanation": "搭配：“煮熟”的对象是食物，不说煮熟梦想。"}, {"text": "咬下", "is_correct": false, "explanation": "语义：咬下需要用嘴咬，作文是文字内容，二者无法对应。"}, {"text": "挂上", "is_correct": false, "explanation": "搭配：“挂上”用于物件悬挂，不说挂上梦想。"}], "explanations": {"写下": "正确。写下表示把梦想写出来记录下来，与“在作文里”和“自己的梦想”搭配。", "煮熟": "搭配：“煮熟”的对象是食物，不说煮熟梦想。", "咬下": "语义：咬下需要用嘴咬，作文是文字内容，二者无法对应。", "挂上": "搭配：“挂上”用于物件悬挂，不说挂上梦想。"}, "sentence_index": 6, "correct_answer": "写下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把行李写下了。", "explanation": "这里应该用〈放下〉。放下指把东西放到某处，写下是用笔写字，行李不能被写下。"}, {"text": "这件事为她的未来写下了基础。", "explanation": "这里应该用〈打下〉。打下基础指奠定基础，写下只能用于记录文字。"}, {"text": "她用相机写下了海边的风景。", "explanation": "这里应该用〈拍下〉。拍下指用相机把画面记录下来，写下是用文字记录，不能用相机写下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写下着一个心愿。", "corrected_sentence": "他写下了一个心愿。", "error_description": "错误：“写下着”。“写下”表示动作已经完成，完成体应用“了”，“着”表示动作持续，不能与“写下”搭配，正确为“写下了一个心愿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写下了过一篇很长的心得。", "corrected_sentence": "她写下过一篇很长的心得。", "error_description": "错误：“写下了过”。“了”与“过”不能同时用在同一动词后，“写下过”表示经历，应去掉“了”；正确句为“她写下过一篇很长的心得。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
