INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装有钱的红纸包或电子红包，用作礼物或奖励。", "primary_collocate": null, "pronunciation": "hóng bāo", "ipa": "xʊŋ˧˥ pau˥", "syllable_count": 2, "sentences": [{"text": "老板给每个员工发了一个红包。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友结婚，我包了一个红包。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司年会上，大家抢到了不少红包。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮了大忙，我送他一个红包表示感谢。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微信群里有人发红包，大家都在抢。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做得好，经理给了他一个红包。", "target_word": "红包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加婚礼要带红包。", "target_word": "红包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不好意思收这个红包。", "target_word": "红包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说不能收家长的红包。", "target_word": "红包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过节时，公司给员工发红包。", "target_word": "红包", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "微信红包", "label": "复合"}], "register": "口语", "sense_fingerprint": "装钱的红纸包或电子红包，用来送礼、道谢或奖励", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红包", "is_correct": true, "explanation": "红包是老板发给员工的奖励或礼物，符合“老板给每个员工发了”的语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是老师布置给学生的，老板不会发给员工。"}, {"text": "请假条", "is_correct": false, "explanation": "语义：请假条是员工写给老板的，不是老板发给员工的。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：邻居是住在附近的人，老板不能把邻居“发”给员工。"}], "explanations": {"红包": "红包是老板发给员工的奖励或礼物，符合“老板给每个员工发了”的语境。", "作业": "语义：作业是老师布置给学生的，老板不会发给员工。", "请假条": "语义：请假条是员工写给老板的，不是老板发给员工的。", "邻居": "语义：邻居是住在附近的人，老板不能把邻居“发”给员工。"}, "sentence_index": 0, "correct_answer": "红包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把茶叶装进红包送给他。", "explanation": "这里应该用〈礼盒〉。红包只能装钱，装茶叶要用礼盒。"}, {"text": "他用红包给花浇水。", "explanation": "这里应该用〈水壶〉。红包是装钱的红纸包，不能盛水，给花浇水要用水壶。"}, {"text": "他用红包写感谢信。", "explanation": "这里应该用〈信纸〉。红包是装钱的小袋子，不能当纸来写字，写感谢信要用信纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红包", "is_correct": true, "explanation": "红包是参加婚礼时带去的礼金小袋子，符合“参加婚礼要带”的语境。"}, {"text": "遗嘱", "is_correct": false, "explanation": "语义：遗嘱是人去世前留下的文字，婚礼上不会带。"}, {"text": "白菊", "is_correct": false, "explanation": "搭配：白菊多用于丧事，与婚礼的喜庆不搭配。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是看病的记录，与参加婚礼无关。"}], "explanations": {"红包": "红包是参加婚礼时带去的礼金小袋子，符合“参加婚礼要带”的语境。", "遗嘱": "语义：遗嘱是人去世前留下的文字，婚礼上不会带。", "白菊": "搭配：白菊多用于丧事，与婚礼的喜庆不搭配。", "病历": "语义：病历是看病的记录，与参加婚礼无关。"}, "sentence_index": 6, "correct_answer": "红包"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他背着红包去上学。", "explanation": "这里应该用〈书包〉。红包很小，只用来装钱，不能背着上学。"}, {"text": "下雨了，他撑着红包出门。", "explanation": "这里应该用〈雨伞〉。红包不能用来遮雨。"}, {"text": "他用红包开门。", "explanation": "这里应该用〈钥匙〉。红包不能用来开门，开门要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节日里，老板给我发了一个的红包。", "corrected_sentence": "节日里，老板给我发了一个红包。", "error_description": "数量短语“一个”后直接接名词，不加“的”，应说“一个红包”，这里多了“的”，写成“一个的红包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给新人包了一条红包。", "corrected_sentence": "我给新人包了一个红包。", "error_description": "量词错误：“红包”应搭配量词“个”，不说“条”。“条”多用于细长的东西，不用于红包。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
