INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在同一单位工作的人。", "primary_collocate": null, "pronunciation": "tóng shì", "ipa": "tʰʊŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我和同事一起吃午饭。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的新同事。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都在开会。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同事每天骑车上班。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的同事帮了我很多。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟同事关系很好。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同事今天生病了。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事送了我一本书。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是同事，也是朋友。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和同事去爬山了。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老同事", "label": "复合"}, {"form": "新同事", "label": "复合"}, {"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一单位工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同事", "is_correct": true, "explanation": "同事：在同一单位工作的人。"}, {"text": "同时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“同时”意思是同一时候，与“同事”不是同一个词。"}, {"text": "从事", "is_correct": false, "explanation": "cóng（第二声）与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。"}, {"text": "重视", "is_correct": false, "explanation": "chóng 与 tóng 声母不同（ch 与 t），“重视”意思是看重、认为重要。"}], "explanations": {"同事": "同事：在同一单位工作的人。", "同时": "shí（第二声）与 shì（第四声）声调不同，“同时”意思是同一时候，与“同事”不是同一个词。", "从事": "cóng（第二声）与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。", "重视": "chóng 与 tóng 声母不同（ch 与 t），“重视”意思是看重、认为重要。"}, "sentence_index": null, "correct_answer": "同事"}, "level_3": {"options": [{"text": "同事", "is_correct": true, "explanation": "“同事”指在同一单位工作的人，可以和“我”一起吃午饭。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”不是人，不能和“我”一起吃午饭。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：“筷子”是餐具，不能和人一起吃午饭。"}, {"text": "午餐", "is_correct": false, "explanation": "配价：“和”后要接一起吃饭的人，“午餐”是被吃的东西，不能作这个对象。"}], "explanations": {"同事": "“同事”指在同一单位工作的人，可以和“我”一起吃午饭。", "饭馆": "语义：“饭馆”不是人，不能和“我”一起吃午饭。", "筷子": "语义：“筷子”是餐具，不能和人一起吃午饭。", "午餐": "配价：“和”后要接一起吃饭的人，“午餐”是被吃的东西，不能作这个对象。"}, "sentence_index": 0, "correct_answer": "同事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同事每天给我做饭，我每个月付他工资。", "explanation": "这里应该用〈保姆〉。“同事”是同一单位工作的人，不会受我雇用、拿我的工资，给我做饭并领我工资的应是“保姆”。"}, {"text": "我的同事每天和我坐同一张课桌。", "explanation": "这里应该用〈同桌〉。“同桌”指坐同一张课桌的人，“同事”指同一单位工作的人。"}, {"text": "我的同事每天在院子里汪汪叫。", "explanation": "这里应该用〈小狗〉。“同事”指人，不会汪汪叫，这里应指小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同事", "is_correct": true, "explanation": "同事：在同一单位工作的人。"}, {"text": "从事", "is_correct": false, "explanation": "cóng 与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。"}, {"text": "红事", "is_correct": false, "explanation": "hóng（第二声）与 tóng 声母不同（h 与 t），“红事”意思是喜庆的事，如婚礼。"}, {"text": "农事", "is_correct": false, "explanation": "nóng 与 tóng 声母不同（n 与 t），“农事”意思是农业上的事情。"}], "explanations": {"同事": "同事：在同一单位工作的人。", "从事": "cóng 与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。", "红事": "hóng（第二声）与 tóng 声母不同（h 与 t），“红事”意思是喜庆的事，如婚礼。", "农事": "nóng 与 tóng 声母不同（n 与 t），“农事”意思是农业上的事情。"}, "sentence_index": null, "correct_answer": "同事"}, "level_3": {"options": [{"text": "同事", "is_correct": true, "explanation": "“同事”指人，会生病，符合“我……今天生病了”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会生病，“我……生病了”需要人作主语。"}, {"text": "车", "is_correct": false, "explanation": "语义：“我车”不能生病，这里的主语应是人。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“生病”的主语应是人或动植物，“工资”不能生病。"}], "explanations": {"同事": "“同事”指人，会生病，符合“我……今天生病了”。", "电脑": "语义：电脑不会生病，“我……生病了”需要人作主语。", "车": "语义：“我车”不能生病，这里的主语应是人。", "工资": "搭配：“生病”的主语应是人或动植物，“工资”不能生病。"}, "sentence_index": 6, "correct_answer": "同事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的同事把我养大了。", "explanation": "这里应该用〈父母〉。“同事”指同一单位工作的人，不会把我养大，抚养子女的应是“父母”。"}, {"text": "我的同事今年上小学了。", "explanation": "这里应该用〈孩子〉。“同事”指在单位上班的人，不会去上小学，说“上小学”的应是“孩子”。"}, {"text": "我的同事今年两岁，还不会说话。", "explanation": "这里应该用〈宝宝〉。“同事”指上班的成年人，两岁还不会说话的应是“宝宝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三个同事们一起去看了电影。", "corrected_sentence": "这三个同事一起去看了电影。", "error_description": "错误形式：“三个同事们”。“们”不能跟在数量词后面。正确形式：“这三个同事”，去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司新来了一只同事。", "corrected_sentence": "我们公司新来了一位同事。", "error_description": "错误形式：“一只同事”。“同事”指人，量词应用“位”或“个”，不用“只”（“只”多用于动物）。正确形式：“一位同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
