INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专政是掌权者用强力控制别人的统治方式。", "primary_collocate": null, "pronunciation": "zhuān zhèng", "ipa": "ʈʂwan˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国王靠专政统治国家。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专政让人民没有说话的自由。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家长期实行专政。", "target_word": "专政", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在专政下，人们不敢说真话。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老百姓不喜欢专政，他们想要自由。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位将军掌权以后，开始实行专政。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里讲了很多国家的专政。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专政常常用警察和军队来管人。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他反对专政，所以离开了自己的国家。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专政结束以后，大家的生活慢慢变好了。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "專政", "label": "繁体"}, {"form": "无产阶级专政", "label": "复合"}, {"form": "人民民主专政", "label": "复合"}], "register": "书面", "sense_fingerprint": "掌权者用强力控制别人的统治方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专政", "is_correct": true, "explanation": "「专政」指掌权者用强力控制别人的统治方式，与“靠……统治国家”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：「睡觉」不是统治手段，「靠睡觉统治国家」不成立。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：「统治国家」的手段不是游戏，「靠游戏统治国家」不搭配。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：祝福不是统治手段，「靠祝福统治国家」与句意不符。"}], "explanations": {"专政": "「专政」指掌权者用强力控制别人的统治方式，与“靠……统治国家”的语境相符。", "睡觉": "搭配：「睡觉」不是统治手段，「靠睡觉统治国家」不成立。", "游戏": "搭配：「统治国家」的手段不是游戏，「靠游戏统治国家」不搭配。", "祝福": "语义：祝福不是统治手段，「靠祝福统治国家」与句意不符。"}, "sentence_index": 0, "correct_answer": "专政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的专政是唱歌。", "explanation": "这里应该用〈专长〉。专政指统治方式，「专长」才指擅长的技能，不能说「她的专政是唱歌」。"}, {"text": "这次演出的专政很精彩。", "explanation": "这里应该用〈节目〉。专政指统治方式，不能用来指演出的内容。"}, {"text": "他的专政是医学。", "explanation": "这里应该用〈专业〉。专政指统治方式，「专业」才表示专门学习或工作的领域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专政", "is_correct": true, "explanation": "「专政」指统治方式，与“历史书里讲了很多国家的……”的语境相符。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：「讲」的宾语是事件、道理等，「国家的心跳」不能被「讲」，句意不通。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：国家没有「牙齿」，「历史书里讲了很多国家的牙齿」句意荒谬。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：「讲」的宾语是事件、道理等，不能说「讲香味」。"}], "explanations": {"专政": "「专政」指统治方式，与“历史书里讲了很多国家的……”的语境相符。", "心跳": "搭配：「讲」的宾语是事件、道理等，「国家的心跳」不能被「讲」，句意不通。", "牙齿": "语义：国家没有「牙齿」，「历史书里讲了很多国家的牙齿」句意荒谬。", "香味": "搭配：「讲」的宾语是事件、道理等，不能说「讲香味」。"}, "sentence_index": 6, "correct_answer": "专政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去商店买了一斤专政带回家。", "explanation": "这里应该用〈东西〉。专政指统治方式，不是可以用「斤」称量、拿到商店去买的物品。"}, {"text": "他吃了一碗专政，觉得很饱。", "explanation": "这里应该用〈饭〉。专政指统治方式，不是可以用「碗」盛装、拿来吃的食物。"}, {"text": "这首歌的专政很动听。", "explanation": "这里应该用〈旋律〉。专政指统治方式，不能用来形容歌曲好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家经历过一条很长的专政。", "corrected_sentence": "那个国家经历过一段很长的专政。", "error_description": "错误形式：「一条」。正确形式：「一段」。「专政」指一段时间里的统治，量词应该用「段」，不能用「条」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以前，那个国家实行着过专政。", "corrected_sentence": "以前，那个国家实行过专政。", "error_description": "错误形式：「实行着过专政」。正确形式：「实行过专政」。「着」表示动作或状态的持续，「过」表示曾经的经历，二者意义冲突，不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
