INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个阶级对敌对阶级采取的强制统治。", "primary_collocate": null, "pronunciation": "zhuān zhèng", "ipa": "ʈʂwan˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "无产阶级专政是一种国家制度。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，专政是一个阶级对另一个阶级的统治。", "target_word": "专政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上老师讲了什么是人民民主专政。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专政的对象是敌对阶级。", "target_word": "专政", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书讲阶级和专政的关系。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史课上，我们学习了无产阶级专政。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专政是国家对敌对力量的强制统治。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我专政是什么意思。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的宪法写着人民民主专政。", "target_word": "专政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写文章分析了阶级专政的特点。", "target_word": "专政", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "專政", "label": "繁体"}, {"form": "无产阶级专政", "label": "复合"}, {"form": "人民民主专政", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个阶级对敌对阶级的强制统治（政治术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专政", "is_correct": true, "explanation": "「专政」指一个阶级对敌对阶级的强制统治，是一种国家制度，与句意相符。"}, {"text": "革命", "is_correct": false, "explanation": "语义：「革命」是行动或运动，不是国家制度，句意不通。"}, {"text": "语文", "is_correct": false, "explanation": "搭配：「无产阶级」不能修饰学科名称「语文」，搭配不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是学科，不是国家制度，句意不通。"}], "explanations": {"专政": "「专政」指一个阶级对敌对阶级的强制统治，是一种国家制度，与句意相符。", "革命": "语义：「革命」是行动或运动，不是国家制度，句意不通。", "语文": "搭配：「无产阶级」不能修饰学科名称「语文」，搭配不通。", "数学": "语义：「数学」是学科，不是国家制度，句意不通。"}, "sentence_index": 0, "correct_answer": "专政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的专政是数学。", "explanation": "这里应该用〈专业〉。专政表示阶级间的强制统治，「专业」才指专门学习或工作的领域。"}, {"text": "老师的专政很清楚，同学们都听懂了。", "explanation": "这里应该用〈讲解〉。专政指阶级间的强制统治，不能用来形容讲课的清楚程度。"}, {"text": "他去超市买了一斤专政带回家。", "explanation": "这里应该用〈东西〉。专政指统治方式，不是可以用「斤」称量、拿到超市去买的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专政", "is_correct": true, "explanation": "「专政」指一个阶级对敌对力量的强制统治，与句中的定义相符。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」不是强制统治，与「强制统治敌对力量」的定义相反。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：「友谊」与「对敌对力量的强制统治」不搭配，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是强制统治，句子的定义与「天气」毫无关系。"}], "explanations": {"专政": "「专政」指一个阶级对敌对力量的强制统治，与句中的定义相符。", "民主": "语义：「民主」不是强制统治，与「强制统治敌对力量」的定义相反。", "友谊": "搭配：「友谊」与「对敌对力量的强制统治」不搭配，句子不成立。", "天气": "语义：「天气」不是强制统治，句子的定义与「天气」毫无关系。"}, "sentence_index": 6, "correct_answer": "专政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喝了一碗专政，觉得很饱。", "explanation": "这里应该用〈汤〉。专政表示阶级间的强制统治，不是可以用「碗」盛装、拿来喝的东西。"}, {"text": "这首歌的专政很动听。", "explanation": "这里应该用〈旋律〉。专政指强制统治，不能用来形容歌曲好听。"}, {"text": "他的专政一会儿跑、一会儿跳，很有意思。", "explanation": "这里的问题在于专政。专政指阶级间的强制统治，不是能跑能跳的东西；应当说「小狗」之类的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人民民主专政是这个国家的一条根本制度。", "corrected_sentence": "人民民主专政是这个国家的一项根本制度。", "error_description": "错误形式：「一条」。正确形式：「一项」。「专政」作为国家的根本制度，量词应该用「项」，不能用「条」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很久以前，他们的国家实行着过专政。", "corrected_sentence": "很久以前，他们的国家实行过专政。", "error_description": "错误形式：「实行着过专政」。正确形式：「实行过专政」。「着」表示动作或状态的持续，「过」表示曾经的经历，二者意义冲突，不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
