INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "红旗是红颜色的旗子。", "primary_collocate": null, "pronunciation": "hóng qí", "ipa": "xʊŋ˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "学校门口挂着一面红旗。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一面小红旗。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红旗在风里一直飘。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们挥着红旗跑过来。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两面红旗送给弟弟。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员在终点线旁边挥动着红旗。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游举着红旗，大家跟着他走。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室前面插着一面红旗。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的红旗表示不能下水。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把红旗挂在了窗户外面。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "紅旗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "红颜色的旗子，具体的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红旗", "is_correct": true, "explanation": "正确。红旗是红颜色的旗子，可以挂在学校门口。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：「挂着」用于旗子、画等物品，不说「挂着一面墙」。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌不能挂在门口，与「挂着」的语境矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头一般不能挂在门口，「挂着一面石头」不成立。"}], "explanations": {"红旗": "正确。红旗是红颜色的旗子，可以挂在学校门口。", "墙": "搭配：「挂着」用于旗子、画等物品，不说「挂着一面墙」。", "课桌": "语义：课桌不能挂在门口，与「挂着」的语境矛盾。", "石头": "语义：石头一般不能挂在门口，「挂着一面石头」不成立。"}, "sentence_index": 0, "correct_answer": "红旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用红旗缝了一面旗子。", "explanation": "这里应该用〈红布〉。红旗已是做成的旗子，不能当缝制旗子的布料。"}, {"text": "他买了一本红旗。", "explanation": "这里应该用〈面〉。「本」用于书册，旗子要用「面」。"}, {"text": "他拿红旗擦了擦窗户。", "explanation": "这里应该用〈抹布〉。红旗是旗子，不能拿来擦窗户，擦窗户要用抹布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红旗", "is_correct": true, "explanation": "正确。导游举着红旗，大家跟着他走，是常见的情景。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：「举着」多用于手持的小物件，不说「举着大楼」。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：导游不能举着月亮，句子与常识矛盾。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不便手持举着走，「导游举着钢琴」不符合常理。"}], "explanations": {"红旗": "正确。导游举着红旗，大家跟着他走，是常见的情景。", "大楼": "搭配：「举着」多用于手持的小物件，不说「举着大楼」。", "月亮": "语义：导游不能举着月亮，句子与常识矛盾。", "钢琴": "语义：钢琴不便手持举着走，「导游举着钢琴」不符合常理。"}, "sentence_index": 6, "correct_answer": "红旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用红旗做了一条裙子。", "explanation": "这里应该用〈红绸〉。红旗已是做成的旗子，不能当做衣服的材料。"}, {"text": "她买了两根红旗。", "explanation": "这里应该用〈面〉。「根」用于细长的东西，旗子要用「面」。"}, {"text": "她用红旗剪了一个小动物。", "explanation": "这里应该用〈红纸〉。红旗是做成的旗子，不能当剪纸的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "操场中央飘着一个红旗。", "corrected_sentence": "操场中央飘着一面红旗。", "error_description": "「红旗」是旗子，量词应用「面」，不能用「个」。正确：一面红旗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广场上的红旗们在风里飘着。", "corrected_sentence": "广场上的红旗在风里飘着。", "error_description": "「红旗」是物品，不能加「们」表示复数。正确：广场上的红旗在风里飘着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
