INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "红色的旗帜，常用作革命或胜利的象征。", "primary_collocate": null, "pronunciation": "hóng qí", "ipa": "xʊŋ˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "红旗是胜利的象征。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，大家举起了红旗。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红旗代表革命和胜利。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上的红旗象征着国家的力量。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把红旗插在山顶上，表示胜利。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，红旗象征着革命精神。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红旗在风中飘着，大家都很激动。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红旗插上山头，战士们欢呼起来。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们心中的红旗，就是胜利的希望。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前，红旗是革命队伍的标志。", "target_word": "红旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "紅旗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作为革命或胜利象征的红旗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红旗", "is_correct": true, "explanation": "正确。红旗在此指象征革命或胜利的旗帜。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有象征胜利的意义，「桌子是胜利的象征」不成立。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不具有象征革命或胜利的意义，句子不成立。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：「是……的象征」要求有象征义的名词，「海水」一般不作象征。"}], "explanations": {"红旗": "正确。红旗在此指象征革命或胜利的旗帜。", "桌子": "语义：桌子没有象征胜利的意义，「桌子是胜利的象征」不成立。", "饺子": "语义：饺子不具有象征革命或胜利的意义，句子不成立。", "海水": "搭配：「是……的象征」要求有象征义的名词，「海水」一般不作象征。"}, "sentence_index": 0, "correct_answer": "红旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿着一件红旗的外套去开会。", "explanation": "这里应该用〈红色〉。红旗是名词，指旗子，不能当颜色来修饰外套，表示颜色要说红色。"}, {"text": "他每天早上用红旗煮粥。", "explanation": "这里应该用〈大米〉。红旗是旗子，不能拿来煮粥。"}, {"text": "他买了一只红旗送给朋友。", "explanation": "这里应该用〈面〉。旗子的量词是「面」，「只」多用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红旗", "is_correct": true, "explanation": "正确。红旗在风中飘着，大家激动，指的是象征胜利的旗帜。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会在风中飘着，句子不成立。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭不会在风中飘着，与语境矛盾。"}, {"text": "事业", "is_correct": false, "explanation": "搭配：「飘着」多用于旗帜、衣物，不说「事业在风中飘着」。"}], "explanations": {"红旗": "正确。红旗在风中飘着，大家激动，指的是象征胜利的旗帜。", "面包": "语义：面包不会在风中飘着，句子不成立。", "煤炭": "语义：煤炭不会在风中飘着，与语境矛盾。", "事业": "搭配：「飘着」多用于旗帜、衣物，不说「事业在风中飘着」。"}, "sentence_index": 6, "correct_answer": "红旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用红旗做了一件衣服。", "explanation": "这里应该用〈红布〉。红旗已是做成的旗子，不能当做衣服的材料。"}, {"text": "他在厨房里用红旗擦桌子。", "explanation": "这里应该用〈抹布〉。红旗是旗子，不能拿来擦桌子，擦桌子要用抹布。"}, {"text": "他把红旗切成丝，放进锅里炒。", "explanation": "这里应该用〈红椒〉。红旗是旗子，不是食材，不能切来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战士们把一个红旗插上了山顶。", "corrected_sentence": "战士们把一面红旗插上了山顶。", "error_description": "「红旗」是旗子，量词应用「面」，不能用「个」。正确：一面红旗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在老一辈人心里，红旗在革命的标志。", "corrected_sentence": "在老一辈人心里，红旗是革命的标志。", "error_description": "「红旗」作主语时，判断句应用「是」，不能用「在」（「在」表示所在）。正确：红旗是革命的标志。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
