INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88997, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "尚无是到现在还没有。", "primary_collocate": null, "pronunciation": "shàng wú", "ipa": "ʂaŋ˥˩ u˧˥", "syllable_count": 2, "sentences": [{"text": "小区门口尚无超市。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结果尚无消息。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司尚无招聘计划。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前尚无人报名参加。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题尚无答案。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业三年了，尚无稳定的工作。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城尚无机场，旅客只能坐火车。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，尚无证据说明这种药有害。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子尚无名字，父母还在商量。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校尚无足球场，学生在操场上踢球。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尚無", "label": "繁体"}], "register": "书面", "sense_fingerprint": "直到现在仍然没有某事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚无", "is_correct": true, "explanation": "「尚无」表示直到现在仍然没有，与“小区门口”“超市”的语境相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：「举办」的宾语是活动、展览等，不能说「举办超市」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：超市是场所，不能被吃，「小区门口吃超市」句意荒谬。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：「游览」的对象是景点或名胜，超市不是游览的地方。"}], "explanations": {"尚无": "「尚无」表示直到现在仍然没有，与“小区门口”“超市”的语境相符。", "举办": "搭配：「举办」的宾语是活动、展览等，不能说「举办超市」。", "吃": "语义：超市是场所，不能被吃，「小区门口吃超市」句意荒谬。", "游览": "搭配：「游览」的对象是景点或名胜，超市不是游览的地方。"}, "sentence_index": 0, "correct_answer": "尚无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街尚无便利店，居民却天天去这条街上的便利店买东西。", "explanation": "这里的问题在于〈尚无〉。尚无表示到目前为止没有，后句却说这条街上有便利店，两句矛盾；已经有便利店时应说「有便利店」。"}, {"text": "这座城市早就尚无机场，大家出门都很方便。", "explanation": "这里应该用〈早就没有〉。尚无表示到目前为止还没有，与「早就」表示很久以前已经如此的语义矛盾。"}, {"text": "这个小区永远尚无超市。", "explanation": "这里应该用〈永远没有〉。尚无表示目前还没有、将来可能有，不能与「永远」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚无", "is_correct": true, "explanation": "「尚无」表示没有，与“机场”“旅客只能坐火车”的语境相符，说明这座城市没有机场。"}, {"text": "乘坐", "is_correct": false, "explanation": "搭配：「乘坐」的宾语是交通工具，不能说「乘坐机场」。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：「发表」的宾语是文章、言论等，不能说「发表机场」。"}, {"text": "唱", "is_correct": false, "explanation": "语义：机场不能被唱，「这座小城唱机场」句意荒谬。"}], "explanations": {"尚无": "「尚无」表示没有，与“机场”“旅客只能坐火车”的语境相符，说明这座城市没有机场。", "乘坐": "搭配：「乘坐」的宾语是交通工具，不能说「乘坐机场」。", "发表": "搭配：「发表」的宾语是文章、言论等，不能说「发表机场」。", "唱": "语义：机场不能被唱，「这座小城唱机场」句意荒谬。"}, "sentence_index": 6, "correct_answer": "尚无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校尚无足球场，但是同学们每天都在足球场上踢球。", "explanation": "这里的问题在于〈尚无〉。尚无表示到目前为止没有，后句说同学们天天在足球场上踢球，两句矛盾；应当说「没有足球场」。"}, {"text": "学校早就尚无足球场，大家都很失望。", "explanation": "这里应该用〈一直没有〉。尚无表示到目前为止还没有，与「早就」表示很久以前已经如此的语义矛盾。"}, {"text": "学校尚无足球场，足球场却在去年就修好了。", "explanation": "这里的问题在于〈尚无〉。尚无表示到目前为止没有，后句说去年就修好了足球场，两句矛盾；应当说「去年还没有」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街尚无了便利店。", "corrected_sentence": "这条街尚无便利店。", "error_description": "错误形式：「尚无了」。正确形式：「尚无」。「尚无」已表示到目前为止没有，后面不能加表示完成的「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子没尚无银行。", "corrected_sentence": "这个村子尚无银行。", "error_description": "错误形式：「没尚无」。正确形式：「尚无」。「尚无」本身已表示到目前为止没有，前面不能再加否定词「没」，否则形成多余的重复否定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
