INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "还没有；至今没有。", "primary_collocate": null, "pronunciation": "shàng wú", "ipa": "ʂaŋ˥˩ u˧˥", "syllable_count": 2, "sentences": [{"text": "这种病尚无特效药。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前尚无人知道事情的真相。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这件事，警方尚无新的消息。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市尚无地铁。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尚无女朋友，家人很着急。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事尚无结论，请大家再等等。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们尚无足够的钱买房子。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故中，尚无人员伤亡。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术尚无成熟的产品。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里尚无医院，看病要去镇上。", "target_word": "尚无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尚無", "label": "繁体"}], "register": "书面", "sense_fingerprint": "到目前为止还不存在、还没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚无", "is_correct": true, "explanation": "「尚无」表示到目前为止还没有，与“这种病”“特效药”搭配，符合句意。"}, {"text": "研制", "is_correct": false, "explanation": "搭配：「研制」的施事是人或机构，「这种病研制特效药」不通。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：「拥有」要求能占有事物的主体，疾病不能拥有药物。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」是人的创造行为，疾病不能发明特效药。"}], "explanations": {"尚无": "「尚无」表示到目前为止还没有，与“这种病”“特效药”搭配，符合句意。", "研制": "搭配：「研制」的施事是人或机构，「这种病研制特效药」不通。", "拥有": "语义：「拥有」要求能占有事物的主体，疾病不能拥有药物。", "发明": "语义：「发明」是人的创造行为，疾病不能发明特效药。"}, "sentence_index": 0, "correct_answer": "尚无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他尚无女朋友，可是他的女朋友天天陪他吃饭。", "explanation": "这里的问题在于〈尚无〉。尚无表示到目前为止没有，后句说女朋友天天陪他，两句自相矛盾；已经有女朋友时不能用尚无。"}, {"text": "这次比赛的结果早就尚无，大家都在等。", "explanation": "这里应该用〈还没有〉。尚无表示到目前为止还没有，与「早就」表示很久以前已经如此的语义矛盾。"}, {"text": "警方尚无新消息，但他们刚刚发布了新消息。", "explanation": "这里的问题在于〈尚无〉。尚无表示目前没有消息，后句说刚刚发布了消息，两句矛盾；应当说「没有新消息」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚无", "is_correct": true, "explanation": "「尚无」表示还没有，与“足够的钱”“买房子”的语境相符，表示缺少所需的钱。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：「参加」的宾语是活动或组织，不能说「参加足够的钱」。"}, {"text": "反对", "is_correct": false, "explanation": "语义：「反对」的对象是主张或政策，「反对足够的钱」句意荒谬。"}, {"text": "出租", "is_correct": false, "explanation": "搭配：「出租」的对象是房屋、车辆等物品，不能出租「钱」。"}], "explanations": {"尚无": "「尚无」表示还没有，与“足够的钱”“买房子”的语境相符，表示缺少所需的钱。", "参加": "搭配：「参加」的宾语是活动或组织，不能说「参加足够的钱」。", "反对": "语义：「反对」的对象是主张或政策，「反对足够的钱」句意荒谬。", "出租": "搭配：「出租」的对象是房屋、车辆等物品，不能出租「钱」。"}, "sentence_index": 6, "correct_answer": "尚无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村永远尚无医院，居民只能去城里看病。", "explanation": "这里应该用〈永远没有〉。尚无表示目前还没有、将来可能有，不能与「永远」搭配。"}, {"text": "这个村子尚无医院，村里的人却天天在医院里看病。", "explanation": "这里的问题在于〈尚无〉。尚无表示到目前为止没有，后句说大家天天在医院看病，两句矛盾；应当说「没有医院」。"}, {"text": "村里已经尚无医院，大家都很着急。", "explanation": "这里应该用〈已经有〉。尚无表示到目前为止还没有，与「已经」的完成义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区尚无了游泳池。", "corrected_sentence": "我们小区尚无游泳池。", "error_description": "错误形式：「尚无了」。正确形式：「尚无」。「尚无」本身已表示到目前为止没有，后面不能再加表示完成的「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小镇没尚无火车站。", "corrected_sentence": "这座小镇尚无火车站。", "error_description": "错误形式：「没尚无」。正确形式：「尚无」。「尚无」本身已表示到目前为止没有，前面不能再加否定词「没」，否则形成多余的重复否定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
